# ── Inline Hybrid Cache (Redis + In-Memory) ──────────────────────────
import time as _time
_CACHE_LOCK = threading.RLock()
_MEM_CACHE: dict = {}

try:
    import redis as _redis_mod
except Exception:
    _redis_mod = None  # type: ignore

_REDIS_URL = os.getenv("REDIS_URL", "").strip()
_redis_client = None

def _get_redis():
    global _redis_client
    if _redis_client is not None:
        return _redis_client if _redis_client else None
    if not _redis_mod or not _REDIS_URL:
        _redis_client = False
        return None
    try:
        r = _redis_mod.from_url(_REDIS_URL, decode_responses=True,
                                socket_connect_timeout=5, socket_timeout=5,
                                socket_keepalive=True, health_check_interval=30)
        r.ping()
        _redis_client = r
        print(f"[cache] Redis connected: {_REDIS_URL.rsplit('@', 1)[-1]}")
        return r
    except Exception as e:
        print(f"[cache] Redis unavailable ({e}). Using in-memory fallback.")
        _redis_client = False
        return None

_CACHE_STATS = {"hits": 0, "misses": 0, "last_ops": []}

def _cache_stat(op: str, key: str, source: str = ""):
    if op in ("HIT", "MISS"):
        _CACHE_STATS["hits" if op == "HIT" else "misses"] += 1
    _CACHE_STATS["last_ops"].append({"t": datetime.now().isoformat(), "op": op, "key": key[:80], "src": source})
    if len(_CACHE_STATS["last_ops"]) > 200:
        _CACHE_STATS["last_ops"] = _CACHE_STATS["last_ops"][-100:]

def cache_get(key: str):
    global _redis_client
    r = _get_redis()
    if r:
        try:
            v = r.get(key)
            if v:
                print(f"[cache] HIT  {key} (redis)")
                _cache_stat("HIT", key, "redis")
                return json.loads(v)
        except Exception as e:
            print(f"[cache] Redis get error: {e}")
            _redis_client = None
    with _CACHE_LOCK:
        entry = _MEM_CACHE.get(key)
        if entry and _time.time() <= entry["expires"]:
            print(f"[cache] HIT  {key} (memory)")
            _cache_stat("HIT", key, "memory")
            return entry["data"]
        _MEM_CACHE.pop(key, None)
    print(f"[cache] MISS {key}")
    _cache_stat("MISS", key, "")
    return None

def cache_set(key: str, data, ttl: int = 10):
    global _redis_client
    r = _get_redis()
    if r:
        try:
            r.setex(key, ttl, json.dumps(data, ensure_ascii=False))
            print(f"[cache] SET  {key} (redis, ttl={ttl}s)")
            return
        except Exception as e:
            print(f"[cache] Redis set error: {e}")
            _redis_client = None
    with _CACHE_LOCK:
        _MEM_CACHE[key] = {"data": data, "expires": _time.time() + ttl}
    print(f"[cache] SET  {key} (memory, ttl={ttl}s)")

def cache_delete(key: str):
    global _redis_client
    r = _get_redis()
    if r:
        try:
            r.delete(key)
        except Exception:
            _redis_client = None
    with _CACHE_LOCK:
        _MEM_CACHE.pop(key, None)

def cache_delete_pattern(pattern: str):
    global _redis_client
    r = _get_redis()
    if r:
        try:
            for k in r.scan_iter(match=pattern):
                r.delete(k)
        except Exception:
            _redis_client = None
    prefix = pattern.rstrip("*")
    with _CACHE_LOCK:
        for k in list(_MEM_CACHE.keys()):
            if k.startswith(prefix):
                _MEM_CACHE.pop(k, None)

def cache_invalidate_restaurant():
    """Clear restaurant caches after mutations (safe with Redis shared across workers)."""
    try:
        cache_delete_pattern("mat3am:restaurant:operational-snapshot:*")
        cache_delete_pattern("mat3am:restaurant:order-taker-bootstrap:*")
        cache_delete_pattern("mat3am:restaurant:table-sessions:*")
        cache_delete_pattern("mat3am:restaurant:tables")
        cache_delete_pattern("mat3am:restaurant:products:*")
    except Exception:
        pass


def _product_image_url(card_guide: str) -> Optional[str]:
    """يُنتج رابط بيانات (data URL) للصورة من ذاكرة التخزين المؤقت العامة."""
    norm = str(card_guide or "").strip().upper().replace("{", "").replace("}", "")
    key = f"mat3am:product:image:{norm}"
    cached = cache_get(key)
    if cached is not None:
        return cached
    conn = get_connection()
    if not conn:
        return None
    try:
        cursor = conn.cursor()
        cursor.execute(
            "SELECT TOP 1 CardImage FROM TBL007 WHERE CardGuide = CAST(? AS uniqueidentifier)",
            (str(card_guide).strip().upper(),),
        )
        row = cursor.fetchone()
        if not row or row[0] is None:
            return None
        blob = row[0]
        try:
            data = bytes(blob)
        except Exception:
            data = blob
        ctype = "application/octet-stream"
        if data.startswith(b"\xFF\xD8\xFF"):
            ctype = "image/jpeg"
        elif data.startswith(b"\x89PNG\r\n\x1a\n"):
            ctype = "image/png"
        elif data.startswith(b"GIF8"):
            ctype = "image/gif"
        b64 = base64.b64encode(data).decode("ascii")
        url = f"data:{ctype};base64,{b64}"
        cache_set(key, url, ttl=3600)
        return url
    except Exception:
        return None
    finally:
        try:
            conn.close()
        except Exception:
            pass

