def _image_url_db_first(db_val, manifest_val, fallback: str) -> str:
    """عند تحميل المنيو: TBL006/TBL007 أولاً، ثم group_images.json / product_images.json."""
    d = str(db_val or "").strip()
    if d:
        return d
    m = str(manifest_val or "").strip()
    if m:
        return m
    return fallback


def _ensure_menu_tables(cursor) -> None:
    cursor.execute(
        """
        IF OBJECT_ID('dbo.TBL006','U') IS NULL
        BEGIN
            CREATE TABLE dbo.TBL006(
                CardGuide uniqueidentifier NOT NULL PRIMARY KEY,
                GroupName nvarchar(255) NULL,
                LatinName nvarchar(255) NULL,
                CardImage varbinary(max) NULL,
                GroupImageUrl nvarchar(500) NULL
            );
        END
        """
    )
    cursor.execute(
        """
        IF OBJECT_ID('dbo.TBL007','U') IS NULL
        BEGIN
            CREATE TABLE dbo.TBL007(
                CardGuide uniqueidentifier NOT NULL PRIMARY KEY,
                ProductName nvarchar(255) NULL,
                LatinName nvarchar(255) NULL,
                GroupGuid uniqueidentifier NULL,
                AgentPrice decimal(18,2) NULL,
                NotActive bit NOT NULL DEFAULT(0),
                CardImage varbinary(max) NULL,
                ProductImageUrl nvarchar(500) NULL
            );
        END
        """
    )
    cursor.execute(
        """
        IF COL_LENGTH('dbo.TBL006','CardImage') IS NULL
            ALTER TABLE dbo.TBL006 ADD CardImage varbinary(max) NULL;
        IF COL_LENGTH('dbo.TBL006','GroupImageUrl') IS NULL
            ALTER TABLE dbo.TBL006 ADD GroupImageUrl nvarchar(500) NULL;
        IF COL_LENGTH('dbo.TBL007','CardImage') IS NULL
            ALTER TABLE dbo.TBL007 ADD CardImage varbinary(max) NULL;
        IF COL_LENGTH('dbo.TBL007','ProductImageUrl') IS NULL
            ALTER TABLE dbo.TBL007 ADD ProductImageUrl nvarchar(500) NULL;
        """
    )


# TBL006: مجموعة «طلبات سريعة» — المنتجات عبر TBL007.GroupGuid تظهر في Speed Order
KDS_SPEED_ORDER_GROUP_NAME = "شيشة وطلبات سريعة"
_kds_speed_group_guid: Optional[str] = None
_kds_speed_group_resolved: bool = False


def _kds_invalidate_speed_group_cache() -> None:
    global _kds_speed_group_guid, _kds_speed_group_resolved
    _kds_speed_group_guid = None
    _kds_speed_group_resolved = False


def _ensure_speed_order_product_group(cursor) -> None:
    _ensure_menu_tables(cursor)
    cursor.execute(
        """
        IF NOT EXISTS (
            SELECT 1 FROM dbo.TBL006
            WHERE RTRIM(LTRIM(ISNULL(GroupName, N''))) = ?
        )
        BEGIN
            INSERT INTO dbo.TBL006 (CardGuide, GroupName) VALUES (NEWID(), ?)
        END
        """,
        (KDS_SPEED_ORDER_GROUP_NAME, KDS_SPEED_ORDER_GROUP_NAME),
    )
    _kds_invalidate_speed_group_cache()


def _kds_resolve_speed_group_guid_for_cursor(cursor) -> Optional[str]:
    global _kds_speed_group_guid, _kds_speed_group_resolved
    if _kds_speed_group_resolved:
        return _kds_speed_group_guid
    _kds_speed_group_resolved = True
    _ensure_menu_tables(cursor)
    try:
        cursor.execute(
            """
            SELECT TOP 1 CardGuide FROM dbo.TBL006
            WHERE RTRIM(LTRIM(ISNULL(GroupName, N''))) = ?
            """,
            (KDS_SPEED_ORDER_GROUP_NAME,),
        )
        row = cursor.fetchone()
        _kds_speed_group_guid = str(row[0]) if row and row[0] else None
    except Exception:
        _kds_speed_group_guid = None
    return _kds_speed_group_guid


def _kds_batch_product_group_guids(cursor, product_guides: set) -> dict:
    out: dict = {}
    if not product_guides:
        return out
    guids = [str(p or "").strip() for p in product_guides if str(p or "").strip()]
    if not guids:
        return out
    ph = ",".join("?" * len(guids))
    try:
        cursor.execute(
            f"SELECT CardGuide, GroupGuid FROM dbo.TBL007 WHERE CardGuide IN ({ph})",
            tuple(guids),
        )
        for r in cursor.fetchall() or []:
            if r and r[0] and r[1] is not None:
                cg = str(r[0])
                gg = str(r[1])
                out[cg.lower()] = gg
                out[cg] = gg
    except Exception:
        pass
    return out


def _kds_item_is_speed_line(it: dict, gmap: dict, speed_guid: Optional[str]) -> bool:
    if not speed_guid or not isinstance(it, dict):
        return False
    pg = str(it.get("productGuide") or "").strip()
    if not pg:
        return False
    gg = gmap.get(pg.lower()) or gmap.get(pg)
    if not gg:
        return False
    a = str(gg).replace("{", "").replace("}", "").lower()
    b = str(speed_guid).replace("{", "").replace("}", "").lower()
    return a == b


def _enrich_invoice_lines_from_menu(cursor, lines: list) -> list:
    cache: dict[str, dict] = {}
    out = []
    for ln in lines:
        if not isinstance(ln, dict):
            continue
        pg = str(ln.get("ProductGuide") or "").strip()
        x = dict(ln)
        if pg:
            rec = _menu_product_pricing_record(cursor, pg, cache)
            menu_name = str(rec.get("name") or "")
            if not str(x.get("ProductName") or "").strip() and menu_name:
                x["ProductName"] = menu_name
            if float(x.get("UnitPrice") or 0) <= 0:
                resolved, _src = _product_effective_unit_price(cursor, pg, cache)
                if resolved > 0:
                    qty = float(x.get("Quantity") or 0)
                    x["UnitPrice"] = resolved
                    x["TotalValue"] = round(resolved * qty, 4)
        out.append(x)
    return out


def _historical_product_unit_price(cursor, product_guide: str) -> Optional[float]:
    pg = str(product_guide or "").strip()
    if not pg:
        return None
    try:
        cursor.execute(
            """
            SELECT TOP 1 TotalValue, Quantity
            FROM dbo.TBL023
            WHERE ProductGuide = CAST(? AS uniqueidentifier)
              AND ISNULL(TotalValue, 0) > 0
              AND ISNULL(Quantity, 0) > 0
            ORDER BY ID DESC
            """,
            (pg,),
        )
        row = cursor.fetchone()
        if row:
            qty = float(row[1] or 0)
            if qty > 0:
                return round(float(row[0] or 0) / qty, 2)
    except Exception:
        pass
    return None


def _product_effective_unit_price(cursor, product_guide: str, cache: Optional[dict] = None) -> tuple[float, str]:
    rec = _menu_product_pricing_record(cursor, product_guide, cache)
    menu_price = rec.get("menu_price")
    if menu_price is not None and float(menu_price) > 0:
        return round(float(menu_price), 2), str(rec.get("price_source") or "menu")
    cost_price = rec.get("cost_price")
    if cost_price is not None and float(cost_price) > 0:
        return round(float(cost_price), 2), "cost"
    hist = rec.get("history_price")
    if hist is not None and float(hist) > 0:
        return round(float(hist), 2), "history"
    return 0.0, ""


def _menu_product_pricing_record(cursor, product_guide: str, cache: Optional[dict] = None) -> dict:
    pg = str(product_guide or "").strip().upper()
    if not pg:
        return {"name": "", "menu_price": None, "cost_price": None, "history_price": None}
    if isinstance(cache, dict) and pg in cache:
        return cache[pg]
    try:
        cursor.execute(
            "SELECT TOP 1 ProductName, EndUserPrice, AgentPrice FROM TBL007 WHERE CardGuide = CAST(? AS uniqueidentifier)",
            (pg,),
        )
        row = cursor.fetchone()
        rec = {
            "name": str(row[0]) if row and row[0] else "",
            "menu_price": float(row[1]) if row and row[1] is not None and float(row[1]) > 0 else None,
            "cost_price": float(row[2]) if row and row[2] is not None and float(row[2]) > 0 else None,
            "history_price": None,
            "price_source": "menu",
        }
    except Exception:
        rec = {"name": "", "menu_price": None, "cost_price": None, "history_price": None, "price_source": ""}
    if (rec.get("menu_price") is None and rec.get("cost_price") is None) or (
        float(rec.get("menu_price") or 0) <= 0 and float(rec.get("cost_price") or 0) <= 0
    ):
        hist = _historical_product_unit_price(cursor, product_guide)
        if hist and hist > 0:
            rec["history_price"] = hist
            rec["price_source"] = "history"
    if isinstance(cache, dict):
        cache[pg] = rec
    return rec


def _resolve_pos_invoice_line_prices(cursor, lines: list) -> list:
    cache: dict[str, dict] = {}
    out: list = []
    for raw in lines or []:
        if not isinstance(raw, dict):
            continue
        row = dict(raw)
        unit_price = float(row.get("UnitPrice") or row.get("unitPrice") or 0)
        pg = str(row.get("ProductGuide") or row.get("productGuide") or "").strip()
        qty = float(row.get("Quantity") or row.get("quantity") or 0)
        if unit_price <= 0 and pg:
            resolved, _src = _product_effective_unit_price(cursor, pg, cache)
            if resolved > 0:
                unit_price = resolved
        row["UnitPrice"] = unit_price
        row["unitPrice"] = unit_price
        if qty > 0:
            total = round(unit_price * qty, 4)
            row["TotalValue"] = total
            row["lineTotal"] = total
        out.append(row)
    return out


def _restaurant_local_invoice_lookup(invoice_id: str) -> dict:
    """بحث فاتورة في invoices.json بالمعرّف أو برقم الفاتورة المحاسبي."""
    raw = _restaurant_load("invoices", [])
    if not isinstance(raw, list):
        raw = []
    iid = str(invoice_id or "").strip()
    if iid:
        iid_upper = iid.upper()
        for inv in raw:
            if isinstance(inv, dict) and str(inv.get("invoiceId") or "").strip().upper() == iid_upper:
                return inv
    try:
        bill_num = int(str(invoice_id or "").strip())
    except (TypeError, ValueError):
        bill_num = None
    if bill_num is not None:
        matches = [
            inv
            for inv in raw
            if isinstance(inv, dict)
            and int(inv.get("billNumber") or -1) == bill_num
            and bool(inv.get("awaitingPayment"))
            and not str(inv.get("paidAt") or "").strip()
        ]
        if len(matches) == 1:
            return matches[0]
    raise HTTPException(status_code=404, detail="الفاتورة غير موجودة في السجل المحلي")


def _invoice_needs_price_repair(inv: dict) -> bool:
    if not isinstance(inv, dict):
        return False
    if not inv.get("awaitingPayment"):
        return False
    if str(inv.get("paidAt") or "").strip():
        return False
    if _money2_round(inv.get("total")) <= 0:
        return True
    for ln in list(inv.get("lines") or []) + list(inv.get("sourceLines") or []):
        if not isinstance(ln, dict):
            continue
        up = ln.get("unitPrice")
        if up is None:
            up = ln.get("UnitPrice")
        if float(up or 0) <= 0:
            return True
    return False


def _reprice_local_awaiting_invoice(cursor, inv: dict) -> dict:
    """إعادة تسعير فاتورة محلية منتظرة من المنيو/التاريخ وتحديث SQL + orders.json."""
    invoice_id = str(inv.get("invoiceId") or "").strip()
    if not invoice_id:
        raise HTTPException(status_code=400, detail="invoiceId مطلوب")
    pos_policy = _mat3am_pos_policy_row_from_cursor(cursor)
    bp = inv.get("billingProfile") if isinstance(inv.get("billingProfile"), dict) else None
    source = inv.get("sourceLines") if isinstance(inv.get("sourceLines"), list) else []
    part_items: list[dict] = []
    if source:
        for src in source:
            if not isinstance(src, dict):
                continue
            pg = str(src.get("productGuide") or "").strip()
            qty = float(src.get("quantity") or 0)
            if qty <= 0:
                continue
            part_items.append(
                {
                    "ProductGuide": pg,
                    "ProductName": str(src.get("name") or "صنف"),
                    "Quantity": qty,
                    "Unit": "1",
                    "UnitPrice": float(src.get("unitPrice") or 0),
                    "TotalValue": float(src.get("lineTotal") or 0),
                    "_orderId": str(src.get("orderId") or ""),
                    "_lineId": str(src.get("lineId") or ""),
                }
            )
    else:
        for ln in inv.get("lines") or []:
            if not isinstance(ln, dict):
                continue
            qty = float(ln.get("quantity") or 0)
            if qty <= 0:
                continue
            part_items.append(
                {
                    "ProductGuide": str(ln.get("productGuide") or ""),
                    "ProductName": str(ln.get("name") or "صنف"),
                    "Quantity": qty,
                    "Unit": "1",
                    "UnitPrice": float(ln.get("unitPrice") or 0),
                    "TotalValue": float(ln.get("lineTotal") or 0),
                }
            )
    if not part_items:
        raise HTTPException(status_code=409, detail="لا توجد بنود لإعادة التسعير")
    if bp and bp.get("active") is not False:
        part_items = _apply_billing_profile_to_invoice_lines(cursor, part_items, bp)
    else:
        part_items = _enrich_invoice_lines_from_menu(cursor, part_items)
    part_items = _resolve_pos_invoice_line_prices(cursor, part_items)
    zero_names = [
        str(x.get("ProductName") or x.get("ProductGuide") or "صنف").strip()
        for x in part_items
        if float(x.get("UnitPrice") or 0) <= 0
    ]
    if zero_names:
        preview = "، ".join(zero_names[:5])
        raise HTTPException(status_code=409, detail=f"تعذر إيجاد سعر لأصناف: {preview}")
    tip_amount = max(0.0, float(inv.get("tipAmount") or 0.0))
    part_totals = _billing_profile_invoice_totals(part_items, bp if bp and bp.get("active") is not False else None, pos_policy, tip_amount)
    for item in part_items:
        pg = str(item.get("ProductGuide") or "").strip()
        tv = float(item.get("TotalValue") or 0)
        if not pg:
            continue
        cursor.execute(
            """
            UPDATE dbo.TBL023
            SET TotalValue = ?
            WHERE MainGuide = CAST(? AS uniqueidentifier)
              AND ProductGuide = CAST(? AS uniqueidentifier)
            """,
            (tv, invoice_id, pg),
        )
    cursor.execute(
        """
        UPDATE dbo.TBL022
        SET TaxValue = ?, LocalAdministrativeTax = ?, Discount = ?
        WHERE CardGuide = CAST(? AS uniqueidentifier)
        """,
        (part_totals["tax"], part_totals["serviceCharge"], part_totals["discountValue"], invoice_id),
    )
    inv["subtotal"] = part_totals["netAfterDiscount"]
    inv["tax"] = part_totals["tax"]
    inv["serviceCharge"] = part_totals["serviceCharge"]
    inv["discount"] = part_totals["discountValue"]
    inv["total"] = part_totals["total"]
    inv["lines"] = _invoice_lines_aggregate_for_store(part_items)
    inv["sourceLines"] = _invoice_source_lines_from_part_items(part_items)
    orders = _restaurant_load("orders", [])
    if isinstance(orders, list):
        price_by_order_line: dict[tuple[str, str], float] = {}
        for src in inv["sourceLines"]:
            if not isinstance(src, dict):
                continue
            oid = str(src.get("orderId") or "")
            lid = str(src.get("lineId") or "")
            if oid and lid:
                price_by_order_line[(oid, lid)] = float(src.get("unitPrice") or 0)
        orders_changed = False
        for o in orders:
            if not isinstance(o, dict):
                continue
            oid = str(o.get("id") or "")
            for it in o.get("items") or []:
                if not isinstance(it, dict):
                    continue
                lid = str(it.get("lineId") or "")
                key = (oid, lid)
                if key in price_by_order_line and float(it.get("unitPrice") or 0) <= 0:
                    it["unitPrice"] = price_by_order_line[key]
                    orders_changed = True
        if orders_changed:
            _restaurant_save("orders", orders)
    return inv


def _persist_repriced_local_invoice(inv: dict) -> None:
    raw = _restaurant_load("invoices", [])
    if not isinstance(raw, list):
        raw = []
    iid = str(inv.get("invoiceId") or "").strip().upper()
    for idx, row in enumerate(raw):
        if isinstance(row, dict) and str(row.get("invoiceId") or "").strip().upper() == iid:
            raw[idx] = inv
            _restaurant_save("invoices", raw)
            return


def _apply_billing_profile_to_invoice_lines(cursor, lines: list, billing_profile: Optional[dict]) -> list:
    """
    توحيد تسعير الفاتورة النهائية مع قالب Owner/VIP:
    - menu: سعر المنيو (EndUserPrice ثم AgentPrice كبديل)
    - cost_plus: الاستاندر كوست AgentPrice + نسبة markup
    """
    profile = billing_profile if isinstance(billing_profile, dict) else {}
    active = bool(profile) and profile.get("active") is not False
    mode = str(profile.get("priceMode") or "menu").strip().lower()
    if mode not in ("menu", "cost_plus"):
        mode = "menu"
    try:
        markup_pct = float(profile.get("costMarkupPct") or 0.0)
    except Exception:
        markup_pct = 0.0
    markup_pct = max(0.0, min(400.0, markup_pct))
    cache: dict[str, dict] = {}
    out = []
    for ln in lines:
        if not isinstance(ln, dict):
            continue
        row = dict(ln)
        pg = str(row.get("ProductGuide") or "").strip()
        rec = _menu_product_pricing_record(cursor, pg, cache) if pg else {"name": "", "menu_price": None, "cost_price": None}
        if not str(row.get("ProductName") or "").strip() and rec.get("name"):
            row["ProductName"] = rec["name"]
        qty = float(row.get("Quantity") or 0)
        unit_price = float(row.get("UnitPrice") or 0)
        if active and pg:
            menu_price = rec.get("menu_price")
            cost_price = rec.get("cost_price")
            if mode == "cost_plus" and cost_price is not None and float(cost_price) > 0:
                unit_price = round(float(cost_price) * (100.0 + markup_pct) / 100.0, 2)
            elif menu_price is not None:
                unit_price = round(float(menu_price), 2)
            elif cost_price is not None:
                unit_price = round(float(cost_price), 2)
        elif unit_price <= 0 and pg:
            menu_price = rec.get("menu_price")
            cost_price = rec.get("cost_price")
            fallback_price = menu_price if menu_price is not None else cost_price
            if fallback_price is not None:
                unit_price = round(float(fallback_price), 2)
        row["UnitPrice"] = unit_price
        row["TotalValue"] = round(unit_price * qty, 4)
        out.append(row)
    return out


def _billing_profile_invoice_totals(
    lines: list,
    billing_profile: Optional[dict],
    policy: dict,
    tip_amount: float = 0.0,
    extra_discount: float = 0.0,
) -> dict:
    profile = billing_profile if isinstance(billing_profile, dict) else {}
    active = bool(profile) and profile.get("active") is not False
    subtotal = sum(float(x.get("TotalValue") or 0.0) for x in lines if isinstance(x, dict))
    try:
        discount_pct = float(profile.get("discountPct") or 0.0) if active else 0.0
    except Exception:
        discount_pct = 0.0
    discount_pct = max(0.0, min(100.0, discount_pct))
    vip_discount = max(0.0, subtotal * (discount_pct / 100.0))
    try:
        extra = max(0.0, float(extra_discount or 0.0))
    except (TypeError, ValueError):
        extra = 0.0
    # لا يتجاوز الخصم الإضافي الصافي بعد خصم VIP
    after_vip = max(0.0, subtotal - vip_discount)
    extra = min(extra, after_vip)
    discount_value = round(vip_discount + extra, 2)
    discounted_net = max(0.0, subtotal - discount_value)
    service_percent = float(policy.get("servicePercent") or 0.0)
    vat_percent = float(policy.get("vatPercent") or 0.0)
    service_before_vat = bool(policy.get("serviceBeforeVat", True))
    no_service = active and bool(profile.get("noService"))
    no_vat = active and bool(profile.get("noVat"))
    service_charge = 0.0 if no_service else (discounted_net * service_percent) / 100.0
    vat_base = (discounted_net + service_charge) if service_before_vat else discounted_net
    vat_value = 0.0 if no_vat else (vat_base * vat_percent) / 100.0
    total = max(0.0, discounted_net + service_charge + vat_value + max(0.0, float(tip_amount or 0.0)))
    return {
        "subtotal": round(subtotal, 2),
        "discountPct": round(discount_pct, 4),
        "discountValue": round(discount_value, 2),
        "netAfterDiscount": round(discounted_net, 2),
        "serviceCharge": round(service_charge, 2),
        "tax": round(vat_value, 2),
        "total": round(total, 2),
        "extraDiscount": round(extra, 2),
        "vipDiscount": round(vip_discount, 2),
    }


def _pos_load_active_promotions() -> list:
    """قائمة العروض النشطة من MAT3AM_PROMOTION."""
    conn = get_connection()
    if not conn:
        return []
    out = []
    try:
        cursor = conn.cursor()
        _ensure_costing_and_stock_schema(cursor)
        cursor.execute(
            """
            SELECT Id, PromoName, PromoType, PriorityNo, IsActive, IsStackable, PayloadJson
            FROM dbo.MAT3AM_PROMOTION
            WHERE IsActive = 1
              AND (StartAt IS NULL OR StartAt <= SYSUTCDATETIME())
              AND (EndAt IS NULL OR EndAt >= SYSUTCDATETIME())
            ORDER BY PriorityNo ASC, UpdatedAt DESC
            """
        )
        for r in cursor.fetchall() or []:
            payload = None
            try:
                payload = json.loads(r[6]) if r[6] else None
            except Exception:
                payload = None
            out.append(
                {
                    "id": str(r[0]),
                    "name": str(r[1] or ""),
                    "type": str(r[2] or "").strip().lower(),
                    "priority": int(r[3] or 100),
                    "isActive": bool(r[4]),
                    "isStackable": bool(r[5]),
                    "payload": payload if isinstance(payload, dict) else {},
                }
            )
    except Exception:
        return []
    finally:
        try:
            conn.close()
        except Exception:
            pass
    return out


def _pos_apply_promotions_server(lines: list, coupon_code: str = "") -> dict:
    """تطبيق عروض/كوبون على بنود الفاتورة (منطق موازٍ لـ posPromotions.ts)."""
    line_discounts: dict = {}
    invoice_discount = 0.0
    notes: list = []
    code = str(coupon_code or "").strip().lower()
    rows = [x for x in (lines or []) if isinstance(x, dict)]
    subtotal = sum(float(x.get("TotalValue") or 0) for x in rows)
    can_apply_more = True
    now_hhmm = datetime.now().strftime("%H:%M")

    for p in sorted(_pos_load_active_promotions(), key=lambda x: int(x.get("priority") or 100)):
        if not can_apply_more:
            break
        payload = p.get("payload") if isinstance(p.get("payload"), dict) else {}
        ptype = str(p.get("type") or "").strip().lower()
        applied = False
        if ptype == "percent_invoice":
            try:
                min_sub = float(payload.get("minSubtotal") or 0)
                percent = float(payload.get("percent") or 0)
            except (TypeError, ValueError):
                min_sub, percent = 0.0, 0.0
            if percent > 0 and subtotal >= min_sub:
                invoice_discount += (subtotal * percent) / 100.0
                notes.append(f"{p.get('name')}: خصم {percent}% على الفاتورة")
                applied = True
        elif ptype == "happy_hour":
            try:
                percent = float(payload.get("percent") or 0)
            except (TypeError, ValueError):
                percent = 0.0
            frm = str(payload.get("from") or "16:00")
            to = str(payload.get("to") or "18:00")
            if percent > 0 and frm <= now_hhmm <= to:
                invoice_discount += (subtotal * percent) / 100.0
                notes.append(f"{p.get('name')}: Happy Hour {percent}%")
                applied = True
        elif ptype == "coupon":
            want = str(payload.get("code") or "").strip().lower()
            if want and code and want == code:
                try:
                    percent = float(payload.get("percent") or 0)
                except (TypeError, ValueError):
                    percent = 0.0
                try:
                    amount = float(payload.get("amount") or payload.get("value") or 0)
                except (TypeError, ValueError):
                    amount = 0.0
                d = 0.0
                if percent > 0:
                    d = (subtotal * percent) / 100.0
                    notes.append(f"{p.get('name')}: كوبون {percent}%")
                elif amount > 0:
                    d = min(amount, subtotal)
                    notes.append(f"{p.get('name')}: كوبون {amount:.2f} ج.م")
                if d > 0:
                    invoice_discount += d
                    applied = True
        elif ptype in ("buy_x_get_y", "tiered_qty"):
            # خصم على مستوى الصنف — يُحسب كتعديل TotalValue لاحقاً عبر line_discounts بمفتاح الاسم
            product_guide = str(payload.get("productGuide") or "").strip().upper()
            for idx, ln in enumerate(rows):
                pg = str(ln.get("ProductGuide") or ln.get("productGuide") or "").strip().upper()
                if product_guide and pg != product_guide:
                    continue
                qty = float(ln.get("Quantity") or 0)
                up = float(ln.get("UnitPrice") or 0)
                key = str(ln.get("_lineKey") or ln.get("lineId") or f"{pg}|{idx}")
                if ptype == "buy_x_get_y":
                    buy_qty = max(1, int(float(payload.get("buyQty") or 2)))
                    free_qty = max(1, int(float(payload.get("freeQty") or 1)))
                    if qty >= buy_qty:
                        cycles = int(qty // (buy_qty + free_qty))
                        freebies = cycles * free_qty
                        if freebies > 0:
                            d = freebies * up
                            line_discounts[key] = float(line_discounts.get(key) or 0) + d
                            notes.append(f"{p.get('name')}: مجاني {freebies}")
                            applied = True
                else:
                    tiers = payload.get("tiers") if isinstance(payload.get("tiers"), list) else []
                    eligible = None
                    for t in tiers:
                        if not isinstance(t, dict):
                            continue
                        try:
                            min_qty = float(t.get("minQty") or 0)
                            percent = float(t.get("percent") or 0)
                        except (TypeError, ValueError):
                            continue
                        if percent > 0 and qty >= min_qty:
                            if eligible is None or min_qty > eligible[0]:
                                eligible = (min_qty, percent)
                    if eligible:
                        d = (qty * up * eligible[1]) / 100.0
                        line_discounts[key] = float(line_discounts.get(key) or 0) + d
                        notes.append(f"{p.get('name')}: خصم {eligible[1]}%")
                        applied = True
        if applied and not bool(p.get("isStackable")):
            can_apply_more = False

    return {
        "invoiceDiscount": round(max(0.0, invoice_discount), 2),
        "lineDiscounts": line_discounts,
        "promoNotes": notes,
        "couponMatched": bool(code) and any("كوبون" in str(n) for n in notes),
    }


def _invoice_apply_line_discount_map(lines: list, line_discount_map: dict) -> float:
    """يخصم من TotalValue لكل بند؛ يعيد مجموع خصم الأسطر."""
    if not isinstance(line_discount_map, dict) or not line_discount_map:
        return 0.0
    total_cut = 0.0
    for idx, ln in enumerate(lines or []):
        if not isinstance(ln, dict):
            continue
        keys = [
            str(ln.get("_lineKey") or ""),
            str(ln.get("lineId") or ""),
            str(ln.get("ProductGuide") or ln.get("productGuide") or "").strip().upper(),
            f"{str(ln.get('ProductGuide') or '').strip().upper()}|{idx}",
            str(ln.get("ProductName") or ln.get("name") or "").strip().lower(),
        ]
        cut = 0.0
        for k in keys:
            if k and k in line_discount_map:
                try:
                    cut = max(cut, float(line_discount_map.get(k) or 0))
                except (TypeError, ValueError):
                    pass
        if cut <= 0:
            continue
        tv = float(ln.get("TotalValue") or 0)
        applied = min(cut, max(0.0, tv))
        ln["TotalValue"] = round(max(0.0, tv - applied), 4)
        qty = float(ln.get("Quantity") or 0)
        if qty > 0:
            ln["UnitPrice"] = round(float(ln["TotalValue"]) / qty, 4)
        ln["lineDiscount"] = round(applied, 2)
        total_cut += applied
    return round(total_cut, 2)


def _invoice_resolve_manager_and_coupon_discounts(body: dict, lines: list) -> dict:
    """
    يجمع خصم الكوبون/العروض + خصم المدير (إجمالي أو على أصناف).
    خصم المدير يتطلب صلاحية مدير/مطوّر/مدير تشغيل.
    """
    body = body if isinstance(body, dict) else {}
    actor = _mat3am_actor_from_body(body)
    coupon_code = str(body.get("couponCode") or body.get("coupon") or "").strip()
    promo = _pos_apply_promotions_server(lines, coupon_code)

    # تعيين مفاتيح أسطر مستقرة قبل تطبيق خصم العروض السطرية
    for idx, ln in enumerate(lines or []):
        if isinstance(ln, dict) and not ln.get("_lineKey"):
            pg = str(ln.get("ProductGuide") or ln.get("productGuide") or "").strip().upper()
            ln["_lineKey"] = str(ln.get("lineId") or f"{pg}|{idx}")

    line_cut_promo = _invoice_apply_line_discount_map(lines, promo.get("lineDiscounts") or {})

    raw_line_discounts = body.get("lineDiscounts") if isinstance(body.get("lineDiscounts"), list) else []
    try:
        mgr_amt = float(body.get("managerDiscountAmount") or 0)
    except (TypeError, ValueError):
        mgr_amt = 0.0
    try:
        mgr_pct = float(body.get("managerDiscountPercent") or 0)
    except (TypeError, ValueError):
        mgr_pct = 0.0
    mgr_amt = max(0.0, mgr_amt)
    mgr_pct = max(0.0, min(100.0, mgr_pct))

    needs_manager = mgr_amt > 0.0001 or mgr_pct > 0.0001 or bool(raw_line_discounts)
    if needs_manager and not _role_has_manager_ops_access(actor.get("role")):
        raise HTTPException(status_code=403, detail="خصم المدير على الفاتورة/الأصناف متاح للمدير فقط.")

    mgr_line_map: dict = {}
    for row in raw_line_discounts:
        if not isinstance(row, dict):
            continue
        key = str(
            row.get("lineKey")
            or row.get("lineId")
            or row.get("productGuide")
            or row.get("name")
            or ""
        ).strip()
        if not key:
            continue
        try:
            amt = float(row.get("amount") or 0)
        except (TypeError, ValueError):
            amt = 0.0
        try:
            pct = float(row.get("percent") or 0)
        except (TypeError, ValueError):
            pct = 0.0
        # مطابقة بالاسم إن لزم
        target = None
        key_l = key.lower()
        key_u = key.upper()
        for ln in lines or []:
            if not isinstance(ln, dict):
                continue
            cands = [
                str(ln.get("_lineKey") or ""),
                str(ln.get("lineId") or ""),
                str(ln.get("ProductGuide") or "").strip().upper(),
                str(ln.get("ProductName") or "").strip().lower(),
                str(ln.get("name") or "").strip().lower(),
            ]
            if key in cands or key_l in cands or key_u in cands:
                target = ln
                break
        if not target:
            continue
        tv = float(target.get("TotalValue") or 0)
        cut = amt
        if pct > 0:
            cut += (tv * pct) / 100.0
        if cut <= 0:
            continue
        lk = str(target.get("_lineKey") or key)
        mgr_line_map[lk] = float(mgr_line_map.get(lk) or 0) + cut

    line_cut_mgr = _invoice_apply_line_discount_map(lines, mgr_line_map)

    # بعد خصم الأسطر: أعد حساب أساس خصم الفاتورة
    subtotal_after_lines = sum(float(x.get("TotalValue") or 0) for x in lines if isinstance(x, dict))
    invoice_extra = float(promo.get("invoiceDiscount") or 0)
    if mgr_pct > 0:
        invoice_extra += (subtotal_after_lines * mgr_pct) / 100.0
    if mgr_amt > 0:
        invoice_extra += mgr_amt
    invoice_extra = round(max(0.0, min(invoice_extra, subtotal_after_lines)), 2)

    notes = list(promo.get("promoNotes") or [])
    if mgr_amt > 0 or mgr_pct > 0:
        bits = []
        if mgr_pct > 0:
            bits.append(f"{mgr_pct}%")
        if mgr_amt > 0:
            bits.append(f"{mgr_amt:.2f} ج.م")
        notes.append("خصم مدير على الفاتورة: " + " + ".join(bits))
    if line_cut_mgr > 0:
        notes.append(f"خصم مدير على أصناف: {line_cut_mgr:.2f} ج.م")

    return {
        "extraDiscount": invoice_extra,
        "lineDiscountTotal": round(line_cut_promo + line_cut_mgr, 2),
        "couponCode": coupon_code,
        "couponMatched": bool(promo.get("couponMatched")),
        "promoNotes": notes,
        "managerApplied": needs_manager,
    }

def _guess_image_ext(data: bytes) -> tuple[str, str]:
    if data.startswith(b"\xFF\xD8\xFF"):
        return ("jpg", "image/jpeg")
    if data.startswith(b"\x89PNG\r\n\x1a\n"):
        return ("png", "image/png")
    if data.startswith(b"GIF8"):
        return ("gif", "image/gif")
    if data[:4] == b"RIFF" and data[8:12] == b"WEBP":
        return ("webp", "image/webp")
    return ("bin", "application/octet-stream")

def _find_product_image_file(card_guide: str) -> tuple[str | None, str | None]:
    d = _product_images_dir()
    gid = str(card_guide).upper()
    for ext, ctype in (("jpg", "image/jpeg"), ("jpeg", "image/jpeg"), ("png", "image/png"), ("gif", "image/gif"), ("webp", "image/webp")):
        p = os.path.join(d, f"{gid}.{ext}")
        if os.path.isfile(p):
            return (p, ctype)
    return (None, None)


def _find_group_image_file(card_guide: str) -> tuple[str | None, str | None]:
    d = _group_images_dir()
    gid = str(card_guide).upper()
    for ext, ctype in (("jpg", "image/jpeg"), ("jpeg", "image/jpeg"), ("png", "image/png"), ("gif", "image/gif"), ("webp", "image/webp")):
        p = os.path.join(d, f"{gid}.{ext}")
        if os.path.isfile(p):
            return (p, ctype)
    return (None, None)


def _auto_group_svg(group_name: str) -> bytes:
    nm = str(group_name or "Group").strip()[:42] or "Group"
    en = "Group"
    low = nm.lower()
    if "soup" in low or "شور" in low:
        en = "Soup"
    elif "pizza" in low or "بيتزا" in low:
        en = "Pizza"
    elif "pasta" in low or "باستا" in low:
        en = "Pasta"
    elif "chicken" in low or "دجاج" in low:
        en = "Chicken"
    elif "dessert" in low or "حلو" in low or "حلويات" in low:
        en = "Dessert"
    elif "drink" in low or "مشروبات" in low or "قهوة" in low:
        en = "Drinks"
    elif "grill" in low or "مشويات" in low:
        en = "Grills"
    elif "sand" in low or "ساند" in low:
        en = "Sandwiches"
    elif "appet" in low or "مقبل" in low:
        en = "Appetizers"
    elif "salad" in low or "سلط" in low:
        en = "Salads"
    svg = f"""<svg xmlns='http://www.w3.org/2000/svg' width='520' height='220' viewBox='0 0 520 220'>
<defs><linearGradient id='g' x1='0' y1='0' x2='1' y2='1'><stop offset='0%' stop-color='#d9f99d'/><stop offset='100%' stop-color='#86efac'/></linearGradient></defs>
<rect x='3' y='3' rx='26' ry='26' width='514' height='214' fill='url(#g)' stroke='#16a34a' stroke-width='6'/>
<rect x='20' y='34' rx='18' ry='18' width='150' height='150' fill='#fff' stroke='#22c55e' stroke-width='4'/>
<text x='95' y='124' text-anchor='middle' font-family='Segoe UI, Tahoma' font-size='62' font-weight='800' fill='#166534'>{en[:1]}</text>
<text x='188' y='90' text-anchor='start' font-family='Segoe UI, Tahoma' font-size='42' font-weight='900' fill='#052e16'>{nm}</text>
<text x='188' y='138' text-anchor='start' font-family='Segoe UI, Tahoma' font-size='34' font-weight='700' fill='#14532d'>{en}</text>
</svg>"""
    return svg.encode("utf-8")

