_CAPTAIN_FLASH_ROLES = frozenset({"waiter", "host", "manager", "developer"})


def _role_label_ar(role_code: str) -> str:
    role = str(role_code or "").strip().lower()
    labels = {
        "waiter": "جرسون طلبات",
        "host": "استقبال",
        "manager": "مدير",
        "developer": "مطوّر",
        "cashier": "كاشير",
        "kitchen": "مطبخ",
        "server": "مناولة",
        "accountant": "محاسب",
        "kitchen_specialist": "شيف مختص",
    }
    return labels.get(role, role or "غير محدد")


def _captains_flash_report_date(raw: Optional[str]) -> date_cls:
    txt = str(raw or "").strip()
    if not txt:
        return date_cls.today() - timedelta(days=1)
    try:
        return datetime.strptime(txt[:10], "%Y-%m-%d").date()
    except Exception:
        raise HTTPException(status_code=400, detail="صيغة from_date يجب أن تكون YYYY-MM-DD")


def _captains_flash_iso_on_day(iso_value: Any, report_day: date_cls) -> bool:
    dt = _parse_iso_dt_local(iso_value)
    return bool(dt and dt.date() == report_day)


def _captains_flash_float(value: Any) -> float:
    try:
        return float(value or 0)
    except Exception:
        return 0.0


def _captains_flash_qty_from_order(order_row: dict) -> float:
    qty = 0.0
    for item in order_row.get("items") or []:
        if not isinstance(item, dict):
            continue
        qty += _captains_flash_float(item.get("quantity") or 0)
    return qty


def _captains_flash_value_from_order(order_row: dict) -> float:
    total = 0.0
    for item in order_row.get("items") or []:
        if not isinstance(item, dict):
            continue
        qty = _captains_flash_float(item.get("quantity") or 0)
        unit_price = _captains_flash_float(item.get("unitPrice") or 0)
        total += qty * unit_price
    return _money2_round(total)


def _captains_flash_match_schedule(entries: list, user_id: str, login: str, report_day: date_cls) -> Optional[dict]:
    uid_norm = _mat3am_guid_norm(user_id)
    login_norm = str(login or "").strip().casefold()
    chosen: Optional[dict] = None
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        e_uid = _mat3am_guid_norm(str(entry.get("userId") or ""))
        e_login = str(entry.get("login") or "").strip().casefold()
        if uid_norm:
            if not e_uid or e_uid != uid_norm:
                continue
        elif login_norm:
            if not e_login or e_login != login_norm:
                continue
        else:
            continue
        try:
            valid_from = datetime.strptime(str(entry.get("validFrom") or "")[:10], "%Y-%m-%d").date()
            valid_to = datetime.strptime(str(entry.get("validTo") or "")[:10], "%Y-%m-%d").date()
        except Exception:
            continue
        if report_day < valid_from or report_day > valid_to:
            continue
        if chosen is None or str(entry.get("createdAt") or "") > str(chosen.get("createdAt") or ""):
            chosen = entry
    return chosen


def _build_captains_flash_report(report_day_raw: Optional[str]) -> dict:
    report_day = _captains_flash_report_date(report_day_raw)
    from mat3am_sql_cache import get_app_users

    users, users_meta = get_app_users(get_connection)
    schedule_entries: list = []
    schedule_source = "none"
    conn = get_connection()
    if conn:
        try:
            cursor = conn.cursor()
            _ensure_mat3am_dev_schema(cursor)
            schedule_entries = _mat3am_role_schedule_entries_list(cursor)
            schedule_source = "sql"
        except Exception:
            schedule_entries = []
            schedule_source = "error"
        finally:
            try:
                conn.close()
            except Exception:
                pass

    users_by_id: dict[str, dict] = {}
    users_by_login: dict[str, dict] = {}
    for user in users if isinstance(users, list) else []:
        if not isinstance(user, dict):
            continue
        role = str(user.get("role") or "").strip().lower()
        if role not in _CAPTAIN_FLASH_ROLES:
            continue
        uid = str(user.get("id") or "").strip()
        login = str(user.get("login") or "").strip().casefold()
        if uid:
            users_by_id[_mat3am_guid_norm(uid)] = user
        if login:
            users_by_login[login] = user

    rows_by_key: dict[str, dict] = {}

    def ensure_row(user_id: str = "", login: str = "", name: str = "", base_role: str = "") -> Optional[dict]:
        uid_norm = _mat3am_guid_norm(user_id)
        login_norm = str(login or "").strip().casefold()
        user = users_by_id.get(uid_norm) if uid_norm else None
        if user is None and login_norm:
            user = users_by_login.get(login_norm)
        if user:
            user_id = str(user.get("id") or user_id or "").strip()
            login = str(user.get("login") or login or "").strip()
            name = str(user.get("name") or name or login or "").strip()
            base_role = str(user.get("role") or base_role or "").strip().lower()
        base_role = str(base_role or "").strip().lower()
        if base_role and base_role not in _CAPTAIN_FLASH_ROLES:
            return None
        if not user_id and not login and not name:
            return None
        key = f"id:{uid_norm}" if uid_norm else (f"login:{login_norm}" if login_norm else f"name:{str(name).strip().casefold()}")
        row = rows_by_key.get(key)
        if row is None:
            row = {
                "captainUserId": user_id or "",
                "captainLogin": login or "",
                "captainName": name or login or "غير محدد",
                "baseRole": base_role or "",
                "baseRoleLabel": _role_label_ar(base_role),
                "scheduledRole": "",
                "scheduledRoleLabel": "",
                "scheduleWindow": "",
                "seatingCount": 0,
                "billRequestCount": 0,
                "completedSessionCount": 0,
                "orderCount": 0,
                "orderQty": 0.0,
                "orderValue": 0.0,
                "guestReturnRequestCount": 0,
                "guestReturnLineCount": 0,
                "guestReturnQty": 0.0,
                "guestReturnValue": 0.0,
                "approvedReturnCount": 0,
                "approvedReturnQty": 0.0,
                "approvedReturnValue": 0.0,
                "extraTimeCount": 0,
                "resetReadyCount": 0,
                "closeCount": 0,
                "transferInCount": 0,
                "transferOutCount": 0,
                "claimCount": 0,
            }
            rows_by_key[key] = row
        else:
            if user_id and not row["captainUserId"]:
                row["captainUserId"] = user_id
            if login and not row["captainLogin"]:
                row["captainLogin"] = login
            if name and (not row["captainName"] or row["captainName"] == "غير محدد"):
                row["captainName"] = name
            if base_role and not row["baseRole"]:
                row["baseRole"] = base_role
                row["baseRoleLabel"] = _role_label_ar(base_role)
        return row

    sessions = _restaurant_load("table_sessions", [])
    if not isinstance(sessions, list):
        sessions = []
    orders = _restaurant_load("orders", [])
    if not isinstance(orders, list):
        orders = []
    returns = _guest_return_requests_load()
    if not isinstance(returns, list):
        returns = []
    session_audit = _restaurant_load("session_audit", [])
    if not isinstance(session_audit, list):
        session_audit = []

    session_to_key: dict[str, str] = {}
    for sess in sessions:
        if not isinstance(sess, dict):
            continue
        row = ensure_row(
            str(sess.get("captainUserId") or ""),
            str(sess.get("captainLogin") or ""),
            str(sess.get("captainName") or sess.get("captainLogin") or ""),
            str(sess.get("captainRole") or ""),
        )
        sid = str(sess.get("id") or "").strip()
        if row is not None and sid:
            if row["captainUserId"]:
                session_to_key[sid] = f"id:{_mat3am_guid_norm(row['captainUserId'])}"
            elif row["captainLogin"]:
                session_to_key[sid] = f"login:{str(row['captainLogin']).strip().casefold()}"
            else:
                session_to_key[sid] = f"name:{str(row['captainName']).strip().casefold()}"
        if row is None:
            continue
        if _captains_flash_iso_on_day(sess.get("startTime"), report_day):
            row["seatingCount"] += 1
        if _captains_flash_iso_on_day(sess.get("billingRequestedAt"), report_day):
            row["billRequestCount"] += 1
        if _captains_flash_iso_on_day(sess.get("endTime"), report_day):
            row["completedSessionCount"] += 1

    for order in orders:
        if not isinstance(order, dict):
            continue
        if not _captains_flash_iso_on_day(order.get("createdAt"), report_day):
            continue
        sid = str(order.get("sessionId") or "").strip()
        row = None
        if sid:
            row_key = session_to_key.get(sid)
            if row_key:
                row = rows_by_key.get(row_key)
        if row is None:
            row = ensure_row()
        if row is None:
            continue
        row["orderCount"] += 1
        row["orderQty"] = _money2_round(float(row["orderQty"]) + _captains_flash_qty_from_order(order))
        row["orderValue"] = _money2_round(float(row["orderValue"]) + _captains_flash_value_from_order(order))

    for req in returns:
        if not isinstance(req, dict):
            continue
        req_row = None
        requested_by = req.get("requestedBy") if isinstance(req.get("requestedBy"), dict) else {}
        req_row = ensure_row(
            str(requested_by.get("userId") or ""),
            "",
            str(requested_by.get("name") or ""),
            str(requested_by.get("role") or ""),
        )
        if req_row is None:
            req_row = rows_by_key.get(session_to_key.get(str(req.get("sessionId") or "").strip(), ""))
        lines = [ln for ln in (req.get("lines") or []) if isinstance(ln, dict)]
        if req_row is not None and _captains_flash_iso_on_day(req.get("requestedAt") or req.get("createdAt"), report_day):
            req_row["guestReturnRequestCount"] += 1
            req_row["guestReturnLineCount"] += len(lines)
            req_row["guestReturnQty"] = _money2_round(float(req_row["guestReturnQty"]) + sum(_captains_flash_float(ln.get("returnQty") or 0) for ln in lines))
            req_row["guestReturnValue"] = _money2_round(
                float(req_row["guestReturnValue"])
                + sum(_captains_flash_float(ln.get("returnQty") or 0) * _captains_flash_float(ln.get("unitPrice") or 0) for ln in lines)
            )
        review = req.get("managerReview") if isinstance(req.get("managerReview"), dict) else {}
        if req_row is not None and _captains_flash_iso_on_day(review.get("at"), report_day) and str(req.get("status") or "").strip().lower() == "approved":
            approved_lines = [ln for ln in lines if str(ln.get("lineDecisionStatus") or "").strip().lower() == "approved"]
            req_row["approvedReturnCount"] += len(approved_lines) or (1 if lines else 0)
            req_row["approvedReturnQty"] = _money2_round(float(req_row["approvedReturnQty"]) + sum(_captains_flash_float(ln.get("returnQty") or 0) for ln in approved_lines))
            req_row["approvedReturnValue"] = _money2_round(
                float(req_row["approvedReturnValue"])
                + sum(_captains_flash_float(ln.get("returnQty") or 0) * _captains_flash_float(ln.get("unitPrice") or 0) for ln in approved_lines)
            )

    for entry in session_audit:
        if not isinstance(entry, dict) or not _captains_flash_iso_on_day(entry.get("at"), report_day):
            continue
        action = str(entry.get("action") or "").strip().lower()
        if action == "claim_order_taker":
            row = ensure_row(
                str(entry.get("captainUserId") or ""),
                str(entry.get("captainLogin") or ""),
                "",
                "waiter",
            )
            if row is not None:
                row["claimCount"] += 1
            continue
        if action == "request_captain_transfer":
            row = ensure_row(str(entry.get("fromCaptainUserId") or ""), "", "", "waiter")
            if row is not None:
                row["transferOutCount"] += 1
            continue
        if action in ("accept_captain_transfer", "reassign_order_taker"):
            row_in = ensure_row(str(entry.get("toCaptainUserId") or ""), str(entry.get("toCaptainLogin") or ""), "", "waiter")
            if row_in is not None:
                row_in["transferInCount"] += 1
            row_out = ensure_row(str(entry.get("fromCaptainUserId") or ""), "", "", "waiter")
            if row_out is not None:
                row_out["transferOutCount"] += 1
            continue
        sid = str(entry.get("sessionId") or "").strip()
        row = rows_by_key.get(session_to_key.get(sid, ""))
        if row is None:
            continue
        if action == "no_order_watch_extra_time":
            row["extraTimeCount"] += 1
        elif action in ("no_order_watch_reset_ready", "no_order_watch_reset_table"):
            row["resetReadyCount"] += 1
        elif action == "complete_session":
            row["closeCount"] += 1

    for row in rows_by_key.values():
        schedule = _captains_flash_match_schedule(schedule_entries, str(row.get("captainUserId") or ""), str(row.get("captainLogin") or ""), report_day)
        if schedule:
            scheduled_role = str(schedule.get("role") or "").strip().lower()
            row["scheduledRole"] = scheduled_role
            row["scheduledRoleLabel"] = _role_label_ar(scheduled_role)
            valid_from = str(schedule.get("validFrom") or "").strip()
            valid_to = str(schedule.get("validTo") or "").strip()
            row["scheduleWindow"] = f"{valid_from} -> {valid_to}" if valid_from or valid_to else ""
        else:
            row["scheduledRole"] = str(row.get("baseRole") or "")
            row["scheduledRoleLabel"] = _role_label_ar(str(row.get("baseRole") or ""))
        row["sortScore"] = (
            int(row.get("billRequestCount") or 0) * 7
            + int(row.get("orderCount") or 0) * 5
            + int(row.get("seatingCount") or 0) * 4
            + int(row.get("guestReturnRequestCount") or 0) * 3
            + int(row.get("extraTimeCount") or 0)
            + int(row.get("resetReadyCount") or 0)
        )

    captain_rows = sorted(
        rows_by_key.values(),
        key=lambda row: (
            -int(row.get("sortScore") or 0),
            -int(row.get("billRequestCount") or 0),
            -int(row.get("orderCount") or 0),
            str(row.get("captainName") or row.get("captainLogin") or ""),
        ),
    )
    captain_rows = [row for row in captain_rows if int(row.get("sortScore") or 0) > 0 or str(row.get("captainName") or "").strip()]

    overall = {
        "captainsCount": len([row for row in captain_rows if int(row.get("sortScore") or 0) > 0]),
        "sessions": sum(int(row.get("seatingCount") or 0) for row in captain_rows),
        "orders": sum(int(row.get("orderCount") or 0) for row in captain_rows),
        "orderQty": _money2_round(sum(_captains_flash_float(row.get("orderQty")) for row in captain_rows)),
        "bills": sum(int(row.get("billRequestCount") or 0) for row in captain_rows),
        "guestReturns": sum(int(row.get("guestReturnRequestCount") or 0) for row in captain_rows),
        "approvedReturns": sum(int(row.get("approvedReturnCount") or 0) for row in captain_rows),
        "extraTime": sum(int(row.get("extraTimeCount") or 0) for row in captain_rows),
        "resetReady": sum(int(row.get("resetReadyCount") or 0) for row in captain_rows),
        "closedSessions": sum(int(row.get("closeCount") or 0) for row in captain_rows),
    }

    columns = [
        "الكابتن",
        "موقعه في الجدولة",
        "تسكين",
        "طلبات",
        "كمية",
        "طلب الحساب",
        "مرتجع",
        "مرتجع معتمد",
        "مدة إضافية",
        "إرجاع جاهزة",
        "حسم/إغلاق",
        "تحويل داخل",
        "تحويل خارج",
    ]
    rows = [
        [
            str(row.get("captainName") or row.get("captainLogin") or ""),
            str(row.get("scheduledRoleLabel") or row.get("baseRoleLabel") or ""),
            int(row.get("seatingCount") or 0),
            int(row.get("orderCount") or 0),
            _money2_round(_captains_flash_float(row.get("orderQty"))),
            int(row.get("billRequestCount") or 0),
            int(row.get("guestReturnRequestCount") or 0),
            int(row.get("approvedReturnCount") or 0),
            int(row.get("extraTimeCount") or 0),
            int(row.get("resetReadyCount") or 0),
            int(row.get("closeCount") or 0),
            int(row.get("transferInCount") or 0),
            int(row.get("transferOutCount") or 0),
        ]
        for row in captain_rows
    ]

    return {
        "reportId": "captains_flash",
        "reportDate": report_day.isoformat(),
        "generatedAt": datetime.now().isoformat(),
        "columns": columns,
        "rows": rows,
        "overall": overall,
        "captains": captain_rows,
        "meta": {
            "usersSource": users_meta,
            "scheduleSource": schedule_source,
        },
        "message": "ملخص تشغيلي يومي للكباتن مبني على الجلسات والطلبات والمرتجعات وسجل التشغيل.",
    }


def _build_flash_report(report_day_raw: Optional[str]) -> dict:
    """Flash Report — ملخص مالي يومي عام (All Orders) من الفواتير المحلية + تسديدات SQL."""
    report_day = _captains_flash_report_date(report_day_raw)
    day_iso = report_day.isoformat()

    invoices = _restaurant_load("invoices", [])
    if not isinstance(invoices, list):
        invoices = []
    sessions = _restaurant_load("table_sessions", [])
    if not isinstance(sessions, list):
        sessions = []
    orders = _restaurant_load("orders", [])
    if not isinstance(orders, list):
        orders = []

    gross_sales = 0.0
    check_discounts = 0.0
    item_discounts = 0.0
    taxes = 0.0
    service_charges = 0.0
    tips = 0.0
    guest_count = 0
    void_count = 0

    for inv in invoices:
        if not isinstance(inv, dict):
            continue
        inv_date = _parse_iso_dt_local(inv.get("paidAt") or inv.get("requestedAt"))
        if not inv_date or inv_date.date() != report_day:
            continue
        subtotal = float(inv.get("subtotal") or 0)
        discount = float(inv.get("discount") or 0)
        gross_sales += subtotal + discount
        check_discounts += discount
        taxes += float(inv.get("tax") or 0)
        service_charges += float(inv.get("serviceCharge") or 0)
        tips += float(inv.get("tipAmount") or 0)
        for ln in inv.get("lines") or []:
            if isinstance(ln, dict):
                # أي خصم على السطر يُحتسب هنا
                line_disc = float(ln.get("discount") or 0)
                if line_disc:
                    item_discounts += line_disc

    for s in sessions:
        if isinstance(s, dict):
            st = _parse_iso_dt_local(s.get("startTime"))
            if st and st.date() == report_day:
                guest_count += max(1, int(s.get("guestCount") or 1))

    for o in orders:
        if isinstance(o, dict) and str(o.get("status") or "").lower() == "cancelled":
            created = _parse_iso_dt_local(o.get("createdAt"))
            if created and created.date() == report_day:
                void_count += 1

    net_sales = max(0.0, gross_sales - check_discounts - item_discounts)
    subtotal = net_sales + taxes
    total = subtotal + tips

    # تفاصيل الدفع من SQL
    payment_summary: list[dict] = []
    conn = get_connection()
    if conn:
        try:
            cursor = conn.cursor()
            cursor.execute(
                """
                SELECT RouteKey, COUNT(*), ISNULL(SUM(Amount), 0)
                FROM dbo.MAT3AM_INV_PAYMENT_LINE
                WHERE CONVERT(date, CreatedAt) = CAST(? AS date)
                GROUP BY RouteKey
                """,
                (day_iso,),
            )
            for row in cursor.fetchall():
                rk = str(row[0] or "unknown")
                qty = int(row[1] or 0)
                amount = float(row[2] or 0)
                label = rk
                if rk == "cash":
                    label = "Cash"
                elif rk == "visa":
                    label = "Credit Car"
                elif rk == "wallet":
                    label = "C L"
                elif rk == "instapay":
                    label = "C L"
                payment_summary.append({"qty": qty, "type": label, "amount": amount, "tip": 0.0})
        except Exception:
            pass
        finally:
            try:
                conn.close()
            except Exception:
                pass

    if not payment_summary:
        payment_summary = [
            {"qty": 0, "type": "Cash", "amount": 0.0, "tip": 0.0},
            {"qty": 0, "type": "Credit Car", "amount": 0.0, "tip": 0.0},
        ]

    guest_amount = float(guest_count) * 233.5 if guest_count > 0 else 0.0  # placeholder; will be derived from data

    return {
        "reportId": "flash",
        "reportDate": day_iso,
        "time": datetime.now().strftime("%I:%M %p"),
        "session": "—",
        "filter": "All Orders",
        "guestCount": guest_count,
        "voidCount": void_count,
        "guestAmount": round(guest_amount, 2),
        "payments": payment_summary,
        "salesSummary": {
            "grossSales": round(gross_sales, 2),
            "checkDiscounts": round(check_discounts, 2),
            "itemDiscounts": round(item_discounts, 2),
            "priceAdjust": 0.0,
            "twoForOneDiscount": 0.0,
            "groupDiscount": 0.0,
            "coupons": 0.0,
            "guest": round(-guest_amount, 2) if guest_amount > 0 else 0.0,
        },
        "netSales": round(net_sales, 2),
        "taxes": round(taxes, 2),
        "subtotal": round(subtotal, 2),
        "tips": round(tips, 2),
        "hashTotal": 0.0,
        "total": round(total, 2),
    }


@app.get("/api/reports/{report_id}/run")
def run_report(
    report_id: str,
    from_date: Optional[str] = None,
    to_date: Optional[str] = None,
    account_guide: Optional[str] = None,
    agent_guide: Optional[str] = None,
    product_guide: Optional[str] = None,
    currency_guide: Optional[str] = None,
    show_opening_balance: Optional[str] = None,
    posted_only: Optional[str] = None,
    show_only_unlinked: Optional[str] = None,
    source_bill_guide: Optional[str] = None,
):
    """تشغيل تقرير — محاكاة إكسترا (كشف حساب عميل، مراقبة كميات الارتباطات، أعمار زمنية، ...)"""
    if report_id == "captains_flash":
        return _build_captains_flash_report(from_date or to_date)
    if report_id == "flash":
        return _build_flash_report(from_date or to_date)
    conn = get_connection()
    if not conn:
        raise HTTPException(status_code=500, detail="فشل الاتصال بقاعدة البيانات")
    try:
        cursor = conn.cursor()
        fd = from_date or "1900-01-01"
        td = to_date or "2099-12-31"

        if report_id == "payment_reconciliation":
            _ensure_payment_routing_schema(cursor)
            cursor.execute(
                """
                WITH op AS (
                    SELECT InvoiceGuid, ISNULL(SUM(Amount), 0) AS OperationalPaid
                    FROM dbo.MAT3AM_INV_PAYMENT_LINE
                    GROUP BY InvoiceGuid
                ),
                xtra AS (
                    SELECT MainGuide, ISNULL(SUM(Value), 0) AS XtraPaid
                    FROM dbo.TBL054
                    GROUP BY MainGuide
                ),
                ledger AS (
                    SELECT h.BillGuide,
                           COUNT(DISTINCT h.CardGuide) AS EntryCount,
                           ISNULL(SUM(CASE WHEN r.AccountGuide IS NOT NULL THEN ISNULL(d.Debit, 0) ELSE 0 END), 0) AS LedgerPaid
                    FROM dbo.TBL011 h
                    LEFT JOIN dbo.TBL012 d ON d.MainGuide = h.CardGuide
                    LEFT JOIN (
                        SELECT DISTINCT AccountGuide
                        FROM dbo.MAT3AM_PAYMENT_ROUTING
                        WHERE IsActive = 1 AND AccountGuide IS NOT NULL
                    ) r ON r.AccountGuide = d.AccountGuide
                    WHERE h.BillGuide IS NOT NULL
                    GROUP BY h.BillGuide
                ),
                invoice_total AS (
                    SELECT MainGuide, ISNULL(SUM(TotalValue), 0) AS LinesTotal
                    FROM dbo.TBL023
                    GROUP BY MainGuide
                )
                SELECT b.CardGuide, b.BillNumber, b.BillDate, t.InvoiceName,
                       ISNULL(a.AgentName, N''), ISNULL(it.LinesTotal, 0),
                       ISNULL(b.LocalAdministrativeTax, 0), ISNULL(b.TaxValue, 0), ISNULL(b.Discount, 0),
                       ISNULL(op.OperationalPaid, 0), ISNULL(xtra.XtraPaid, 0), ISNULL(ledger.LedgerPaid, 0),
                       ISNULL(b.Paid, 0), ISNULL(ledger.EntryCount, 0), ISNULL(b.CheckID01, 0),
                       CASE
                           WHEN ABS(ISNULL(op.OperationalPaid, 0) - ISNULL(xtra.XtraPaid, 0)) > 0.02 THEN N'فرق تشغيلي / TBL054'
                           WHEN ABS(ISNULL(xtra.XtraPaid, 0) - ISNULL(ledger.LedgerPaid, 0)) > 0.02 THEN N'فرق TBL054 / القيد'
                           WHEN ISNULL(ledger.EntryCount, 0) = 0 THEN N'غير مرحل'
                           WHEN ISNULL(op.OperationalPaid, 0) = 0 AND ISNULL(xtra.XtraPaid, 0) = 0 THEN N'على الحساب — مطابق'
                           ELSE N'مطابق'
                       END AS MatchStatus
                FROM dbo.TBL022 b
                INNER JOIN dbo.MAT3AM_RESTAURANT_INVOICE_TYPES m ON m.Tbl020CardGuide = b.MainGuide
                INNER JOIN dbo.TBL020 t ON t.CardGuide = b.MainGuide
                LEFT JOIN dbo.TBL016 a ON a.CardGuide = b.AgentGuide
                LEFT JOIN invoice_total it ON it.MainGuide = b.CardGuide
                LEFT JOIN op ON op.InvoiceGuid = b.CardGuide
                LEFT JOIN xtra ON xtra.MainGuide = b.CardGuide
                LEFT JOIN ledger ON ledger.BillGuide = b.CardGuide
                WHERE CONVERT(date, b.BillDate) >= CAST(? AS date)
                  AND CONVERT(date, b.BillDate) <= CAST(? AS date)
                ORDER BY b.BillDate DESC, b.BillNumber DESC
                """,
                (fd, td),
            )
            rows = cursor.fetchall()
            out = []
            for r in rows:
                invoice_total_value = round(
                    float(r[5] or 0) + float(r[6] or 0) + float(r[7] or 0) - float(r[8] or 0),
                    2,
                )
                op_paid = round(float(r[9] or 0), 2)
                xtra_paid = round(float(r[10] or 0), 2)
                ledger_paid = round(float(r[11] or 0), 2)
                out.append(
                    [
                        str(r[0]),
                        int(r[1] or 0),
                        str(r[2]) if r[2] else "",
                        r[3] or "",
                        r[4] or "",
                        invoice_total_value,
                        op_paid,
                        xtra_paid,
                        ledger_paid,
                        round(op_paid - xtra_paid, 2),
                        round(xtra_paid - ledger_paid, 2),
                        round(float(r[12] or 0), 2),
                        int(r[13] or 0),
                        int(r[14] or 0),
                        r[15] or "",
                    ]
                )
            return {
                "columns": [
                    "CardGuide",
                    "رقم_الفاتورة",
                    "التاريخ",
                    "نوع_الفاتورة",
                    "العميل",
                    "إجمالي_الفاتورة",
                    "تحصيل_تشغيلي",
                    "تحصيل_TBL054",
                    "تحصيل_بالقيد",
                    "فرق_تشغيلي_عن_TBL054",
                    "فرق_TBL054_عن_القيد",
                    "Paid_TBL022",
                    "عدد_القيود",
                    "CheckID01",
                    "حالة_المطابقة",
                ],
                "rows": out,
                "message": "مطابقة مستقلة بين سجل الكاشير وTBL054 وحسابات التحصيل في TBL011/TBL012.",
            }

        if report_id == "accounts_list":
            cursor.execute("SELECT CardGuide, CardCode, AccountName, LatinName FROM TBL004 WHERE AccountName IS NOT NULL ORDER BY CardCode")
            rows = cursor.fetchall()
            return {"columns": ["CardGuide", "CardCode", "AccountName", "LatinName"], "rows": [[str(r[0]), r[1] or "", r[2] or "", r[3] or ""] for r in rows]}

        if report_id == "bonds_list":
            cursor.execute("SELECT TOP 200 b.CardGuide, b.BondNumber, b.BondDate, b.Notes, e.EntryName FROM TBL010 b LEFT JOIN TBL009 e ON e.CardGuide = b.MainGuide ORDER BY b.BondDate DESC")
            rows = cursor.fetchall()
            return {"columns": ["CardGuide", "BondNumber", "BondDate", "Notes", "EntryTypeName"], "rows": [[str(r[0]), r[1], str(r[2]) if r[2] else "", r[3] or "", r[4] or ""] for r in rows]}

        if report_id == "entries_list":
            cursor.execute("SELECT TOP 200 CardGuide, EntryNumber, EntryDate, Notes FROM TBL011 ORDER BY EntryDate DESC")
            rows = cursor.fetchall()
            return {"columns": ["CardGuide", "EntryNumber", "EntryDate", "Notes"], "rows": [[str(r[0]), r[1], str(r[2]) if r[2] else "", r[3] or ""] for r in rows]}

        # ميزان المراجعة — إجمالي مدين/دائن لكل حساب من TBL012 ضمن الفترة
        if report_id == "trial_balance":
            q = """
            SELECT a.CardGuide, a.CardCode, a.AccountName,
                   ISNULL(SUM(d.Debit),0), ISNULL(SUM(d.Credit),0),
                   ISNULL(SUM(d.Debit),0)-ISNULL(SUM(d.Credit),0)
            FROM TBL004 a
            LEFT JOIN TBL012 d ON d.AccountGuide = a.CardGuide
            LEFT JOIN TBL011 h ON h.CardGuide = d.MainGuide
            WHERE a.AccountName IS NOT NULL
              AND (h.EntryDate IS NULL OR (CONVERT(date, h.EntryDate) >= ? AND CONVERT(date, h.EntryDate) <= ?))
            GROUP BY a.CardGuide, a.CardCode, a.AccountName
            HAVING ISNULL(SUM(d.Debit),0) <> 0 OR ISNULL(SUM(d.Credit),0) <> 0
            ORDER BY a.CardCode
            """
            cursor.execute(q, (fd, td))
            rows = cursor.fetchall()
            return {"columns": ["CardGuide", "CardCode", "AccountName", "إجمالي_مدين", "إجمالي_دائن", "الرصيد"], "rows": [[str(r[0]), r[1] or "", r[2] or "", float(r[3] or 0), float(r[4] or 0), float(r[5] or 0)] for r in rows]}

        # دفتر الأستاذ العام — حركات حساب واحد مع رصيد متراكم
        if report_id == "general_ledger":
            if not account_guide:
                cursor.execute("SELECT TOP 100 CardGuide, CardCode, AccountName FROM TBL004 WHERE AccountName IS NOT NULL ORDER BY CardCode")
                rows = cursor.fetchall()
                return {"columns": ["CardGuide", "CardCode", "AccountName"], "rows": [[str(r[0]), r[1] or "", r[2] or ""] for r in rows], "message": "أرسل account_guide لحركات الحساب"}
            q = """
            SELECT h.EntryNumber, h.EntryDate, h.Notes, d.Description, d.Debit, d.Credit
            FROM TBL012 d
            INNER JOIN TBL011 h ON h.CardGuide = d.MainGuide
            WHERE d.AccountGuide = ? AND CONVERT(date, h.EntryDate) >= ? AND CONVERT(date, h.EntryDate) <= ?
            ORDER BY h.EntryDate, h.EntryNumber
            """
            cursor.execute(q, (account_guide, fd, td))
            rows = cursor.fetchall()
            balance = 0.0
            out_rows = []
            for r in rows:
                deb, cred = float(r[4] or 0), float(r[5] or 0)
                balance += deb - cred
                out_rows.append([r[0], str(r[1]) if r[1] else "", r[2] or "", r[3] or "", deb, cred, round(balance, 2)])
            return {"columns": ["رقم_القيد", "التاريخ", "البيان", "وصف_البند", "مدين", "دائن", "الرصيد"], "rows": out_rows}

        # كشف حساب عميل — بكل الخيارات: من/إلى تاريخ، عميل، عملة، رصيد افتتاحي، مرحل فقط
        if report_id == "customer_statement":
            if not agent_guide:
                cursor.execute("SELECT TOP 100 CardGuide, AgentName, CardNumber FROM TBL016 WHERE AgentName IS NOT NULL AND CardGuide <> CAST('26CBD95C-98CB-48F3-8EEA-EE5D2B0D0500' AS uniqueidentifier) ORDER BY AgentName")
                rows = cursor.fetchall()
                return {"columns": ["CardGuide", "AgentName", "CardNumber"], "rows": [[str(r[0]), r[1] or "", r[2] or ""] for r in rows], "message": "أرسل agent_guide لكشف الحساب"}
            inv_where = "AgentGuide = ? AND CONVERT(date, TBL022.BillDate) >= ? AND CONVERT(date, TBL022.BillDate) <= ?"
            inv_params = [agent_guide, fd, td]
            if currency_guide:
                try:
                    cursor.execute("SELECT TOP 1 CurrencyGuide FROM TBL022")
                    inv_where += " AND (TBL022.CurrencyGuide = ? OR TBL022.CurrencyGuide IS NULL)"
                    inv_params.append(currency_guide)
                except Exception:
                    pass
            if str(posted_only).strip().lower() in ("1", "true", "yes", "نعم"):
                inv_where += " AND (TBL022.LockRelations = 1)"
            cursor.execute("""
            SELECT TBL022.BillDate, TBL022.BillNumber, 'فاتورة', (SELECT ISNULL(SUM(TotalValue),0) FROM TBL023 WHERE MainGuide = TBL022.CardGuide)
            FROM TBL022
            WHERE """ + inv_where + """
            ORDER BY TBL022.BillDate
            """, tuple(inv_params))
            inv_rows = cursor.fetchall()
            bond_where = "AgentGuide = ? AND CONVERT(date, BondDate) >= ? AND CONVERT(date, BondDate) <= ?"
            bond_params = [agent_guide, fd, td]
            if currency_guide:
                bond_where += " AND (CurrencyGuide = ? OR CurrencyGuide IS NULL)"
                bond_params.append(currency_guide)
            if str(posted_only).strip().lower() in ("1", "true", "yes", "نعم"):
                bond_where += " AND EXISTS (SELECT 1 FROM TBL011 e WHERE e.BondGuide = TBL010.CardGuide)"
            cursor.execute("""
            SELECT BondDate, BondNumber, Notes, (SELECT ISNULL(SUM(Debit),0)+ISNULL(SUM(Credit),0) FROM TBL038 WHERE MainGuide = TBL010.CardGuide)
            FROM TBL010
            WHERE """ + bond_where + """
            ORDER BY BondDate
            """, tuple(bond_params))
            bond_rows = cursor.fetchall()
            opening = 0.0
            if str(show_opening_balance).strip().lower() in ("1", "true", "yes", "نعم"):
                cursor.execute("""
                SELECT ISNULL(SUM(v),0) FROM (
                    SELECT (SELECT ISNULL(SUM(TotalValue),0) FROM TBL023 WHERE MainGuide = TBL022.CardGuide) AS v
                    FROM TBL022 WHERE AgentGuide = ? AND CONVERT(date, TBL022.BillDate) < ?
                ) x
                """, (agent_guide, fd))
                opening += float((cursor.fetchone() or [0])[0] or 0)
                cursor.execute("""
                SELECT ISNULL(SUM((SELECT ISNULL(SUM(Debit),0)+ISNULL(SUM(Credit),0) FROM TBL038 WHERE MainGuide = TBL010.CardGuide)),0)
                FROM TBL010 WHERE AgentGuide = ? AND CONVERT(date, BondDate) < ?
                """, (agent_guide, fd))
                opening -= float((cursor.fetchone() or [0])[0] or 0)
            rows_combined = []
            if opening != 0.0:
                rows_combined.append(("", "", "رصيد افتتاحي", opening if opening > 0 else 0.0, -opening if opening < 0 else 0.0))
            for r in inv_rows:
                rows_combined.append((str(r[0]) if r[0] else "", r[1] or "", "فاتورة", float(r[3] or 0), 0.0))
            for r in bond_rows:
                rows_combined.append((str(r[0]) if r[0] else "", r[1] or "", r[2] or "سند", 0.0, float(r[3] or 0)))
            rows_combined.sort(key=lambda x: (x[0] or "1900-01-01", x[1]))
            balance = 0.0
            out_rows = []
            for r in rows_combined:
                balance += r[3] - r[4]
                out_rows.append([r[0], r[1], r[2], r[3], r[4], round(balance, 2)])
            return {"columns": ["التاريخ", "الرقم", "البيان", "مدين", "دائن", "الرصيد"], "rows": out_rows}

        # مراقبة كميات الارتباطات — فواتير مع كميات وحالة الربط بالقيد (مرحل/غير مرحل)
        if report_id == "relations_quantities":
            only_unlinked = str(show_only_unlinked).strip().lower() in ("1", "true", "yes", "نعم")
            q = """
            SELECT b.CardGuide, b.BillNumber, b.BillDate, a.AgentName,
                   ISNULL((SELECT SUM(Quantity) FROM TBL023 WHERE MainGuide = b.CardGuide),0),
                   ISNULL((SELECT SUM(TotalValue) FROM TBL023 WHERE MainGuide = b.CardGuide),0),
                   CASE WHEN e.CardGuide IS NOT NULL THEN 1 ELSE 0 END
            FROM TBL022 b
            LEFT JOIN TBL016 a ON a.CardGuide = b.AgentGuide
            LEFT JOIN TBL011 e ON e.BillGuide = b.CardGuide
            WHERE CONVERT(date, b.BillDate) >= ? AND CONVERT(date, b.BillDate) <= ?
            """
            params = [fd, td]
            if only_unlinked:
                q += " AND e.CardGuide IS NULL"
            q += " ORDER BY b.BillDate, b.BillNumber"
            cursor.execute(q, params)
            rows = cursor.fetchall()
            cols = ["CardGuide", "رقم_الفاتورة", "التاريخ", "العميل", "مجموع_الكميات", "مجموع_القيمة", "مرتبط_بقيد"]
            return {"columns": cols, "rows": [[str(r[0]), r[1] or "", str(r[2]) if r[2] else "", r[3] or "", float(r[4] or 0), float(r[5] or 0), "نعم" if r[6] else "لا"] for r in rows]}

        # أعمار زمنية — فواتير مصدر ومولودة + تسديدات + تحليل المتبقي بأعمار (0-7، 7-15، 15-21، 21-28، 28+)
        if report_id == "invoice_aging":
            if not agent_guide:
                cursor.execute("SELECT TOP 100 CardGuide, AgentName, CardNumber FROM TBL016 WHERE AgentName IS NOT NULL ORDER BY AgentName")
                rows = cursor.fetchall()
                return {"columns": ["CardGuide", "AgentName", "CardNumber"], "rows": [[str(r[0]), r[1] or "", r[2] or ""] for r in rows], "message": "أرسل agent_guide لتقرير الأعمار الزمنية"}
            from datetime import date as _date_type, datetime as _dt_type
            try:
                as_of = _date_type.today()
            except Exception:
                try:
                    as_of = _dt_type.strptime(str(fd or "")[:10], "%Y-%m-%d").date()
                except Exception:
                    as_of = _date_type.today()
            out_rows = []
            show_open = str(show_opening_balance).strip().lower() in ("1", "true", "yes", "نعم")
            if show_open:
                cursor.execute("""
                SELECT ISNULL(SUM(v),0) FROM (
                    SELECT (SELECT ISNULL(SUM(TotalValue),0) FROM TBL023 WHERE MainGuide = TBL022.CardGuide) AS v
                    FROM TBL022 WHERE AgentGuide = ? AND CONVERT(date, TBL022.BillDate) < ?
                ) x
                """, (agent_guide, fd))
                open_inv = float((cursor.fetchone() or [0])[0] or 0)
                cursor.execute("""
                SELECT ISNULL(SUM((SELECT ISNULL(SUM(Debit),0)+ISNULL(SUM(Credit),0) FROM TBL038 WHERE MainGuide = TBL010.CardGuide)),0)
                FROM TBL010 WHERE AgentGuide = ? AND CONVERT(date, BondDate) < ?
                """, (agent_guide, fd))
                open_bnd = float((cursor.fetchone() or [0])[0] or 0)
                opening = open_inv - open_bnd
                if opening != 0.0:
                    out_rows.append(["", "رصيد افتتاحي", "", "", "", "", "", round(opening, 2), "", "رصيد افتتاحي"])
            mothers = []
            if source_bill_guide:
                cursor.execute("""
                SELECT m.CardGuide, m.BillNumber, m.BillDate, ty.InvoiceName,
                       ISNULL((SELECT SUM(TotalValue) FROM TBL023 WHERE MainGuide = m.CardGuide),0)
                FROM TBL022 m
                LEFT JOIN TBL020 ty ON ty.CardGuide = m.MainGuide
                WHERE m.CardGuide = ?
                """, (source_bill_guide,))
                r = cursor.fetchone()
                if r:
                    mothers = [(str(r[0]), r[1] or "", str(r[2]) if r[2] else "", r[3] or "فاتورة مصدر", float(r[4] or 0))]
                else:
                    mothers = [(source_bill_guide, "", "", "فاتورة مصدر", 0.0)]
            else:
                cursor.execute("""
                SELECT DISTINCT m.CardGuide, m.BillNumber, m.BillDate, ty.InvoiceName,
                       ISNULL((SELECT SUM(TotalValue) FROM TBL023 WHERE MainGuide = m.CardGuide),0)
                FROM TBL022 c
                INNER JOIN TBL022 m ON m.CardGuide = c.SourceBill
                LEFT JOIN TBL020 ty ON ty.CardGuide = m.MainGuide
                WHERE c.SourceBill IS NOT NULL AND c.AgentGuide = ?
                  AND CONVERT(date, c.BillDate) >= ? AND CONVERT(date, c.BillDate) <= ?
                """, (agent_guide, fd, td))
                mothers = [(str(r[0]), r[1] or "", str(r[2]) if r[2] else "", r[3] or "فاتورة مصدر", float(r[4] or 0)) for r in cursor.fetchall()]
            has_bill_guide = True
            try:
                cursor.execute("SELECT TOP 1 BillGuide FROM TBL010 WHERE BillGuide IS NOT NULL")
            except Exception:
                has_bill_guide = False
            for m_guide, m_num, m_date, m_type, m_val in mothers:
                cursor.execute("""
                SELECT c.CardGuide, c.BillNumber, c.BillDate
                FROM TBL022 c
                WHERE c.SourceBill = ? AND c.AgentGuide = ?
                  AND CONVERT(date, c.BillDate) >= ? AND CONVERT(date, c.BillDate) <= ?
                ORDER BY c.BillDate, c.BillNumber
                """, (m_guide, agent_guide, fd, td))
                children = cursor.fetchall()
                for ch in children:
                    ch_guide, ch_num, ch_date = str(ch[0]), ch[1] or "", str(ch[2]) if ch[2] else ""
                    cursor.execute("SELECT ISNULL(SUM(TotalValue),0) FROM TBL023 WHERE MainGuide = ?", (ch[0],))
                    ch_val = float((cursor.fetchone() or [0])[0] or 0)
                    settlements = 0.0
                    if has_bill_guide:
                        try:
                            cursor.execute("""
                            SELECT ISNULL(SUM(amt),0) FROM (
                                SELECT (SELECT ISNULL(SUM(Debit),0)+ISNULL(SUM(Credit),0) FROM TBL038 WHERE MainGuide = b.CardGuide) AS amt
                                FROM TBL010 b WHERE b.BillGuide = ?
                            ) x
                            """, (ch[0],))
                            settlements = float((cursor.fetchone() or [0])[0] or 0)
                        except Exception:
                            pass
                    remaining = ch_val - settlements
                    days = 0
                    try:
                        bd = ch[2]
                        if bd and str(bd or "")[:10]:
                            bd_date = bd.date() if hasattr(bd, 'date') else _dt_type.strptime(str(bd)[:10], "%Y-%m-%d").date()
                            ref = as_of if isinstance(as_of, _date_type) else _dt_type.strptime(str(as_of)[:10], "%Y-%m-%d").date()
                            days = (ref - bd_date).days
                    except Exception:
                        pass
                    if days <= 7:
                        bucket = "0-7 أيام"
                    elif days <= 15:
                        bucket = "7-15 يوم"
                    elif days <= 21:
                        bucket = "15-21 يوم"
                    elif days <= 28:
                        bucket = "21-28 يوم"
                    else:
                        bucket = "أكثر من 28 يوم"
                    out_rows.append([m_num, m_type, round(m_val, 2), ch_num, ch_date, round(ch_val, 2), round(settlements, 2), round(remaining, 2), days, bucket])
            return {"columns": ["أم_رقم", "أم_النوع", "أم_القيمة", "مولودة_رقم", "مولودة_تاريخ", "مولودة_قيمة", "تسديدات", "متبقي", "أيام", "فئة_العمر"], "rows": out_rows}

        # الحركة اليومية — قيود (TBL011+TBL012) وسندات (TBL010+TBL038) في الفترة بكل الحقول
        if report_id == "daily_movement":
            out_rows = []
            cursor.execute("""
            SELECT h.EntryDate, N'قيد', h.EntryNumber, h.Notes, acc.AccountName, d.Description, ISNULL(d.Debit,0), ISNULL(d.Credit,0), h.CurrencyGuide, h.Rate
            FROM TBL012 d
            INNER JOIN TBL011 h ON h.CardGuide = d.MainGuide
            LEFT JOIN TBL004 acc ON acc.CardGuide = d.AccountGuide
            WHERE CONVERT(date, h.EntryDate) >= ? AND CONVERT(date, h.EntryDate) <= ?
            ORDER BY h.EntryDate, h.EntryNumber
            """, (fd, td))
            for r in cursor.fetchall():
                out_rows.append([str(r[0]) if r[0] else "", r[1], r[2], r[3] or "", r[4] or "", r[5] or "", float(r[6] or 0), float(r[7] or 0), str(r[8]) if r[8] else "", float(r[9] or 1)])
            cursor.execute("""
            SELECT b.BondDate, et.EntryName, b.BondNumber, b.Notes, acc.AccountName, d.Notes, ISNULL(d.Debit,0), ISNULL(d.Credit,0), b.CurrencyGuide, b.Rate
            FROM TBL038 d
            INNER JOIN TBL010 b ON b.CardGuide = d.MainGuide
            LEFT JOIN TBL009 et ON et.CardGuide = b.MainGuide
            LEFT JOIN TBL004 acc ON acc.CardGuide = d.AccountGuide
            WHERE CONVERT(date, b.BondDate) >= ? AND CONVERT(date, b.BondDate) <= ?
            ORDER BY b.BondDate, b.BondNumber
            """, (fd, td))
            for r in cursor.fetchall():
                out_rows.append([str(r[0]) if r[0] else "", r[1] or "سند", r[2], r[3] or "", r[4] or "", r[5] or "", float(r[6] or 0), float(r[7] or 0), str(r[8]) if r[8] else "", float(r[9] or 1)])
            out_rows.sort(key=lambda x: (x[0], 0 if x[1] == "قيد" else 1, x[2]))
            return {"columns": ["التاريخ", "النوع", "الرقم", "البيان", "الحساب", "وصف_البند", "مدين", "دائن", "العملة", "سعر_الصرف"], "rows": out_rows}

        # تقرير حركة صنف — حركات من TBL023 (تفاصيل فواتير)
        if report_id == "item_movement":
            if not product_guide:
                cursor.execute("SELECT TOP 100 CardGuide, ProductName, LatinName FROM TBL007 WHERE ProductName IS NOT NULL AND NotActive=0 ORDER BY ProductName")
                rows = cursor.fetchall()
                return {"columns": ["CardGuide", "ProductName", "LatinName"], "rows": [[str(r[0]), r[1] or "", r[2] or ""] for r in rows], "message": "أرسل product_guide لحركة الصنف"}
            cursor.execute("""
            SELECT CONVERT(date, h.BillDate), h.BillNumber, i.Quantity, i.TotalValue
            FROM TBL023 i
            INNER JOIN TBL022 h ON h.CardGuide = i.MainGuide
            WHERE i.ProductGuide = ? AND CONVERT(date, h.BillDate) >= ? AND CONVERT(date, h.BillDate) <= ?
            ORDER BY h.BillDate
            """, (product_guide, fd, td))
            rows = cursor.fetchall()
            qty_balance = 0.0
            out_rows = []
            for r in rows:
                qty = float(r[2] or 0)
                qty_balance -= qty
                out_rows.append([str(r[0]) if r[0] else "", r[1] or "", qty, float(r[3] or 0), round(qty_balance, 2)])
            return {"columns": ["التاريخ", "رقم_الفاتورة", "الكمية", "القيمة", "رصيد_الكمية"], "rows": out_rows}

        # تقرير جرد — أصناف مع كمية مبيعات من TBL023
        if report_id == "inventory":
            cursor.execute("""
            SELECT p.CardGuide, p.CardCode, p.ProductName, p.AgentPrice,
                   (SELECT ISNULL(SUM(i.Quantity),0) FROM TBL023 i WHERE i.ProductGuide = p.CardGuide) AS QtyOut
            FROM TBL007 p
            WHERE p.ProductName IS NOT NULL AND p.NotActive = 0
            ORDER BY p.ProductName
            """)
            rows = cursor.fetchall()
            return {"columns": ["CardGuide", "CardCode", "ProductName", "السعر", "كمية_المبيعات"], "rows": [[str(r[0]), r[1] or "", r[2] or "", float(r[3] or 0), float(r[4] or 0)] for r in rows]}

        raise HTTPException(status_code=404, detail="تقرير غير معروف")
    except HTTPException:
        raise
    except Exception as e:
        raise HTTPException(status_code=500, detail=str(e))
    finally:
        try:
            if conn:
                conn.close()
        except Exception:
            pass

