@app.get("/api/costing/unit-price")
def get_costing_unit_price(product_guide: str, invoice_type_guid: Optional[str] = None):
    """
    سعر الوحدة حسب دالة إكسترا:
    Select dbo.Fun182(8,1,@ProductGuide,0,@InvoiceTypeGuid,Null,...)
    """
    conn = get_connection()
