def _restaurant_sql_ready() -> bool:
    """جدول حالة المطعم المشتركة بين الأجهزة — أي اتصال SQL ناجح (إعدادات أو config الافتراضي)."""
    global _restaurant_sql_table_ready
    if _restaurant_sql_table_ready:
        return True
    conn = get_connection()
    if not conn:
        return False
    try:
        cursor = conn.cursor()
        # مسار سريع: أغلب بيئات التشغيل لديها الجدول بالفعل لكن بدون صلاحية CREATE/ALTER.
        # لا نحاول DDL أولًا حتى لا تفشل المشاركة بين الأجهزة بسبب صلاحيات محدودة.
        try:
            cursor.execute("SELECT TOP 1 StateKey FROM dbo.MAT3AM_RESTAURANT_STATE")
            _restaurant_sql_table_ready = True
            return True
        except Exception:
            pass
        # fallback: عند بيئة تطوير كاملة الصلاحيات نحاول إنشاء الجدول مرة واحدة.
        try:
            _restaurant_sql_ensure_table(cursor)
            conn.commit()
            _restaurant_sql_table_ready = True
            return True
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _restaurant_sql_get(key: str):
    if key not in _RESTAURANT_SQL_KEYS:
        return None
    if not _restaurant_sql_ready():
        return None
    conn = get_connection()
    if not conn:
        return None
    try:
        cursor = conn.cursor()
        cursor.execute("SET LOCK_TIMEOUT 3000")
        cursor.execute("SELECT PayloadJson FROM dbo.MAT3AM_RESTAURANT_STATE WHERE StateKey = ?", (key,))
        row = cursor.fetchone()
        if not row or row[0] is None:
            return None
        return json.loads(str(row[0]))
    except Exception:
        return None
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _restaurant_sql_set(key: str, data) -> bool:
    if key not in _RESTAURANT_SQL_KEYS:
        return False
    if not _restaurant_sql_ready():
        return False
    conn = get_connection()
    if not conn:
        return False
    try:
        cursor = conn.cursor()
        try:
            cursor.timeout = 3
        except Exception:
            pass
        cursor.execute("SET LOCK_TIMEOUT 3000")
        js = json.dumps(data, ensure_ascii=False)
        cursor.execute("SELECT 1 FROM dbo.MAT3AM_RESTAURANT_STATE WHERE StateKey = ?", (key,))
        if cursor.fetchone():
            cursor.execute(
                "UPDATE dbo.MAT3AM_RESTAURANT_STATE SET PayloadJson = ?, UpdatedAt = SYSUTCDATETIME() WHERE StateKey = ?",
                (js, key),
            )
        else:
            cursor.execute(
                "INSERT INTO dbo.MAT3AM_RESTAURANT_STATE (StateKey, PayloadJson) VALUES (?, ?)",
                (key, js),
            )
        conn.commit()
        return True
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _restaurant_sql_get_bulk(keys: list) -> dict:
    """قراءة عدة مفاتيح من MAT3AM_RESTAURANT_STATE في اتصال ODBC واحد."""
    wanted = [k for k in keys if k in _RESTAURANT_SQL_KEYS]
    if not wanted or not _restaurant_sql_ready():
        return {}
    conn = get_connection()
    if not conn:
        return {}
    out: dict = {}
    try:
        cursor = conn.cursor()
        cursor.execute("SET LOCK_TIMEOUT 3000")
        placeholders = ",".join("?" * len(wanted))
        cursor.execute(
            f"SELECT StateKey, PayloadJson FROM dbo.MAT3AM_RESTAURANT_STATE WHERE StateKey IN ({placeholders})",
            tuple(wanted),
        )
        for row in cursor.fetchall() or []:
            sk = str(row[0] or "").strip()
            if not sk or row[1] is None:
                continue
            try:
                out[sk] = json.loads(str(row[1]))
            except Exception:
                continue
    except Exception:
        return {}
    finally:
        try:
            conn.close()
        except Exception:
            pass
    return out


def _restaurant_set_local_override(name: str, data: Any) -> None:
    if name not in _RESTAURANT_FAST_LOCAL_SQL_KEYS:
        return
    with _restaurant_local_override_lock:
        _restaurant_local_overrides[name] = copy.deepcopy(data)


def _restaurant_get_local_override(name: str):
    if name not in _RESTAURANT_FAST_LOCAL_SQL_KEYS:
        return None
    with _restaurant_local_override_lock:
        current = _restaurant_local_overrides.get(name)
        return copy.deepcopy(current) if current is not None else None


def _restaurant_clear_local_override_if_match(name: str, data: Any) -> None:
    if name not in _RESTAURANT_FAST_LOCAL_SQL_KEYS:
        return
    with _restaurant_local_override_lock:
        current = _restaurant_local_overrides.get(name)
        if current == data:
            _restaurant_local_overrides.pop(name, None)


def _restaurant_sql_set_async(name: str, data: Any) -> None:
    if name not in _RESTAURANT_SQL_KEYS:
        return
    payload = copy.deepcopy(data)

    def _runner() -> None:
        ok = _restaurant_sql_set(name, payload)
        if ok:
            _restaurant_clear_local_override_if_match(name, payload)
        else:
            # #region debug-point D:sql-sync-async-failed
            _dbg_table_session_close(
                "D",
                "api_server.py:_restaurant_sql_set_async:failed",
                "async sql sync failed",
                {"key": name},
            )
            # #endregion

    threading.Thread(target=_runner, name=f"mat3am-sql-sync-{name}", daemon=True).start()


def _restaurant_write_local_file_async(name: str, data: Any) -> None:
    payload = copy.deepcopy(data)

    def _runner() -> None:
        try:
            _restaurant_write_local_file(name, payload)
        except Exception as ex:
            # #region debug-point D:file-sync-async-failed
            _dbg_table_session_close(
                "D",
                "api_server.py:_restaurant_write_local_file_async:failed",
                "async local file sync failed",
                {"key": name, "error": str(ex or "")[:280]},
            )
            # #endregion

    threading.Thread(target=_runner, name=f"mat3am-file-sync-{name}", daemon=True).start()


def _restaurant_write_local_file(name: str, data: Any) -> None:
    # #region debug-point A:write-local-start
    if name in _RESTAURANT_FAST_LOCAL_SQL_KEYS:
        _dbg_table_session_close(
            "A",
            "api_server.py:_restaurant_write_local_file:start",
            "local file write start",
            {"key": name},
        )
    # #endregion
    p = _restaurant_path(name)
    os.makedirs(os.path.dirname(p), exist_ok=True)
    last_err = None
    for _attempt in range(3):
        tmp_fd, tmp_path = tempfile.mkstemp(prefix=f"{name}.", suffix=".json.tmp", dir=os.path.dirname(p))
        try:
            with os.fdopen(tmp_fd, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
                f.flush()
            os.replace(tmp_path, p)
            last_err = None
            break
        except PermissionError as ex:
            last_err = ex
            try:
                if os.path.exists(tmp_path):
                    os.unlink(tmp_path)
            except Exception:
                pass
            import time as _time

            _time.sleep(0.15)
        except Exception:
            try:
                if os.path.exists(tmp_path):
                    os.unlink(tmp_path)
            except Exception:
                pass
            raise
    if last_err is not None:
        raise last_err
    # #region debug-point A:write-local-done
    if name in _RESTAURANT_FAST_LOCAL_SQL_KEYS:
        _dbg_table_session_close(
            "A",
            "api_server.py:_restaurant_write_local_file:done",
            "local file write done",
            {"key": name},
        )
    # #endregion


def _restaurant_load(name: str, default: Any):
    """تحميل ملفات JSON للمطعم — مع تفضيل التخزين في SQL للمفاتيح المشتركة بين الأجهزة."""
    if name in _RESTAURANT_SQL_KEYS:
        local_override = _restaurant_get_local_override(name)
        if local_override is not None:
            return local_override
        sqlv = _restaurant_sql_get(name)
        if sqlv is not None:
            return sqlv
    p = _restaurant_path(name)
    if not os.path.exists(p):
        return default
    try:
        with open(p, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return default
    return data


def _restaurant_save(name: str, data: Any):
    """حفظ حالة المطعم: للمفاتيح المشتركة يُكتب SQL أولاً ثم نسخة JSON على القرص كاحتياطي محلي."""
    if name in _RESTAURANT_FAST_LOCAL_SQL_KEYS:
        _restaurant_set_local_override(name, data)
        # #region debug-point A:fast-save-after-override
        _dbg_table_session_close(
            "A",
            "api_server.py:_restaurant_save:fast-after-override",
            "fast local save after override",
            {"key": name},
        )
        # #endregion
        _restaurant_write_local_file_async(name, data)
        _restaurant_sql_set_async(name, data)
        return
    sql_ok = False
    if name in _RESTAURANT_SQL_KEYS:
        sql_ok = _restaurant_sql_set(name, data)
    try:
        _restaurant_write_local_file(name, data)
    except Exception as ex:
        if name in _RESTAURANT_SQL_KEYS and not sql_ok:
            raise HTTPException(
                status_code=500,
                detail=f"تعذر حفظ {name}: لا اتصال SQL ولا كتابة الملف المحلي ({ex})",
            ) from ex
        if name in _RESTAURANT_SQL_KEYS and sql_ok:
            print(f"[mat3am] _restaurant_save: فشلت النسخة الاحتياطية JSON لكن SQL نجح — {name}: {ex}", flush=True)
            return
        raise
    if name in _RESTAURANT_SQL_KEYS and not sql_ok:
        print(f"[mat3am] _restaurant_save: SQL غير متاح — تُحفظ نسخة ملف فقط لـ {name}", flush=True)


def _restaurant_guid_norm(value: Any) -> str:
    return str(value or "").strip().replace("{", "").replace("}", "").upper()


def _restaurant_waiter_assignment_day_iso(calendar_iso: Optional[str] = None) -> str:
    s = str(calendar_iso or "").strip()[:10]
    if re.match(r"^\d{4}-\d{2}-\d{2}$", s):
        return s
    return datetime.now().date().isoformat()


def _restaurant_waiter_assignment_date(value: Any) -> str:
    s = str(value or "").strip()[:10]
    if re.match(r"^\d{4}-\d{2}-\d{2}$", s):
        return s
    raise HTTPException(status_code=400, detail="صيغة التاريخ يجب أن تكون YYYY-MM-DD")


def _restaurant_waiter_assignment_table_id(value: Any) -> str:
    return _norm_session_table_id(str(value or "").strip())


def _restaurant_waiter_table_assignments_load() -> List[dict]:
    raw = _restaurant_load("waiter_table_assignments", [])
    if not isinstance(raw, list):
        return []
    out: List[dict] = []
    for item in raw:
        if not isinstance(item, dict):
            continue
        uid = str(item.get("userId") or "").strip()
        if not uid:
            continue
        vf = str(item.get("validFrom") or "").strip()[:10]
        vt = str(item.get("validTo") or "").strip()[:10]
        if not re.match(r"^\d{4}-\d{2}-\d{2}$", vf) or not re.match(r"^\d{4}-\d{2}-\d{2}$", vt):
            continue
        if vf > vt:
            vf, vt = vt, vf
        table_ids: List[str] = []
        for raw_tid in (item.get("tableIds") or []):
            tid = _restaurant_waiter_assignment_table_id(raw_tid)
            if tid and tid not in table_ids:
                table_ids.append(tid)
        out.append(
            {
                "id": str(item.get("id") or uuid.uuid4()),
                "userId": uid,
                "userLogin": str(item.get("userLogin") or "").strip()[:120],
                "userName": str(item.get("userName") or "").strip()[:200],
                "validFrom": vf,
                "validTo": vt,
                "tableIds": table_ids,
                "createdAt": str(item.get("createdAt") or "").strip()[:40],
            }
        )
    return out


def _restaurant_waiter_table_assignments_save(rows: List[dict]) -> None:
    safe: List[dict] = []
    for row in rows:
        if not isinstance(row, dict):
            continue
        uid = str(row.get("userId") or "").strip()
        if not uid:
            continue
        try:
            vf = _restaurant_waiter_assignment_date(row.get("validFrom"))
            vt = _restaurant_waiter_assignment_date(row.get("validTo"))
        except HTTPException:
            continue
        if vf > vt:
            vf, vt = vt, vf
        table_ids: List[str] = []
        for raw_tid in (row.get("tableIds") or []):
            tid = _restaurant_waiter_assignment_table_id(raw_tid)
            if tid and tid not in table_ids:
                table_ids.append(tid)
        safe.append(
            {
                "id": str(row.get("id") or uuid.uuid4()),
                "userId": uid,
                "userLogin": str(row.get("userLogin") or "").strip()[:120],
                "userName": str(row.get("userName") or "").strip()[:200],
                "validFrom": vf,
                "validTo": vt,
                "tableIds": table_ids,
                "createdAt": str(row.get("createdAt") or datetime.now().isoformat()).strip()[:40],
            }
        )
    safe.sort(
        key=lambda x: (
            str(x.get("validFrom") or ""),
            str(x.get("userName") or x.get("userLogin") or ""),
            str(x.get("createdAt") or ""),
            str(x.get("id") or ""),
        )
    )
    _restaurant_save("waiter_table_assignments", safe)


