def _kids_resolve_root_group_guid(cursor) -> Optional[str]:
    """يحاول إيجاد جذر TBL006 «Kids Area Services» بالاسم اللاتيني أو العربي."""
    try:
        cursor.execute(
            """
            SELECT TOP 1 CardGuide FROM dbo.TBL006
            WHERE (LatinName IS NOT NULL AND LOWER(LTRIM(RTRIM(CAST(LatinName AS NVARCHAR(400))))) = LOWER(?))
               OR (GroupName IS NOT NULL AND LTRIM(RTRIM(CAST(GroupName AS NVARCHAR(400)))) = ?)
            ORDER BY CASE WHEN MainGuide IS NULL THEN 0 ELSE 1 END, ID
            """,
            (KIDS_ROOT_LATIN_NAME.lower(), KIDS_ROOT_AR_NAME),
        )
        r = cursor.fetchone()
        if r and r[0]:
            return str(r[0]).strip().upper()
    except Exception:
        pass
    return None


def _kids_next_root_card_code(cursor) -> str:
    """يولّد CardCode لجذر TBL006 جديد (3 خانات). يبحث عن أعلى رقم بين الجذور (MainGuide IS NULL)."""
    try:
        cursor.execute(
            "SELECT TOP 1 CardCode FROM dbo.TBL006 "
            "WHERE MainGuide IS NULL AND CardCode IS NOT NULL "
            "AND ISNUMERIC(CardCode) = 1 "
            "ORDER BY TRY_CAST(CardCode AS BIGINT) DESC"
        )
        r = cursor.fetchone()
        if r and r[0]:
            try:
                return str(int(str(r[0]).strip()) + 1)
            except Exception:
                pass
    except Exception:
        pass
    return "900"  # نطاق آمن لمنشأة لا تستخدم 9xx


def _kids_next_subgroup_card_code(cursor, root_guid: str, root_card_code: Optional[str]) -> str:
    """يولّد CardCode لباقة فرعية تحت root_guid: <root_code>NN حيث NN = max+1.

    لو الجذر بدون CardCode (سابق وقع في خطأ) يستخدم بدلاً منه طابع زمني قصير.
    """
    base = (str(root_card_code).strip() if root_card_code else "")
    try:
        if base:
            cursor.execute(
                "SELECT TOP 1 CardCode FROM dbo.TBL006 "
                "WHERE MainGuide = CAST(? AS uniqueidentifier) "
                "AND CardCode LIKE ? AND ISNUMERIC(CardCode) = 1 "
                "ORDER BY TRY_CAST(CardCode AS BIGINT) DESC",
                (root_guid, f"{base}%"),
            )
        else:
            cursor.execute(
                "SELECT TOP 1 CardCode FROM dbo.TBL006 "
                "WHERE MainGuide = CAST(? AS uniqueidentifier) "
                "AND CardCode IS NOT NULL "
                "ORDER BY TRY_CAST(CardCode AS BIGINT) DESC",
                (root_guid,),
            )
        r = cursor.fetchone()
        if r and r[0]:
            try:
                return str(int(str(r[0]).strip()) + 1)
            except Exception:
                pass
    except Exception:
        pass
    if base:
        return f"{base}01"
    # احتياط: طابع زمني قصير
    return datetime.now().strftime("9%H%M%S")


def _kids_next_product_card_code(cursor, sub_group_guid: str, sub_card_code: Optional[str]) -> str:
    """يولّد CardCode لبند TBL007 تحت مجموعة: <sub_code>NNN حيث NNN = max+1."""
    base = (str(sub_card_code).strip() if sub_card_code else "")
    try:
        if base:
            cursor.execute(
                "SELECT TOP 1 CardCode FROM dbo.TBL007 "
                "WHERE GroupGuid = CAST(? AS uniqueidentifier) "
                "AND CardCode LIKE ? AND ISNUMERIC(CardCode) = 1 "
                "ORDER BY TRY_CAST(CardCode AS BIGINT) DESC",
                (sub_group_guid, f"{base}%"),
            )
        else:
            cursor.execute(
                "SELECT TOP 1 CardCode FROM dbo.TBL007 "
                "WHERE GroupGuid = CAST(? AS uniqueidentifier) "
                "AND CardCode IS NOT NULL "
                "ORDER BY TRY_CAST(CardCode AS BIGINT) DESC",
                (sub_group_guid,),
            )
        r = cursor.fetchone()
        if r and r[0]:
            try:
                return str(int(str(r[0]).strip()) + 1)
            except Exception:
                pass
    except Exception:
        pass
    if base:
        return f"{base}001"
    return datetime.now().strftime("9%H%M%S")


def _kids_get_card_code(cursor, table: str, guid: str) -> Optional[str]:
    """يقرأ CardCode المعرّف لمجموعة/بند موجود مسبقاً."""
    try:
        cursor.execute(
            f"SELECT TOP 1 CardCode FROM dbo.{table} WHERE CardGuide = CAST(? AS uniqueidentifier)",
            (guid,),
        )
        r = cursor.fetchone()
        if r and r[0] is not None:
            return str(r[0]).strip()
    except Exception:
        pass
    return None


def _kids_ensure_root_group(cursor, conn) -> str:
    """يضمن وجود جذر TBL006 ويُعيد CardGuide له. ينشئه إن لم يوجد، مع CardCode غير NULL."""
    g = _kids_resolve_root_group_guid(cursor)
    if g:
        return g
    new_guid = str(uuid.uuid4()).upper()
    new_code = _kids_next_root_card_code(cursor)
    try:
        cursor.execute(
            """
            INSERT INTO dbo.TBL006 (CardGuide, GroupName, LatinName, MainGuide, Security, CardCode)
            VALUES (CAST(? AS uniqueidentifier), ?, ?, NULL, 1, ?)
            """,
            (new_guid, KIDS_ROOT_AR_NAME, KIDS_ROOT_LATIN_NAME, new_code),
        )
        conn.commit()
    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        raise HTTPException(status_code=500, detail=f"تعذر إنشاء مجموعة الكيدز ايريا الجذر في TBL006: {e}")
    return new_guid


def _kids_ensure_default_agent(cursor, conn) -> str:
    """عميل افتراضي «Kids Area» في TBL016 ضمن مجموعة kids_area_customers — يُنشأ مرة واحدة."""
    try:
        group_guid = _ensure_tbl015_group_by_name(cursor, conn, KIDS_AGENT_GROUP_NAME)
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"تعذر تجهيز مجموعة عملاء الكيدز ايريا: {e}")
    try:
        cursor.execute(
            """
            SELECT TOP 1 CardGuide FROM dbo.TBL016
            WHERE AgentName IS NOT NULL
              AND LOWER(LTRIM(RTRIM(AgentName))) = LOWER(?)
              AND MainGroupGuide = CAST(? AS uniqueidentifier)
            ORDER BY ID
            """,
            (KIDS_DEFAULT_AGENT_NAME, group_guid),
        )
        r = cursor.fetchone()
        if r and r[0]:
            return str(r[0]).strip().upper()
    except Exception:
        pass
    acct_guid = _pick_default_account_guid_tbl004(cursor)
    if not acct_guid:
        raise HTTPException(
            status_code=400,
            detail="لا يوجد حساب في TBL004 لربط عميل الكيدز ايريا الافتراضي. أضف حساباً أولاً.",
        )
    try:
        acct_guid = str(uuid.UUID(str(acct_guid))).upper()
    except Exception:
        raise HTTPException(status_code=400, detail="حساب TBL004 الافتراضي غير صالح GUID.")
    new_guid = str(uuid.uuid4()).upper()
    try:
        cursor.execute(
            """
            INSERT INTO dbo.TBL016 (CardGuide, AgentName, NotActive, MainGroupGuide, AccountID)
            VALUES (?, ?, 0, CAST(? AS uniqueidentifier), CAST(? AS uniqueidentifier))
            """,
            (new_guid, KIDS_DEFAULT_AGENT_NAME, group_guid, acct_guid),
        )
        conn.commit()
    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        raise HTTPException(status_code=500, detail=f"تعذر إنشاء عميل الكيدز ايريا الافتراضي: {e}")
    return new_guid


def _kids_ensure_cost_center(cursor, conn) -> Optional[str]:
    """مركز كلفة «كيدز ايريا» في TBL005 — يُنشأ إن لم يوجد. يعود None لو فشل (لا يفسد البوتستراب)."""
