def _kids_pick_default_unit_for_products(cursor) -> Optional[str]:
    try:
        cursor.execute("SELECT TOP 1 CardGuide FROM dbo.TBL019 WHERE GroupName IS NOT NULL ORDER BY ID")
        r = cursor.fetchone()
        if r and r[0]:
            return str(r[0]).strip().upper()
    except Exception:
        return None
    return None


def _kids_load_packages_from_db(cursor) -> list:
    """يقرأ الباقات (sub-groups تحت الجذر) ومنتجاتها من TBL006/TBL007."""
    root = _kids_resolve_root_group_guid(cursor)
    if not root:
        return []
    out: list = []
    try:
        cursor.execute(
            """
            SELECT CardGuide, GroupName, LatinName
            FROM dbo.TBL006
            WHERE MainGuide = CAST(? AS uniqueidentifier)
            ORDER BY ID
            """,
            (root,),
        )
        sub_groups = [
            {"groupGuide": str(r[0]).strip().upper(), "groupName": r[1] or "", "latinName": r[2] or ""}
            for r in (cursor.fetchall() or [])
        ]
    except Exception:
        return []
    for g in sub_groups:
        items: list = []
        try:
            cursor.execute(
                """
                SELECT CardGuide, ProductName, AgentPrice, EndUserPrice, Custom5, Hieght3
                FROM dbo.TBL007
                WHERE GroupGuid = CAST(? AS uniqueidentifier)
                  AND (NotActive = 0 OR NotActive IS NULL)
                ORDER BY ID
                """,
                (g["groupGuide"],),
            )
            for r in cursor.fetchall() or []:
                price = float(r[2] or r[3] or 0)
                marker = str(r[4] or "").strip()
                minutes = 0
                try:
                    minutes = int(r[5]) if r[5] is not None else 0
                except (TypeError, ValueError):
                    minutes = 0
                items.append(
                    {
                        "productGuide": str(r[0]).strip().upper(),
                        "name": str(r[1] or ""),
                        "price": price,
                        "isKitchen": marker == KIDS_KITCHEN_MARKER,
                        "minutes": minutes,
                    }
                )
        except Exception:
            items = []
        if not items:
            continue
        total_price = round(sum(float(it.get("price") or 0) for it in items), 2)
        total_minutes = max((int(it.get("minutes") or 0) for it in items), default=0)
        out.append(
            {
                "packageGuide": g["groupGuide"],
                "packageName": g["groupName"],
                "latinName": g["latinName"],
                "items": items,
                "totalPrice": total_price,
                "durationMinutes": total_minutes,
            }
        )
    return out


def _kids_bootstrap_default_packages(cursor, conn) -> int:
    """ينشئ الباقات الافتراضية إن لم توجد أي باقات تحت الجذر. يعيد عدد الباقات المُنشأة."""
    root = _kids_ensure_root_group(cursor, conn)
    try:
        cursor.execute(
            "SELECT COUNT(*) FROM dbo.TBL006 WHERE MainGuide = CAST(? AS uniqueidentifier)",
            (root,),
        )
        c = cursor.fetchone()
        if c and c[0] and int(c[0]) > 0:
            return 0
    except Exception:
        return 0
    unit_guid = _kids_pick_default_unit_for_products(cursor)
    created = 0
    code_seed = 14001
    for idx, pkg in enumerate(KIDS_DEFAULT_PACKAGES, start=1):
        sub_guid = str(uuid.uuid4()).upper()
        try:
            cursor.execute(
                """
                INSERT INTO dbo.TBL006 (CardGuide, GroupName, LatinName, MainGuide, Security, CardCode)
                VALUES (CAST(? AS uniqueidentifier), ?, ?, CAST(? AS uniqueidentifier), 1, ?)
                """,
                (sub_guid, pkg["groupName"], pkg["latinName"], root, str(code_seed + idx)),
            )
        except Exception:
            try:
                conn.rollback()
            except Exception:
                pass
            continue
        for jdx, it in enumerate(pkg["items"], start=1):
            prod_guid = str(uuid.uuid4()).upper()
            marker = KIDS_KITCHEN_MARKER if it.get("kitchen") else None
            minutes_val = int(it.get("minutes") or 0)
            try:
                if unit_guid:
                    cursor.execute(
                        """
                        INSERT INTO dbo.TBL007
                        (CardGuide, CardCode, ProductName, GroupGuid, DefaultUnit, Unit, Security,
                         AgentPrice, EndUserPrice, Custom5, Hieght3, NotActive, Source)
                        VALUES (?, ?, ?, CAST(? AS uniqueidentifier), CAST(? AS uniqueidentifier),
                                CAST(? AS uniqueidentifier), 1, ?, ?, ?, ?, 0, 1)
                        """,
                        (
                            prod_guid,
                            f"{code_seed + idx}{jdx:03d}",
                            it["name"],
                            sub_guid,
                            unit_guid,
                            unit_guid,
                            float(it["price"]),
                            float(it["price"]),
                            marker,
                            minutes_val,
                        ),
                    )
                else:
                    cursor.execute(
                        """
                        INSERT INTO dbo.TBL007
                        (CardGuide, CardCode, ProductName, GroupGuid, Security,
                         AgentPrice, EndUserPrice, Custom5, Hieght3, NotActive, Source)
                        VALUES (?, ?, ?, CAST(? AS uniqueidentifier), 1, ?, ?, ?, ?, 0, 1)
                        """,
                        (
                            prod_guid,
                            f"{code_seed + idx}{jdx:03d}",
                            it["name"],
                            sub_guid,
                            float(it["price"]),
                            float(it["price"]),
                            marker,
                            minutes_val,
                        ),
                    )
            except Exception:
                try:
                    conn.rollback()
                except Exception:
                    pass
                continue
        created += 1
    try:
        conn.commit()
    except Exception:
        pass
    return created


def _restaurant_venue_path() -> str:
    os.makedirs(_restaurant_dir, exist_ok=True)
    return os.path.join(_restaurant_dir, "venue.json")


def _restaurant_read_venue() -> dict:
    """نوع المنشأ: restaurant | coffee_shop — يغيّر افتراضيات الواجهة دون تفرع مشروع."""
    p = _restaurant_venue_path()
    if not os.path.exists(p):
        return {"venueType": "restaurant", "venueName": ""}
    try:
        with open(p, "r", encoding="utf-8") as f:
            d = json.load(f)
        if not isinstance(d, dict):
            return {"venueType": "restaurant", "venueName": ""}
        vt = str(d.get("venueType") or "restaurant").strip().lower().replace("-", "_")
        aliases_coffee = ("coffee_shop", "coffeeshop", "coffee", "cafe", "café")
        if vt in aliases_coffee:
            vt = "coffee_shop"
        elif vt != "restaurant":
            vt = "restaurant"
        vn = str(d.get("venueName") or "").strip()
        return {"venueType": vt, "venueName": vn}
    except Exception:
        return {"venueType": "restaurant", "venueName": ""}


def _restaurant_workflow_default() -> dict:
    return {
        "receiveGuestBy": "host",            # host | manager | waiter | customer_self | server
        "takeOrderBy": "waiter",             # host | manager | waiter | customer_self | server
        "deliverFromKitchenBy": "server",    # server | waiter | manager | host | operation_manager | kitchen_window | none
        "cleanTableBy": "server",            # server | waiter | manager | cleaner
        "checkRequestBy": "waiter",          # waiter | manager | cashier | server
        "cashierDispatchMode": "both",       # visa_machine | cash_collector | both
        # سياسة التنظيف (Workflow Policy)
        "cleaningStartTrigger": "payment_completed",  # request_check | payment_completed | manager_command | waiter_command
        "cleaningExecutionBy": "server",              # server | waiter | manager | cleaner
        "cleaningReviewBy": "none",                   # none | manager | waiter | cleaner
        "cleaningStartStatus": "dirty",               # dirty | cleaning
        # جرسون الطلبات (كابتن): إن فُعّل، لا يُقبل إرسال طلبات/طلب حساب إلا من مستخدم التسكين أو المدير/المطوّر.
        "orderTakerExclusiveTable": "off",            # off | on
    }


def _restaurant_workflow_path() -> str:
    os.makedirs(_restaurant_dir, exist_ok=True)
    return os.path.join(_restaurant_dir, "workflow_settings.json")


def _workflow_sql_ensure_table(cursor) -> None:
    cursor.execute(
        """
        IF OBJECT_ID(N'dbo.MAT3AM_WORKFLOW_SETTINGS', N'U') IS NULL
        BEGIN
            CREATE TABLE dbo.MAT3AM_WORKFLOW_SETTINGS (
                SettingsKey NVARCHAR(80) NOT NULL PRIMARY KEY,
                PayloadJson NVARCHAR(MAX) NULL,
                UpdatedAt DATETIME2 NOT NULL DEFAULT SYSUTCDATETIME(),
                UpdatedBy NVARCHAR(100) NULL
            );
        END
        IF NOT EXISTS (
            SELECT 1 FROM sys.indexes WHERE name = N'IX_MAT3AM_WORKFLOW_SETTINGS_UpdatedAt'
              AND object_id = OBJECT_ID(N'dbo.MAT3AM_WORKFLOW_SETTINGS')
        )
        BEGIN
            CREATE INDEX IX_MAT3AM_WORKFLOW_SETTINGS_UpdatedAt ON dbo.MAT3AM_WORKFLOW_SETTINGS(UpdatedAt DESC);
        END
        """
    )


def _workflow_sql_read() -> Optional[dict]:
    conn = get_connection()
    if not conn:
        return None
    try:
        cursor = conn.cursor()
        _workflow_sql_ensure_table(cursor)
        conn.commit()
        cursor.execute("SELECT TOP 1 PayloadJson FROM dbo.MAT3AM_WORKFLOW_SETTINGS WHERE SettingsKey = N'default'")
        row = cursor.fetchone()
        if not row or row[0] is None:
            return None
        try:
            raw = json.loads(str(row[0]))
            return raw if isinstance(raw, dict) else None
        except Exception:
            return None
    except Exception:
        try:
            conn.rollback()
        except Exception:
            pass
        return None
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _workflow_sql_write(payload: dict, updated_by: str = "system") -> bool:
    conn = get_connection()
    if not conn:
        return False
    try:
        cursor = conn.cursor()
        _workflow_sql_ensure_table(cursor)
        pj = json.dumps(payload, ensure_ascii=False)
        cursor.execute("SET LOCK_TIMEOUT 5000")
        cursor.execute(
            """
            UPDATE dbo.MAT3AM_WORKFLOW_SETTINGS
            SET PayloadJson = ?, UpdatedAt = SYSUTCDATETIME(), UpdatedBy = ?
            WHERE SettingsKey = ?
            """,
            (pj, str(updated_by or "system"), "default"),
        )
        if int(getattr(cursor, "rowcount", 0) or 0) <= 0:
            cursor.execute(
                """
                INSERT INTO dbo.MAT3AM_WORKFLOW_SETTINGS (SettingsKey, PayloadJson, UpdatedBy)
                VALUES (?, ?, ?)
                """,
                ("default", pj, str(updated_by or "system")),
            )
        conn.commit()
        return True
    except Exception as ex:
        try:
            conn.rollback()
        except Exception:
            pass
        print(f"[mat3am] _workflow_sql_write failed: {ex}", flush=True)
        return False
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _write_json_file_atomic(path: str, data: Any) -> None:
    os.makedirs(os.path.dirname(path), exist_ok=True)
    last_err = None
    for _attempt in range(3):
        tmp_fd, tmp_path = tempfile.mkstemp(prefix="mat3am.", suffix=".json.tmp", dir=os.path.dirname(path))
        try:
            with os.fdopen(tmp_fd, "w", encoding="utf-8") as f:
                json.dump(data, f, ensure_ascii=False, indent=2)
                f.flush()
            os.replace(tmp_path, path)
            last_err = None
            break
        except PermissionError as ex:
            last_err = ex
            try:
                if os.path.exists(tmp_path):
                    os.unlink(tmp_path)
            except Exception:
                pass
            import time as _time

            _time.sleep(0.15)
        except Exception:
            try:
                if os.path.exists(tmp_path):
                    os.unlink(tmp_path)
            except Exception:
                pass
            raise
    if last_err is not None:
        raise last_err


def _restaurant_read_workflow() -> dict:
    d = _restaurant_workflow_default()
    sql_obj = _workflow_sql_read()
    if isinstance(sql_obj, dict):
        for k in d.keys():
            if k in sql_obj and str(sql_obj.get(k) or "").strip():
                d[k] = str(sql_obj.get(k)).strip()
        return _restaurant_normalize_workflow_settings(d)
    p = _restaurant_workflow_path()
    if not os.path.exists(p):
        return _restaurant_normalize_workflow_settings(d)
    try:
        with open(p, "r", encoding="utf-8") as f:
            j = json.load(f)
        if isinstance(j, dict):
            for k in d.keys():
                if k in j and str(j.get(k) or "").strip():
                    d[k] = str(j.get(k)).strip()
            # migration: if legacy JSON exists and SQL has no row yet, sync once to SQL
            _workflow_sql_write(d, updated_by="json_migration")
    except Exception:
        pass
    return _restaurant_normalize_workflow_settings(d)


def _restaurant_normalize_workflow_settings(raw: dict) -> dict:
    cur = _restaurant_workflow_default()
    if not isinstance(raw, dict):
        return cur
    role_like = {
        "host",
        "manager",
        "operation_manager",
        "waiter",
        "customer_self",
        "server",
        "cashier",
        "cleaner",
        "kitchen_window",
        "none",
    }
    receive_allowed = {"host", "manager", "waiter", "customer_self", "server"}
    take_allowed = {"host", "manager", "waiter", "customer_self", "server"}
    # none = لا أحد يستلم — بإنهاء المطبخ تذهب الأصناف مباشرة للطاولة
    deliver_allowed = {
        "server",
        "waiter",
        "manager",
        "operation_manager",
        "host",
        "kitchen_window",
        "none",
    }
    clean_allowed = {"server", "waiter", "manager", "cleaner"}
    check_allowed = {"waiter", "manager", "cashier", "server"}
    dispatch_allowed = {"visa_machine", "cash_collector", "both"}
    clean_trigger_allowed = {"request_check", "payment_completed", "manager_command", "waiter_command"}
    clean_exec_allowed = {"server", "waiter", "manager", "cleaner"}
    clean_review_allowed = {"none", "manager", "waiter", "cleaner"}
    clean_start_status_allowed = {"dirty", "cleaning"}

    for k in list(cur.keys()):
        v = str(raw.get(k) or "").strip().lower()
        if not v:
            continue
        if k in ("receiveGuestBy", "takeOrderBy", "deliverFromKitchenBy", "cleanTableBy", "checkRequestBy", "cleaningExecutionBy", "cleaningReviewBy") and v not in role_like:
            continue
        cur[k] = v

    if cur["receiveGuestBy"] not in receive_allowed:
        cur["receiveGuestBy"] = "host"
    if cur["takeOrderBy"] not in take_allowed:
        cur["takeOrderBy"] = "waiter"
    if cur["deliverFromKitchenBy"] not in deliver_allowed:
        cur["deliverFromKitchenBy"] = "server"
    if cur["cleanTableBy"] not in clean_allowed:
        cur["cleanTableBy"] = "server"
    if cur["checkRequestBy"] not in check_allowed:
        cur["checkRequestBy"] = "waiter"
    if cur["cashierDispatchMode"] not in dispatch_allowed:
        cur["cashierDispatchMode"] = "both"
    if cur["cleaningStartTrigger"] not in clean_trigger_allowed:
        cur["cleaningStartTrigger"] = "payment_completed"
    if cur["cleaningExecutionBy"] not in clean_exec_allowed:
        cur["cleaningExecutionBy"] = "server"
    if cur["cleaningReviewBy"] not in clean_review_allowed:
        cur["cleaningReviewBy"] = "none"
    if cur["cleaningStartStatus"] not in clean_start_status_allowed:
        cur["cleaningStartStatus"] = "dirty"
    ox = str(cur.get("orderTakerExclusiveTable") or "").strip().lower()
    if ox in ("on", "1", "true", "yes"):
        cur["orderTakerExclusiveTable"] = "on"
    else:
        cur["orderTakerExclusiveTable"] = "off"
    # منع تضارب المفتاحين legacy/new:
    # cleanTableBy (قديم) و cleaningExecutionBy (الحالي) يجب أن يكونا نفس القيمة دائمًا.
    cur["cleanTableBy"] = cur["cleaningExecutionBy"]
    return cur


def _workflow_order_taker_exclusive_on() -> bool:
    w = _restaurant_read_workflow()
    v = str(w.get("orderTakerExclusiveTable") or "").strip().lower()
    return v in ("on", "1", "true", "yes")


def _mat3am_actor_from_body(body: object) -> dict:
    if not isinstance(body, dict):
        return {}
    a = body.get("mat3amActor")
    if not isinstance(a, dict):
        return {}
    return {
        "id": str(a.get("id") or "").strip(),
        "login": str(a.get("login") or "").strip(),
        "name": str(a.get("name") or "").strip(),
        "role": str(a.get("role") or "").strip().lower(),
    }


def _restaurant_session_by_id(session_id: str) -> Optional[dict]:
    sid = str(session_id or "").strip()
    if not sid:
        return None
    data = _restaurant_load("table_sessions", [])
    if not isinstance(data, list):
        return None
    for s in data:
        if isinstance(s, dict) and str(s.get("id") or "").strip() == sid:
            return s
    return None


def _order_taker_exclusive_violation(session: dict, body: dict) -> Optional[str]:
    """إن وُجدت رسالة فالمستخدم الحالي لا يجوز له العمل على جلسة الكابتن."""
    if not _workflow_order_taker_exclusive_on():
        return None
    if not isinstance(session, dict):
        return None
    if str(session.get("status") or "").lower() != "active":
        return None
    actor = _mat3am_actor_from_body(body)
    aid = str(actor.get("id") or "").strip()
    role = str(actor.get("role") or "").strip().lower()
    if _role_has_manager_ops_access(role):
        return None
    if not aid:
        return "أرسل مع الطلب mat3amActor (المستخدم الحالي) لتفعيل قفل الكابتن."
    cap = str(session.get("captainUserId") or "").strip()
    if not cap:
        return None
    if cap == aid:
        return None
    cname = str(session.get("captainName") or session.get("captainLogin") or "").strip() or "كابتن آخر"
    return f"الطاولة مسندة إلى {cname}. اضغط «تسكين كابتن» إن كنت المسؤول أو يتدخل المدير."


def _restaurant_assert_order_taker_may_use_session(session_id: str, body: dict) -> None:
    sess = _restaurant_session_by_id(session_id)
    if not isinstance(sess, dict):
        return
    err = _order_taker_exclusive_violation(sess, body)
    if err:
        raise HTTPException(status_code=403, detail=err)


def _restaurant_assert_same_captain_for_request_bill(session_id: str, body: dict) -> None:
    """طلب الحساب: يجب أن يكون من نفس الكابتن المسكّن (إلا المدير/المطوّر)."""
    sess = _restaurant_session_by_id(session_id)
    if not isinstance(sess, dict):
        return
    if str(sess.get("status") or "").lower() != "active":
        return
    actor = _mat3am_actor_from_body(body if isinstance(body, dict) else {})
    role = str(actor.get("role") or "").strip().lower()
    if _role_has_manager_ops_access(role):
        return
    aid = str(actor.get("id") or "").strip()
    if not aid:
        raise HTTPException(status_code=403, detail="طلب الحساب يتطلب mat3amActor للمستخدم الحالي.")
    cap = str(sess.get("captainUserId") or "").strip()
    if not cap:
        raise HTTPException(status_code=409, detail="لا يوجد كابتن مسكّن على الجلسة. نفّذ «تسكين كابتن» أولاً.")
    if cap != aid:
        cname = str(sess.get("captainName") or sess.get("captainLogin") or "").strip() or "كابتن آخر"
        raise HTTPException(status_code=403, detail=f"طلب الحساب مسموح فقط لنفس المسكّن: {cname}.")


def _restaurant_write_workflow(body: dict) -> dict:
    cur = _restaurant_read_workflow()
    merged = dict(cur)
    if isinstance(body, dict):
        for k in list(merged.keys()):
            if k in body and str(body.get(k) or "").strip():
                merged[k] = str(body.get(k)).strip()
    cur = _restaurant_normalize_workflow_settings(merged)
    p = _restaurant_workflow_path()
    sql_ok = _workflow_sql_write(cur, updated_by="settings_ui")
    if sql_ok:
        return cur
    try:
        _write_json_file_atomic(p, cur)
    except Exception as ex:
        raise
    return cur


def _workflow_role_for(action: str) -> str:
    w = _restaurant_read_workflow()
    a = str(action or "").strip().lower()
    if a == "receive_guest":
        return str(w.get("receiveGuestBy") or "host")
    if a == "take_order":
        return str(w.get("takeOrderBy") or "waiter")
    if a == "pickup_kitchen":
        return str(w.get("deliverFromKitchenBy") or "server")
    if a == "clean_table":
        return str(w.get("cleaningExecutionBy") or w.get("cleanTableBy") or "server")
    if a == "request_check":
        return str(w.get("checkRequestBy") or "waiter")
    if a == "dispatch_cashier":
        return str(w.get("cashierDispatchMode") or "both")
    return "waiter"


def _workflow_kitchen_needs_runner() -> bool:
    """True إن كان مسار التسليم عبر دور استلام (مناولة/جرسون…) وليس مباشرة للطاولة."""
    role = str(_workflow_role_for("pickup_kitchen") or "server").strip().lower()
    return role in ("server", "waiter", "manager", "operation_manager", "host")


def _workflow_delivery_receiver_role() -> str:
    w = _restaurant_read_workflow()
    role = str(w.get("deliverFromKitchenBy") or "server").strip().lower()
    if role in ("server", "waiter", "manager", "operation_manager", "host"):
        return role
    # none | kitchen_window | أي قيمة أخرى = لا طابور استلام
    return "none"


def _workflow_apply_cleaning_policy(table_id: str, event: str, actor_role: Optional[str] = None) -> dict:
    """
    event: request_check | payment_completed | direct_command
    actor_role عند direct_command: manager | waiter
    """
    tid = str(table_id or "").strip()
    if not tid:
        return {"applied": False, "reason": "missing_table_id"}
    wf = _restaurant_read_workflow()
    trigger = str(wf.get("cleaningStartTrigger") or "payment_completed").strip().lower()
    actor = str(actor_role or "").strip().lower()
    ev = str(event or "").strip().lower()
    should = False
    if trigger in ("request_check", "payment_completed") and ev == trigger:
        should = True
    elif trigger == "manager_command" and ev == "direct_command" and actor == "manager":
        should = True
    elif trigger == "waiter_command" and ev == "direct_command" and actor == "waiter":
        should = True
    if not should:
        return {"applied": False, "reason": "trigger_not_matched", "trigger": trigger, "event": ev, "actorRole": actor}
    status = str(wf.get("cleaningStartStatus") or "dirty").strip().lower()
    if status not in ("dirty", "cleaning"):
        status = "dirty"
    restaurant_update_table_status(tid, {"status": status})
    return {"applied": True, "tableId": tid, "status": status, "trigger": trigger, "event": ev}


@app.get("/api/restaurant/workflow-settings")
def restaurant_workflow_settings_get():
    return _restaurant_read_workflow()


@app.put("/api/restaurant/workflow-settings")
def restaurant_workflow_settings_put(body: dict):
    return _restaurant_write_workflow(body if isinstance(body, dict) else {})


# ============================================================
# Shared Terminal Mode (Mandatory PIN Overlay) — إعدادات/تحقق/سجل تدقيق
# ------------------------------------------------------------
# يتعامل مع جدول MAT3AM_TERMINAL_SETTINGS (سطر واحد StateKey='global')
# + MAT3AM_TERMINAL_PIN_AUDIT (كل محاولة) + MAT3AM_TERMINAL_LOCKOUT (قفل بعد محاولات).
# يُصدر token قصير العمر مُوقَّع HMAC-SHA256 يربط terminalId+userId+expiresAt.
# الأدوار الحساسة على السيرفر تستدعي _terminal_require_user(actor) قبل التنفيذ
# عندما يكون SharedTerminalEnabled=1 — وإلا تعمل بالسلوك القديم بلا تغيير.
# ============================================================

TERMINAL_SETTINGS_DEFAULTS = {
    "sharedTerminalEnabled": False,
    "cardReaderHandoverEnabled": False,  # تسليم الكابتن بقارئ بطاقات (PIN = رقم الكارد)
    # — النمط الافتراضي الجديد: هجين «نافذة منزلقة + step-up للعمليات الخطرة» —
    "slidingRefreshAfterAction": True,   # عمليات روتينية تجدّد العداد بدون قفل
    "stepUpForDangerOps": True,          # العمليات الخطرة تطلب PIN فوري في مكانها
    "idleLockMinutes": 2,                # نافذة الخمول الأساسية (دقائق)
    "hardLogoutMinutes": 10,             # خروج كامل بعد هذا الزمن من الإهمال
    # — الإعدادات الكلاسيكية (تستخدم فقط عند slidingRefreshAfterAction = False) —
    "lockAfterSave": False,
    "lockAfterEdit": False,
    "lockAfterSend": False,
    "lockAfterDelete": False,
    "lockAfterDiscount": False,
    "lockAfterReturn": False,
    "maxAttemptsBeforeLockout": 3,
    "lockoutSeconds": 30,
    "tokenTtlSeconds": 900,
}

# سرّ التوقيع: يُؤخذ من البيئة، أو يُولَّد ثابتاً لكل تشغيل (يُستحسن إعداد متغير دائم في الإنتاج).
_TERMINAL_TOKEN_SECRET_ENV = os.environ.get("MAT3AM_TERMINAL_TOKEN_SECRET", "").strip()
_TERMINAL_TOKEN_SECRET_RUNTIME = (_TERMINAL_TOKEN_SECRET_ENV or uuid.uuid4().hex + uuid.uuid4().hex).encode("utf-8")


def _terminal_token_secret() -> bytes:
    return _TERMINAL_TOKEN_SECRET_RUNTIME


def _b64u(b: bytes) -> str:
    import base64
    return base64.urlsafe_b64encode(b).rstrip(b"=").decode("ascii")


def _b64u_decode(s: str) -> bytes:
    import base64
    pad = "=" * (-len(s) % 4)
    return base64.urlsafe_b64decode(s + pad)


def _terminal_token_sign(payload: dict) -> str:
    """يبني token بصيغة base64url(payload_json).base64url(hmac_sha256). بسيط ومحلّي بلا تبعيات JWT."""
    import hmac, hashlib
    p = _b64u(json.dumps(payload, separators=(",", ":"), ensure_ascii=False).encode("utf-8"))
    sig = hmac.new(_terminal_token_secret(), p.encode("ascii"), hashlib.sha256).digest()
    return f"{p}.{_b64u(sig)}"


def _terminal_token_verify(token: str) -> Optional[dict]:
    """يتحقق توقيع الـtoken وانتهاء الصلاحية. يعيد payload أو None."""
    if not token or "." not in token:
        return None
    try:
        import hmac, hashlib
        p, sig = token.split(".", 1)
        expected = hmac.new(_terminal_token_secret(), p.encode("ascii"), hashlib.sha256).digest()
        if not hmac.compare_digest(_b64u(expected), sig):
            return None
        payload = json.loads(_b64u_decode(p).decode("utf-8"))
        if not isinstance(payload, dict):
            return None
        exp = int(payload.get("exp") or 0)
        if exp <= int(datetime.utcnow().timestamp()):
            return None
        return payload
    except Exception:
        return None


def _terminal_settings_load(cursor) -> dict:
    """يقرأ صف الإعدادات الوحيد ويُعيد dict camelCase. ينشئه إن غاب.
    ملاحظة: الحقول الجديدة (SlidingRefreshAfterAction/HardLogoutMinutes/StepUpForDangerOps)
    تُقرأ في استعلام منفصل بـ try/except حتى لا نكسر القراءة لو لم يُنفَّذ ALTER بعد."""
    try:
        cursor.execute(
            """
            SELECT TOP 1 SharedTerminalEnabled, IdleLockMinutes,
                   LockAfterSave, LockAfterEdit, LockAfterSend,
                   LockAfterDelete, LockAfterDiscount, LockAfterReturn,
                   MaxAttemptsBeforeLockout, LockoutSeconds, TokenTtlSeconds,
                   UpdatedAt, UpdatedBy
            FROM dbo.MAT3AM_TERMINAL_SETTINGS WHERE StateKey = N'global'
            """
        )
        r = cursor.fetchone()
    except Exception:
        return dict(TERMINAL_SETTINGS_DEFAULTS)
    if not r:
        try:
            cursor.execute("INSERT INTO dbo.MAT3AM_TERMINAL_SETTINGS (StateKey) VALUES (N'global')")
            cursor.connection.commit()
        except Exception:
            try: cursor.connection.rollback()
            except Exception: pass
        return dict(TERMINAL_SETTINGS_DEFAULTS)
    out = {
        "sharedTerminalEnabled": bool(r[0]),
        "idleLockMinutes": int(r[1] or 2),
        "lockAfterSave": bool(r[2]),
        "lockAfterEdit": bool(r[3]),
        "lockAfterSend": bool(r[4]),
        "lockAfterDelete": bool(r[5]),
        "lockAfterDiscount": bool(r[6]),
        "lockAfterReturn": bool(r[7]),
        "maxAttemptsBeforeLockout": int(r[8] or 3),
        "lockoutSeconds": int(r[9] or 30),
        "tokenTtlSeconds": int(r[10] or 900),
        "updatedAt": r[11].isoformat() if r[11] else None,
        "updatedBy": r[12] or "",
        # افتراضات لو الأعمدة الجديدة لم تُنفّذ بعد
        "slidingRefreshAfterAction": True,
        "hardLogoutMinutes": 10,
        "stepUpForDangerOps": True,
        "cardReaderHandoverEnabled": False,
    }
    try:
        cursor.execute(
            """
            SELECT TOP 1 SlidingRefreshAfterAction, HardLogoutMinutes, StepUpForDangerOps
            FROM dbo.MAT3AM_TERMINAL_SETTINGS WHERE StateKey = N'global'
            """
        )
        r2 = cursor.fetchone()
        if r2:
            out["slidingRefreshAfterAction"] = bool(r2[0])
            out["hardLogoutMinutes"] = int(r2[1] or 10)
            out["stepUpForDangerOps"] = bool(r2[2])
    except Exception:
        pass
    try:
        cursor.execute(
            """
            SELECT TOP 1 CardReaderHandoverEnabled
            FROM dbo.MAT3AM_TERMINAL_SETTINGS WHERE StateKey = N'global'
            """
        )
        r3 = cursor.fetchone()
        if r3 is not None:
            out["cardReaderHandoverEnabled"] = bool(r3[0])
    except Exception:
        pass
    return out


def _terminal_settings_save(cursor, body: dict, by_name: str) -> dict:
    """يُحدّث صف الإعدادات (UPSERT). يقتصر على المفاتيح المسموحة."""
    cur_st = _terminal_settings_load(cursor)
    merged = dict(cur_st)
    for k in TERMINAL_SETTINGS_DEFAULTS.keys():
        if k in body and body[k] is not None:
            merged[k] = body[k]
    # validation
    try:
        merged["idleLockMinutes"] = max(1, min(60, int(merged["idleLockMinutes"])))
    except Exception:
        merged["idleLockMinutes"] = 2
    try:
        merged["hardLogoutMinutes"] = max(1, min(240, int(merged.get("hardLogoutMinutes", 10))))
    except Exception:
        merged["hardLogoutMinutes"] = 10
    try:
        merged["maxAttemptsBeforeLockout"] = max(1, min(20, int(merged["maxAttemptsBeforeLockout"])))
    except Exception:
        merged["maxAttemptsBeforeLockout"] = 3
    try:
        merged["lockoutSeconds"] = max(5, min(900, int(merged["lockoutSeconds"])))
    except Exception:
        merged["lockoutSeconds"] = 30
    try:
        merged["tokenTtlSeconds"] = max(60, min(7200, int(merged["tokenTtlSeconds"])))
    except Exception:
        merged["tokenTtlSeconds"] = 900
    cursor.execute(
        """
        UPDATE dbo.MAT3AM_TERMINAL_SETTINGS
           SET SharedTerminalEnabled = ?, IdleLockMinutes = ?,
               LockAfterSave = ?, LockAfterEdit = ?, LockAfterSend = ?,
               LockAfterDelete = ?, LockAfterDiscount = ?, LockAfterReturn = ?,
               MaxAttemptsBeforeLockout = ?, LockoutSeconds = ?, TokenTtlSeconds = ?,
               UpdatedAt = SYSUTCDATETIME(), UpdatedBy = ?
         WHERE StateKey = N'global'
        """,
        (
            1 if merged["sharedTerminalEnabled"] else 0,
            int(merged["idleLockMinutes"]),
            1 if merged["lockAfterSave"] else 0,
            1 if merged["lockAfterEdit"] else 0,
            1 if merged["lockAfterSend"] else 0,
            1 if merged["lockAfterDelete"] else 0,
            1 if merged["lockAfterDiscount"] else 0,
            1 if merged["lockAfterReturn"] else 0,
            int(merged["maxAttemptsBeforeLockout"]),
            int(merged["lockoutSeconds"]),
            int(merged["tokenTtlSeconds"]),
            (str(by_name or "")[:120] or None),
        ),
    )
    # Update الحقول الجديدة بشكل منفصل (لا يكسر لو الأعمدة لم تُضَف بعد)
    try:
        cursor.execute(
            """
            UPDATE dbo.MAT3AM_TERMINAL_SETTINGS
               SET SlidingRefreshAfterAction = ?, HardLogoutMinutes = ?, StepUpForDangerOps = ?
             WHERE StateKey = N'global'
            """,
            (
                1 if merged.get("slidingRefreshAfterAction", True) else 0,
                int(merged.get("hardLogoutMinutes", 10)),
                1 if merged.get("stepUpForDangerOps", True) else 0,
            ),
        )
    except Exception:
        # الأعمدة الجديدة غير موجودة بعد — نتجاهل
        try: cursor.connection.rollback()
        except Exception: pass
    try:
        cursor.execute(
            """
            UPDATE dbo.MAT3AM_TERMINAL_SETTINGS
               SET CardReaderHandoverEnabled = ?
             WHERE StateKey = N'global'
            """,
            (1 if merged.get("cardReaderHandoverEnabled") else 0,),
        )
    except Exception:
        pass
    cursor.connection.commit()
    return _terminal_settings_load(cursor)


def _terminal_pin_audit(cursor, *, terminal_id: str, login: Optional[str],
                        old_uid: Optional[str], new_uid: Optional[str],
                        action: str, reason: Optional[str],
                        ip: Optional[str], ua: Optional[str]) -> None:
    try:
        cursor.execute(
            """
            INSERT INTO dbo.MAT3AM_TERMINAL_PIN_AUDIT
            (TerminalId, AttemptedLogin, OldUserId, NewUserId, ActionType, Reason, ClientIp, UserAgent)
            VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                str(terminal_id or "unknown")[:120],
                (str(login or "")[:120] or None),
                (str(old_uid or "")[:64] or None),
                (str(new_uid or "")[:64] or None),
                str(action or "pin_fail")[:40],
                (str(reason or "")[:120] or None),
                (str(ip or "")[:64] or None),
                (str(ua or "")[:400] or None),
            ),
        )
        cursor.connection.commit()
    except Exception:
        try: cursor.connection.rollback()
        except Exception: pass


def _terminal_get_lockout(cursor, terminal_id: str) -> tuple:
    """يعيد (failedAttempts, lockedUntilUtc_or_None)."""
    try:
        cursor.execute(
            "SELECT FailedAttempts, LockedUntilUtc FROM dbo.MAT3AM_TERMINAL_LOCKOUT WHERE TerminalId = ?",
            (str(terminal_id or "unknown")[:120],),
        )
        r = cursor.fetchone()
        if not r:
            return (0, None)
        return (int(r[0] or 0), r[1])
    except Exception:
        return (0, None)


def _terminal_record_failure(cursor, terminal_id: str, max_attempts: int, lockout_seconds: int) -> tuple:
    """يحدّث (أو يُدخل) صف القفل بعد محاولة فاشلة. يعيد (failedAttempts, lockedUntilUtc_or_None)."""
    from datetime import timedelta as _td
    fails, until = _terminal_get_lockout(cursor, terminal_id)
    fails = int(fails or 0) + 1
    new_until = until
    if fails >= int(max_attempts or 3):
        new_until = datetime.utcnow() + _td(seconds=int(lockout_seconds or 30))
    try:
        cursor.execute(
            """
            MERGE dbo.MAT3AM_TERMINAL_LOCKOUT AS t
            USING (SELECT ? AS TerminalId) AS s
               ON t.TerminalId = s.TerminalId
            WHEN MATCHED THEN UPDATE SET FailedAttempts = ?, LockedUntilUtc = ?, LastAttemptAt = SYSUTCDATETIME()
            WHEN NOT MATCHED THEN INSERT (TerminalId, FailedAttempts, LockedUntilUtc, LastAttemptAt)
                                  VALUES (?, ?, ?, SYSUTCDATETIME());
            """,
            (str(terminal_id or "unknown")[:120], fails, new_until,
             str(terminal_id or "unknown")[:120], fails, new_until),
        )
        cursor.connection.commit()
    except Exception:
        try: cursor.connection.rollback()
        except Exception: pass
    return (fails, new_until)


def _terminal_clear_lockout(cursor, terminal_id: str) -> None:
    try:
        cursor.execute(
            "DELETE FROM dbo.MAT3AM_TERMINAL_LOCKOUT WHERE TerminalId = ?",
            (str(terminal_id or "unknown")[:120],),
        )
        cursor.connection.commit()
    except Exception:
        try: cursor.connection.rollback()
        except Exception: pass


def _terminal_pin_compare(stored: str, presented: str) -> bool:
    """نقبل: نص خام مطابق (للنظام القديم) أو sha256-hex(PIN) لمستخدمين جدد إن أُدخل بصيغة مهشّمة."""
    if not stored or not presented:
        return False
    try:
        import hmac, hashlib
        if hmac.compare_digest(str(stored).strip(), str(presented).strip()):
            return True
        h = hashlib.sha256(str(presented).strip().encode("utf-8")).hexdigest()
        if hmac.compare_digest(str(stored).strip().lower(), h.lower()):
            return True
    except Exception:
        return False
    return False


def _terminal_resolve_user_by_pin(cursor, pin: str, login_hint: Optional[str] = None) -> Optional[dict]:
    """يحاول إيجاد مستخدم نشط في MAT3AM_APP_USERS بـ PIN معطى.
    لو مرّر login_hint نطابق ضمن سجلّ ذلك المستخدم فقط (أكثر أماناً عند تكرار PIN قصير)."""
    if not pin:
        return None
    try:
        if login_hint:
            cursor.execute(
                """
                SELECT TOP 1 Id, LoginName, DisplayName, RoleCode, PinHash, IsActive, SpecialistStationCode
                FROM dbo.MAT3AM_APP_USERS
                WHERE LoginName = ? AND IsActive = 1
                """,
                (str(login_hint).strip().lower(),),
            )
            r = cursor.fetchone()
            if r and _terminal_pin_compare(str(r[4] or ""), pin):
                return {
                    "id": str(r[0]).strip().upper(),
                    "login": r[1],
                    "name": r[2],
                    "role": (r[3] or "").lower(),
                    "specialistStationCode": str(r[6] or "").strip().lower(),
                }
            return None
        cursor.execute(
            """
            SELECT Id, LoginName, DisplayName, RoleCode, PinHash, IsActive, SpecialistStationCode
            FROM dbo.MAT3AM_APP_USERS WHERE IsActive = 1 ORDER BY CreatedAt DESC
            """
        )
        for r in cursor.fetchall() or []:
            if _terminal_pin_compare(str(r[4] or ""), pin):
                return {
                    "id": str(r[0]).strip().upper(),
                    "login": r[1],
                    "name": r[2],
                    "role": (r[3] or "").lower(),
                    "specialistStationCode": str(r[6] or "").strip().lower(),
                }
    except Exception:
        return None
    return None


# In-memory TTL cache للإعدادات — يُجدَّد كل CACHE_TTL_SEC ثانية.
# مهم للأداء: قبل الـcache كل طلب حسّاس كان يفتح conn ويستدعي _ensure_mat3am_dev_schema
# (≈60 DDL idempotent) ⇒ استنزاف pool وعدم استقرار اتصال DB في الذروة.
_TERMINAL_SETTINGS_CACHE: dict = {"data": None, "fetched_at": 0.0}
_TERMINAL_SETTINGS_CACHE_TTL_SEC = 30.0


def _terminal_invalidate_settings_cache() -> None:
    _TERMINAL_SETTINGS_CACHE["data"] = None
    _TERMINAL_SETTINGS_CACHE["fetched_at"] = 0.0


def _terminal_get_settings_cached() -> dict:
    """قراءة الإعدادات بـ TTL cache (30 ثانية).
    - لا يستدعي _ensure_mat3am_dev_schema (DDL يجب أن يُنفّذ في startup فقط).
    - عند تعذّر الاتصال يعيد القيم المحفوظة سابقاً (lab survival)، أو الافتراضي."""
    import time as _time
    now = _time.time()
    cached = _TERMINAL_SETTINGS_CACHE.get("data")
    fetched_at = float(_TERMINAL_SETTINGS_CACHE.get("fetched_at") or 0.0)
    if cached is not None and (now - fetched_at) < _TERMINAL_SETTINGS_CACHE_TTL_SEC:
        return cached
    conn = get_connection()
    if not conn:
        # لا اتصال: استعمل آخر قيمة مكاشة، أو الافتراضيات
        return cached if cached is not None else dict(TERMINAL_SETTINGS_DEFAULTS)
    try:
        cur = conn.cursor()
        out = _terminal_settings_load(cur)
        _TERMINAL_SETTINGS_CACHE["data"] = out
        _TERMINAL_SETTINGS_CACHE["fetched_at"] = now
        return out
    except Exception:
        return cached if cached is not None else dict(TERMINAL_SETTINGS_DEFAULTS)
    finally:
        try: conn.close()
        except Exception: pass


def _terminal_role_pin_exempt(role: Optional[str]) -> bool:
    """المطوّر معفى من PIN المشترك — للتهيئة وإعداد SQL دون حظر overlay."""
    return str(role or "").strip().lower() == "developer"


def _terminal_require_user(actor: Optional[dict]) -> Optional[dict]:
    """يُستدعى من endpoints الحسّاسة:
    - لو SharedTerminalEnabled=False ⇒ يعيد actor كما هو (لا تغيير في السلوك القديم).
    - لو True ⇒ يجب أن يحوي actor.terminalToken صالحاً، وإلا HTTPException(401).
      عند النجاح يُرجع dict {id, login, role, name, terminalId, exp} المستخرَج من الـtoken.
    - دور developer معفى دائماً (تهيئة أولية حتى بدون PinHash).
    """
    st = _terminal_get_settings_cached()
    if not st.get("sharedTerminalEnabled"):
        return actor if isinstance(actor, dict) else None
    if isinstance(actor, dict) and _terminal_role_pin_exempt(actor.get("role")):
        return actor
    if not isinstance(actor, dict):
        raise HTTPException(status_code=401, detail="Shared Terminal Mode مفعّل: أرسل mat3amActor مع terminalToken صادر بعد التحقق بـ PIN.")
    tok = str(actor.get("terminalToken") or "").strip()
    payload = _terminal_token_verify(tok) if tok else None
    if not payload:
        raise HTTPException(status_code=401, detail="Shared Terminal Mode: الـ terminalToken مفقود/منتهي. أعد إدخال PIN.")
    return {
        "id": payload.get("uid"),
        "login": payload.get("login"),
        "name": payload.get("name") or actor.get("name"),
        "role": payload.get("role") or actor.get("role"),
        "terminalId": payload.get("tid"),
        "exp": payload.get("exp"),
    }


@app.get("/api/settings/shared-terminal")
def settings_shared_terminal_get():
    return _terminal_get_settings_cached()


@app.put("/api/settings/shared-terminal")
def settings_shared_terminal_put(body: dict):
    body = body if isinstance(body, dict) else {}
    by_name = str((body.get("mat3amActor") or {}).get("name") or "")
    conn = get_connection()
    if not conn:
        raise HTTPException(status_code=503, detail="فشل الاتصال بقاعدة البيانات")
    try:
        cur = conn.cursor()
        # DDL يُضمن في startup؛ هنا فقط حفظ سريع (نتسامح لو الجدول غاب)
        try: _ensure_mat3am_dev_schema(cur)
        except Exception: pass
        out = _terminal_settings_save(cur, body, by_name)
        # أبطل الـcache فوراً ⇒ القراءة التالية تجلب القيم المحدثة
        _terminal_invalidate_settings_cache()
        return out
    finally:
        try: conn.close()
        except Exception: pass


# ---------- Telegram Ops Pulse (تقرير المالك/المدير) ----------
_TELEGRAM_OPS_RUNTIME = None


def _telegram_ops_build_context() -> dict:
    snap = {}
    try:
        snap = _restaurant_operational_snapshot_sync(False) or {}
    except Exception as e:
        print(f"[telegram-ops] snapshot: {e}", flush=True)
        snap = {}
    tickets = []
    try:
        tickets = _delivery_tickets_load() or []
    except Exception as e:
        print(f"[telegram-ops] delivery: {e}", flush=True)
    pending = []
    try:
        rows = _manager_approval_requests_load() or []
        pending = [
            r
            for r in rows
            if isinstance(r, dict)
            and str(r.get("status") or "").strip().lower() == _MANAGER_APPROVAL_STATUS_PENDING
        ]
    except Exception as e:
        print(f"[telegram-ops] approvals: {e}", flush=True)
    venue = "المطعم"
    try:
        ops = _restaurant_read_ops_storage()
        if isinstance(ops, dict):
            venue = str(ops.get("venueName") or ops.get("restaurantName") or venue).strip() or venue
    except Exception:
        pass
    try:
        if os.path.isfile(_settings_path):
            with open(_settings_path, "r", encoding="utf-8") as f:
                raw_st = json.load(f)
            if isinstance(raw_st, dict):
                venue = str(raw_st.get("venueName") or raw_st.get("restaurantName") or venue).strip() or venue
    except Exception:
        pass
    return {
        "snap": snap if isinstance(snap, dict) else {},
        "deliveryTickets": tickets if isinstance(tickets, list) else [],
        "pendingApprovals": pending,
        "venueLabel": venue,
    }


def _telegram_ops_runtime():
    global _TELEGRAM_OPS_RUNTIME
    if _TELEGRAM_OPS_RUNTIME is not None:
        return _TELEGRAM_OPS_RUNTIME
    import telegram_ops_pulse as tg_ops

    _TELEGRAM_OPS_RUNTIME = tg_ops.OpsPulseRuntime(
        settings_path_fn=lambda: _restaurant_path("telegram_ops_pulse"),
        build_context_fn=_telegram_ops_build_context,
    )
    return _TELEGRAM_OPS_RUNTIME


