def _normalize_vip_owner_templates_json(val: str) -> str:
    """قوالب عملاء VIP/Owners — مرجع لشريحة الطاولة (بدون تخزين خارجي)."""
    raw = (val or "").strip()
    if not raw:
        return "[]"
    try:
        arr = json.loads(raw)
    except (json.JSONDecodeError, TypeError):
        return "[]"
    if not isinstance(arr, list):
        return "[]"
    out: list[dict] = []
    seen: set[str] = set()
    for x in arr[:40]:
        if not isinstance(x, dict):
            continue
        tid = str(x.get("id") or "").strip()
        if not tid:
            tid = str(uuid.uuid4())
        if tid in seen:
            continue
        ag = str(x.get("agentGuid") or "").strip().upper()
        if ag:
            try:
                uuid.UUID(ag)
            except Exception:
                continue
        seen.add(tid)
        try:
            disc = float(str(x.get("discountPct") or "0").replace(",", "."))
            disc = max(0.0, min(100.0, disc))
        except Exception:
            disc = 0.0
        try:
            markup = float(str(x.get("costMarkupPct") or "0").replace(",", "."))
            markup = max(0.0, min(400.0, markup))
        except Exception:
            markup = 0.0
        disc_en = _truthy_flag(x.get("discountEnabled"))
        if not disc_en:
            disc = 0.0
        lbl = str(x.get("label") or "").strip()[:200]
        # ag قد يكون فارغاً لصف مسودّة من الواجهة حتى يُختَر عميل من TBL016
        out.append(
            {
                "id": tid,
                "agentGuid": ag,
                "label": lbl,
                "noService": _truthy_flag(x.get("noService")),
                "noVat": _truthy_flag(x.get("noVat")),
                "discountEnabled": disc_en,
                "discountPct": disc,
                "costPricingEnabled": _truthy_flag(x.get("costPricingEnabled")),
                "costMarkupPct": markup,
            }
        )
    return json.dumps(out, ensure_ascii=False, separators=(",", ":"))


def _normalize_kitchen_specialist_chefs_json(val: str, allowed_station_codes: Optional[set[str]] = None) -> str:
    raw = (val or "").strip()
    if not raw:
        return "[]"
    try:
        arr = json.loads(raw)
    except Exception:
        return "[]"
    if not isinstance(arr, list):
        return "[]"
    out = []
    seen_ids: set[str] = set()
    seen_station_codes: set[str] = set()
    for x in arr[:60]:
        if not isinstance(x, dict):
            continue
        rid = str(x.get("id") or "").strip() or str(uuid.uuid4())
        if rid in seen_ids:
            continue
        seen_ids.add(rid)
        label = str(x.get("label") or "").strip()[:120]
        job_title = str(x.get("jobTitle") or "").strip()[:120]
        active = _truthy_flag(x.get("active"), default=True)
        station_code = re.sub(r"[^a-z0-9_-]+", "_", str(x.get("stationCode") or "").strip().lower())[:80].strip("_")
        if allowed_station_codes is not None and station_code and station_code not in allowed_station_codes:
            continue
        if station_code and station_code in seen_station_codes:
            continue
        if station_code:
            seen_station_codes.add(station_code)
        user_id = str(x.get("userId") or "").strip().upper()
        if user_id:
            try:
                uuid.UUID(user_id)
            except Exception:
                user_id = ""
        user_login = str(x.get("userLogin") or "").strip().lower()[:120]
        product_guids = []
        seen_products: set[str] = set()
        raw_products = x.get("productGuids")
        if isinstance(raw_products, list):
            for g in raw_products[:400]:
                gid = str(g or "").strip().upper()
                if not gid or gid in seen_products:
                    continue
                seen_products.add(gid)
                product_guids.append(gid)
        out.append(
            {
                "id": rid,
                "label": label,
                "jobTitle": job_title,
                "active": active,
                "stationCode": station_code,
                "userId": user_id,
                "userLogin": user_login,
                "productGuids": product_guids,
            }
        )
    return json.dumps(out, ensure_ascii=False, separators=(",", ":"))


def _vip_owner_templates_fill_missing_agent_guid(vip_json: str) -> str:
    """
    محاولة ذكية لملء agentGuid لقوالب Owner/VIP عند حفظ الإعدادات:
    - لو agentGuid فارغ و label (الاسم) موجود، نبحث في TBL016 عن AgentName مطابق (ثم LIKE كخطة بديلة).
    - يحل حالة المستخدم: أدخل الاسم من الإعدادات لكن لم تُسجّل GUID في السطر لسبب UI/متصفح.
    """
    raw = (vip_json or "").strip()
    if not raw:
        return "[]"
    try:
        arr = json.loads(raw)
    except (json.JSONDecodeError, TypeError):
        return raw
    if not isinstance(arr, list) or not arr:
        return raw
    conn = get_connection()
    if not conn:
        return raw
    try:
        cur = conn.cursor()
        changed = False
        for x in arr:
            if not isinstance(x, dict):
                continue
            ag = str(x.get("agentGuid") or "").strip()
            if ag:
                continue
            lbl = str(x.get("label") or "").strip()
            if not lbl:
                continue
            # أولاً: تطابق كامل
            try:
                cur.execute(
                    "SELECT TOP 1 CardGuide, AgentName FROM dbo.TBL016 WHERE AgentName = ? AND AgentName IS NOT NULL ORDER BY ID DESC",
                    (lbl,),
                )
                r = cur.fetchone()
            except Exception:
                r = None
            # ثانياً: تطابق جزئي (LIKE)
            if not r:
                try:
                    cur.execute(
                        "SELECT TOP 1 CardGuide, AgentName FROM dbo.TBL016 WHERE AgentName LIKE ? AND AgentName IS NOT NULL ORDER BY ID DESC",
                        (f"%{lbl}%",),
                    )
                    r = cur.fetchone()
                except Exception:
                    r = None
            if r and r[0]:
                x["agentGuid"] = str(r[0]).strip().upper()
                if not str(x.get("label") or "").strip() and r[1]:
                    x["label"] = str(r[1]).strip()
                changed = True
        if not changed:
            return raw
        return json.dumps(arr, ensure_ascii=False, separators=(",", ":"))
    finally:
        try:
            conn.close()
        except Exception:
            pass


