@app.get("/api/restaurant/settings/payment-routing")
def restaurant_payment_routing_get():
    """قائمة ربط طرق التحصيل (نقدي/فيزا/…) بحسابات TBL004 — تُخزَّن في SQL."""
    conn = get_connection()
    if not conn:
        raise HTTPException(status_code=500, detail="فشل الاتصال بقاعدة البيانات")
    try:
        cur = conn.cursor()
        _ensure_payment_routing_schema(cur)
        conn.commit()
        cur.execute(
            """
            SELECT RouteKey, DisplayName, AccountGuide, SortOrder, IsActive
            FROM dbo.MAT3AM_PAYMENT_ROUTING
            ORDER BY SortOrder, RouteKey
            """
        )
        routes = []
        for r in cur.fetchall() or []:
            ag = r[2]
            routes.append(
                {
                    "routeKey": r[0],
                    "displayName": r[1],
                    "accountGuide": str(ag).upper() if ag else None,
                    "sortOrder": int(r[3] or 0),
                    "isActive": bool(r[4]),
                }
            )
        invoice_types = []
        try:
            cur.execute(
                """
                SELECT m.OrderKind, m.Tbl020CardGuide, t.InvoiceName,
                       t.ProductsAccount, t.CashAccount, t.BankAccount,
                       t.SubjectToTaxAccount, t.GenerateEntry
                FROM dbo.MAT3AM_RESTAURANT_INVOICE_TYPES m
                INNER JOIN dbo.TBL020 t ON t.CardGuide = m.Tbl020CardGuide
                ORDER BY m.OrderKind
                """
            )
            for r in cur.fetchall() or []:
                invoice_types.append(
                    {
                        "orderKind": str(r[0] or ""),
                        "invoiceTypeGuide": str(r[1]).upper(),
                        "invoiceName": str(r[2] or ""),
                        "revenueAccountGuide": str(r[3]).upper() if r[3] else None,
                        "cashAccountGuide": str(r[4]).upper() if r[4] else None,
                        "bankAccountGuide": str(r[5]).upper() if r[5] else None,
                        "taxAccountGuide": str(r[6]).upper() if r[6] else None,
                        "generateEntry": int(r[7] or 0),
                    }
                )
        except Exception:
            invoice_types = []
        return {"routes": routes, "invoiceTypes": invoice_types}
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.put("/api/restaurant/settings/payment-routing")
def restaurant_payment_routing_put(body: dict):
    """استبدال جدول ربط التحصيل — يُنصح بمفاتيح: cash, visa, wallet, instapay + أي طرق إضافية (مثل visa_b2)."""
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="جسم غير صالح")
    routes = body.get("routes")
    invoice_types = body.get("invoiceTypes")
    if not isinstance(routes, list) or not routes:
        raise HTTPException(status_code=400, detail="routes مطلوبة (مصفوفة غير فارغة)")
    conn = get_connection()
    if not conn:
        raise HTTPException(status_code=500, detail="فشل الاتصال بقاعدة البيانات")
    try:
        cur = conn.cursor()
        _ensure_payment_routing_schema(cur)
        validated = []
        seen = set()
        for item in routes:
            if not isinstance(item, dict):
                continue
            rk = str(item.get("routeKey") or "").strip()[:40]
            if not rk or not re.match(r"^[A-Za-z0-9_]+$", rk):
                raise HTTPException(status_code=400, detail=f"مفتاح غير صالح: {rk!r}")
            if rk in seen:
                raise HTTPException(status_code=400, detail=f"تكرار routeKey: {rk}")
            seen.add(rk)
            dn = str(item.get("displayName") or rk).strip()[:200] or rk
            try:
                so = int(item.get("sortOrder") if item.get("sortOrder") is not None else 100)
            except (TypeError, ValueError):
                so = 100
            is_act = bool(item.get("isActive", True))
            ag_raw = str(item.get("accountGuide") or "").strip()
            ag = None
            if ag_raw:
                try:
                    uuid.UUID(ag_raw)
                except Exception:
                    raise HTTPException(status_code=400, detail=f"accountGuide غير صالح لـ {rk}") from None
                cur.execute(
                    "SELECT 1 FROM dbo.TBL004 WHERE CardGuide = CAST(? AS uniqueidentifier)",
                    (ag_raw,),
                )
                if not cur.fetchone():
                    raise HTTPException(status_code=400, detail=f"الحساب غير موجود في TBL004 لـ {rk}")
                ag = ag_raw
            validated.append((rk, dn, ag, so, is_act))
        if not validated:
            raise HTTPException(status_code=400, detail="لا توجد بنود صالحة في routes")
        cur.execute("DELETE FROM dbo.MAT3AM_PAYMENT_ROUTING")
        for rk, dn, ag, so, is_act in validated:
            cur.execute(
                """
                INSERT INTO dbo.MAT3AM_PAYMENT_ROUTING (RouteKey, DisplayName, AccountGuide, SortOrder, IsActive)
                VALUES (?, ?, ?, ?, ?)
                """,
                (rk, dn, ag, so, is_act),
            )
        if isinstance(invoice_types, list):
            account_fields = (
                ("revenueAccountGuide", "ProductsAccount"),
                ("cashAccountGuide", "CashAccount"),
                ("bankAccountGuide", "BankAccount"),
                ("taxAccountGuide", "SubjectToTaxAccount"),
            )
            for item in invoice_types:
                if not isinstance(item, dict):
                    continue
                invoice_type_guid = str(item.get("invoiceTypeGuide") or "").strip()
                try:
                    uuid.UUID(invoice_type_guid)
                except Exception:
                    raise HTTPException(status_code=400, detail="invoiceTypeGuide غير صالح") from None
                cur.execute(
                    """
                    SELECT 1
                    FROM dbo.MAT3AM_RESTAURANT_INVOICE_TYPES
                    WHERE Tbl020CardGuide = CAST(? AS uniqueidentifier)
                    """,
                    (invoice_type_guid,),
                )
                if not cur.fetchone():
                    raise HTTPException(status_code=400, detail="نوع الفاتورة ليس ضمن أنواع المطعم المسجلة")
                updates = []
                params: list = []
                for json_key, sql_column in account_fields:
                    raw = str(item.get(json_key) or "").strip()
                    account_guid = None
                    if raw:
                        try:
                            uuid.UUID(raw)
                        except Exception:
                            raise HTTPException(
                                status_code=400,
                                detail=f"{json_key} غير صالح لنوع الفاتورة {invoice_type_guid}",
                            ) from None
                        cur.execute(
                            "SELECT 1 FROM dbo.TBL004 WHERE CardGuide = CAST(? AS uniqueidentifier)",
                            (raw,),
                        )
                        if not cur.fetchone():
                            raise HTTPException(status_code=400, detail=f"الحساب غير موجود: {json_key}")
                        account_guid = raw
                    updates.append(f"{sql_column} = ?")
                    params.append(account_guid)
                # GenerateEntry=2 يجعل Prc008 يولد قيداً غير مرحل نهائياً حسب إعداد إكسترا.
                updates.append("GenerateEntry = 2")
                params.append(invoice_type_guid)
                cur.execute(
                    f"UPDATE dbo.TBL020 SET {', '.join(updates)} WHERE CardGuide = CAST(? AS uniqueidentifier)",
                    tuple(params),
                )
        conn.commit()
        return restaurant_payment_routing_get()
    except HTTPException:
        try:
            conn.rollback()
        except Exception:
            pass
        raise
    except Exception as e:
        try:
            conn.rollback()
        except Exception:
            pass
        raise HTTPException(status_code=500, detail=str(e)) from e
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.get("/api/restaurant/accounts-for-routing")
def restaurant_accounts_for_routing(q: Optional[str] = None):
    """عيّنة من TBL004 لاختيار حساب التحصيل في إعدادات الدفع."""
    conn = get_connection()
    if not conn:
        raise HTTPException(status_code=500, detail="فشل الاتصال بقاعدة البيانات")
    try:
        cur = conn.cursor()
        qq = (q or "").strip()
        if qq:
            like = f"%{qq[:80]}%"
            cur.execute(
                """
                SELECT TOP 120 CardGuide, CardCode, AccountName
                FROM dbo.TBL004
                WHERE AccountName LIKE ? OR CardCode LIKE ? OR CAST(CardGuide AS NVARCHAR(36)) LIKE ?
                ORDER BY CardCode
                """,
                (like, like, like),
            )
        else:
            cur.execute(
                """
                SELECT TOP 120 CardGuide, CardCode, AccountName
                FROM dbo.TBL004
                WHERE AccountName IS NOT NULL
                ORDER BY CardCode
                """
            )
        rows = []
        for r in cur.fetchall() or []:
            rows.append(
                {
                    "cardGuide": str(r[0]).upper() if r[0] else "",
                    "cardCode": str(r[1] or ""),
                    "accountName": str(r[2] or ""),
                }
            )
        return {"accounts": rows}
    finally:
        try:
            conn.close()
        except Exception:
            pass


def _restaurant_write_venue(body: dict) -> dict:
    vt = str((body or {}).get("venueType") or "restaurant").strip().lower().replace("-", "_")
    if vt in ("coffee_shop", "coffeeshop", "coffee", "cafe", "café"):
        vt = "coffee_shop"
    else:
        vt = "restaurant"
    vn = str((body or {}).get("venueName") or "").strip()
    out = {"venueType": vt, "venueName": vn}
    with open(_restaurant_venue_path(), "w", encoding="utf-8") as f:
        json.dump(out, f, ensure_ascii=False, indent=2)
    return out


