@app.post("/api/restaurant/guest-returns")
def restaurant_guest_returns_post(body: dict):
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="يتوقع JSON")
    session_id = str(body.get("sessionId") or "").strip()
    if not session_id:
        raise HTTPException(status_code=400, detail="sessionId مطلوب")
    lines_in = body.get("lines")
    if not isinstance(lines_in, list) or not lines_in:
        raise HTTPException(status_code=400, detail="lines مطلوبة (بند واحد على الأقل)")
    request_table_id = str(body.get("tableId") or "").strip()
    session_row = _restaurant_find_session_row(session_id)
    if not isinstance(session_row, dict):
        raise HTTPException(status_code=404, detail="الجلسة الحالية غير موجودة")
    session_table_id = str(session_row.get("tableId") or "").strip()
    if request_table_id and session_table_id and not _restaurant_table_ids_equal(request_table_id, session_table_id):
        raise HTTPException(status_code=409, detail="المرتجع لا يطابق طاولة الجلسة الحالية")
    reason_map = _guest_return_reason_map()
    approved_qty_map = _approved_guest_return_qty_map_for_session(session_id)
    norm_lines = []
    for ln in lines_in[:40]:
        if not isinstance(ln, dict):
            continue
        order_id = str(ln.get("orderId") or "").strip()
        line_id = str(ln.get("lineId") or "").strip()
        if not order_id or not line_id:
            continue
        rc = str(ln.get("reasonCode") or "").strip()
        if rc not in reason_map:
            raise HTTPException(status_code=400, detail=f"سبب غير معروف: {rc}")
        disp = str(ln.get("proposedDisposition") or ln.get("disposition") or "").strip()
        if disp and disp not in _GUEST_RETURN_DISPOSITION_CODES:
            raise HTTPException(status_code=400, detail=f"معالجة غير مدعومة: {disp}")
        try:
            rq = float(ln.get("returnQty") or ln.get("quantity") or 0)
        except (TypeError, ValueError):
            rq = 0
        if rq <= 0:
            continue
        source_line = _guest_return_resolve_order_line(session_id, order_id, line_id)
        source_table_id = str(source_line.get("tableId") or "").strip()
        if request_table_id and source_table_id and not _restaurant_table_ids_equal(request_table_id, source_table_id):
            raise HTTPException(status_code=409, detail="البند المطلوب لا يتبع الطاولة الحالية")
        source_qty = float(source_line.get("quantity") or 0.0)
        approved_qty = float(approved_qty_map.get((order_id, line_id), 0.0) or 0.0)
        available_qty = max(0.0, source_qty - min(source_qty, approved_qty))
        if available_qty <= 0:
            raise HTTPException(status_code=409, detail="هذا البند استُهلك مرتجعه المعتمد بالكامل سابقًا")
        if rq - available_qty > 0.000001:
            raise HTTPException(status_code=409, detail=f"كمية المرتجع تتجاوز المتاح للبند ({available_qty:g})")
        rr = reason_map[rc]
        line_status = str(source_line.get("lineStatus") or "").strip().lower()
        order_status = str(source_line.get("orderStatus") or "").strip().lower()
        decision = _guest_return_decision(rc, str(rr.get("category") or ""), line_status, order_status)
        norm_lines.append(
            {
                "orderId": order_id[:80],
                "lineId": line_id[:80],
                "productGuide": str(source_line.get("productGuide") or "")[:80],
                "name": str(source_line.get("name") or "")[:300],
                "quantity": source_qty,
                "availableQty": available_qty,
                "returnQty": rq,
                "unitPrice": float(source_line.get("unitPrice") or 0),
                "seatNo": source_line.get("seatNo"),
                "reasonCode": rc,
                "reasonLabel": str(rr.get("label") or rc)[:200],
                "reasonCategory": str(rr.get("category") or "")[:80],
                "lineStatus": line_status[:32] if line_status else "",
                "orderStatus": order_status[:32] if order_status else "",
                "itemStage": str(decision.get("itemStage") or ""),
                "itemStageLabel": str(decision.get("itemStageLabel") or ""),
                "returnKind": str(ln.get("returnKind") or decision.get("returnKind") or "")[:64],
                "returnKindLabel": str(decision.get("returnKindLabel") or "")[:200],
                "approvalMode": str(ln.get("approvalMode") or decision.get("approvalMode") or "")[:64],
                "approvalModeLabel": str(decision.get("approvalModeLabel") or "")[:200],
                "recommendedDisposition": str(decision.get("recommendedDisposition") or "")[:64] or None,
                "policyHint": str(decision.get("policyHint") or "")[:500],
                "proposedDisposition": disp or str(decision.get("recommendedDisposition") or "") or None,
                "finalDisposition": None,
                "waiterNote": str(ln.get("waiterNote") or "")[:400],
                "lineDecisionStatus": "pending_manager",
            }
        )
    if not norm_lines:
        raise HTTPException(status_code=400, detail="لا بنود صالحة")
    actor = body.get("requestedBy") if isinstance(body.get("requestedBy"), dict) else {}
    now_iso = datetime.now().isoformat()
    rec = {
        "id": str(uuid.uuid4()),
        "sessionId": session_id,
        "tableId": str(body.get("tableId") or "")[:80],
        "tableLabel": str(body.get("tableLabel") or "")[:120],
        "status": "pending_manager",
        "reviewMode": "contextual",
        "requestedAt": now_iso,
        "requestedBy": {
            "userId": str(actor.get("userId") or body.get("userId") or "")[:64],
            "name": str(actor.get("name") or body.get("userName") or "")[:120],
            "role": str(actor.get("role") or "")[:32],
        },
        "lines": norm_lines,
        "managerNote": "",
        "managerReview": None,
        "reviewSummary": {
            "pendingCount": sum(1 for ln in norm_lines if str(ln.get("approvalMode") or "") == "manager_review_required"),
            "directEligibleCount": sum(1 for ln in norm_lines if str(ln.get("approvalMode") or "") == "direct_accept_recommended"),
            "cancelIfNotStartedCount": sum(1 for ln in norm_lines if str(ln.get("approvalMode") or "") == "cancel_if_not_started"),
        },
    }
    data = _guest_return_requests_load()
    data.append(rec)
    _guest_return_requests_save(data)
    return {"ok": True, "request": rec}


@app.patch("/api/restaurant/guest-returns/{request_id}")
def restaurant_guest_returns_patch(request_id: str, body: dict):
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="يتوقع JSON")
    action = str(body.get("action") or "").strip().lower()
    data = _guest_return_requests_load()
    target = None
    for r in data:
        if str(r.get("id") or "") == str(request_id):
            target = r
            break
    if not target:
        raise HTTPException(status_code=404, detail="طلب المرتجع غير موجود")
    now_iso = datetime.now().isoformat()
    reviewer = body.get("reviewedBy") if isinstance(body.get("reviewedBy"), dict) else {}
    if action == "reject":
        target["status"] = "rejected"
        target["managerNote"] = str(body.get("managerNote") or "")[:2000]
        for ln in target.get("lines") or []:
            if isinstance(ln, dict):
                ln["lineDecisionStatus"] = "rejected"
        target["managerReview"] = {
            "userId": str(reviewer.get("userId") or "")[:64],
            "name": str(reviewer.get("name") or "")[:120],
            "at": now_iso,
        }
        _guest_return_requests_save(data)
        return {"ok": True, "request": target}
    if action in ("approve", "approve_lines"):
        if str(target.get("status") or "").lower() not in ("pending_manager",):
            raise HTTPException(status_code=409, detail="الطلب ليس بانتظار المدير")
        line_updates = body.get("lines")
        if isinstance(line_updates, list):
            by_lid = {str(x.get("lineId") or ""): x for x in line_updates if isinstance(x, dict)}
            for ln in target.get("lines") or []:
                if not isinstance(ln, dict):
                    continue
                lid = str(ln.get("lineId") or "")
                upd = by_lid.get(lid)
                if not upd:
                    continue
                fd = str(upd.get("finalDisposition") or upd.get("disposition") or "").strip()
                if fd and fd not in _GUEST_RETURN_DISPOSITION_CODES:
                    raise HTTPException(status_code=400, detail=f"معالجة غير مدعومة: {fd}")
                if fd:
                    ln["finalDisposition"] = fd
                elif ln.get("proposedDisposition"):
                    ln["finalDisposition"] = ln.get("proposedDisposition")
                elif ln.get("recommendedDisposition"):
                    ln["finalDisposition"] = ln.get("recommendedDisposition")
                ln["lineDecisionStatus"] = "approved"
        else:
            for ln in target.get("lines") or []:
                if isinstance(ln, dict) and ln.get("proposedDisposition") and not ln.get("finalDisposition"):
                    ln["finalDisposition"] = ln.get("proposedDisposition")
                elif isinstance(ln, dict) and ln.get("recommendedDisposition") and not ln.get("finalDisposition"):
                    ln["finalDisposition"] = ln.get("recommendedDisposition")
                if isinstance(ln, dict):
                    ln["lineDecisionStatus"] = "approved"
        target["status"] = "approved"
        target["managerNote"] = str(body.get("managerNote") or target.get("managerNote") or "")[:2000]
        target["managerReview"] = {
            "userId": str(reviewer.get("userId") or "")[:64],
            "name": str(reviewer.get("name") or "")[:120],
            "at": now_iso,
        }
        _guest_return_requests_save(data)
        return {"ok": True, "request": target}
    raise HTTPException(status_code=400, detail="action غير مدعوم: approve | reject")


def _manager_approval_create_invoice_payment_request(invoice: dict, approval_type: str, actor: dict) -> dict:
    invoice_id = str(invoice.get("invoiceId") or "").strip()
    session_id = str(invoice.get("sessionId") or "").strip()
    data = _manager_approval_requests_load()
    for row in reversed(data):
        if (
            str(row.get("type") or "") == _MANAGER_APPROVAL_TYPE_INVOICE_PAYMENT
            and str(row.get("invoiceId") or "") == invoice_id
            and str(row.get("approvalType") or "") == approval_type
            and str(row.get("status") or "") == _MANAGER_APPROVAL_STATUS_PENDING
        ):
            _manager_approval_enqueue_inbox(row)
            return row
    label = "ترحيل الفاتورة على الحساب" if approval_type == "on_account_credit" else "تصفير الفاتورة كضيف صالة"
    req = {
        "id": str(uuid.uuid4()),
        "type": _MANAGER_APPROVAL_TYPE_INVOICE_PAYMENT,
        "status": _MANAGER_APPROVAL_STATUS_PENDING,
        "requestedAt": datetime.now().isoformat(),
        "invoiceId": invoice_id,
        "billNumber": invoice.get("billNumber"),
        "invoiceTotal": _money2_round(invoice.get("total")),
        "approvalType": approval_type,
        "sessionId": session_id,
        "tableId": str(invoice.get("tableIdResolved") or ""),
        "tableLabel": str(invoice.get("tableName") or invoice.get("tableLabel") or "فاتورة"),
        "reason": label,
        "requestedBy": {
            "userId": str(actor.get("id") or ""),
            "name": str(actor.get("name") or actor.get("login") or ""),
            "role": str(actor.get("role") or ""),
        },
        "openOrdersSummary": {"totalValue": _money2_round(invoice.get("total"))},
        "decisionOptions": [
            {
                "id": "approve_invoice_payment_exception",
                "label": f"اعتماد: {label}",
                "description": "يسمح بتنفيذ طريقة التسوية الاستثنائية لهذه الفاتورة فقط.",
                "recommended": True,
            }
        ],
        "decisionFlags": [
            {
                "id": "notifyRequester",
                "label": "إشعار مقدم الطلب بالقرار",
                "description": "يرسل نتيجة الاعتماد أو الرفض لصاحب الطلب.",
                "default": True,
            }
        ],
    }
    _manager_approval_requests_save(data + [req])
    _manager_approval_enqueue_inbox(req)
    return req


