@app.post("/api/restaurant/manager-approvals")
def restaurant_manager_approvals_post(body: dict):
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="يتوقع JSON")
    req_type = str(body.get("type") or "").strip()
    requester = _mat3am_actor_from_body(body)
    if req_type == _MANAGER_APPROVAL_TYPE_CANCEL_SESSION_WITH_OPEN_ORDERS:
        session_id = str(body.get("sessionId") or "").strip()
        if not session_id:
            raise HTTPException(status_code=400, detail="sessionId مطلوب")
        session_row = _restaurant_find_session_row(session_id)
        if not isinstance(session_row, dict):
            raise HTTPException(status_code=404, detail="الجلسة غير موجودة")
        req = _manager_approval_create_cancel_session_request(session_row, requester, str(body.get("reason") or ""))
    elif req_type == _MANAGER_APPROVAL_TYPE_CAPTAIN_HANDOVER:
        session_id = str(body.get("sessionId") or "").strip()
        if not session_id:
            raise HTTPException(status_code=400, detail="sessionId مطلوب")
        session_row = _restaurant_find_session_row(session_id)
        if not isinstance(session_row, dict):
            raise HTTPException(status_code=404, detail="الجلسة غير موجودة")
        req = _manager_approval_create_captain_handover_request(session_row, requester, str(body.get("reason") or ""))
    elif req_type == _MANAGER_APPROVAL_TYPE_GUEST_SESSION:
        session_id = str(body.get("sessionId") or "").strip()
        if not session_id:
            raise HTTPException(status_code=400, detail="sessionId مطلوب")
        session_row = _restaurant_find_session_row(session_id)
        if not isinstance(session_row, dict):
            raise HTTPException(status_code=404, detail="الجلسة غير موجودة")
        customer_type = str(body.get("customerType") or "guest").strip().lower()
        req = _manager_approval_create_guest_session_request(session_row, requester, str(body.get("reason") or ""), requested_customer_type=customer_type)
    elif req_type == _MANAGER_APPROVAL_TYPE_RESET_TABLE_WITH_OPEN_ORDERS:
        table_id = str(body.get("tableId") or "").strip()
        if not table_id:
            raise HTTPException(status_code=400, detail="tableId مطلوب")
        req = _manager_approval_create_reset_table_request(table_id, requester, str(body.get("reason") or ""))
    elif req_type == _MANAGER_APPROVAL_TYPE_SHIFT_CLOSE:
        # الإقفال يُنشأ من POST /api/restaurant/cashier/shift-close/submit — لا يُنشأ من هنا مباشرة.
        raise HTTPException(status_code=400, detail="أنشئ إقفال الشيفت من شاشة الكاشير ثم يصل للمدير تلقائياً.")
    else:
        raise HTTPException(status_code=400, detail="type غير مدعوم حالياً.")
    return {"ok": True, "request": req}


@app.patch("/api/restaurant/manager-approvals/{request_id}")
def restaurant_manager_approvals_patch(request_id: str, body: dict):
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="يتوقع JSON")
    action = str(body.get("action") or "").strip().lower()
    reviewer = body.get("reviewedBy") if isinstance(body.get("reviewedBy"), dict) else {}
    reviewer_role = str(reviewer.get("role") or "").strip().lower()
    if not _role_has_manager_ops_access(reviewer_role):
        raise HTTPException(status_code=403, detail="حسم هذا الطلب لمدير التشغيل أو المدير أو المطوّر فقط.")
    data = _manager_approval_requests_load()
    target = None
    for row in data:
        if isinstance(row, dict) and str(row.get("id") or "").strip() == str(request_id):
            target = row
            break
    if not isinstance(target, dict):
        raise HTTPException(status_code=404, detail="طلب الموافقة غير موجود")
    if str(target.get("status") or "").strip().lower() != _MANAGER_APPROVAL_STATUS_PENDING:
        raise HTTPException(status_code=409, detail="الطلب ليس بانتظار المدير حالياً.")
    now_iso = datetime.now().isoformat()
    manager_note = str(body.get("managerNote") or "")[:2000]
    flags_raw = body.get("flags")
    flags_map = {}
    if isinstance(flags_raw, list):
        flags_map = {str(x.get("id") or ""): bool(x.get("enabled")) for x in flags_raw if isinstance(x, dict)}
    elif isinstance(flags_raw, dict):
        flags_map = {str(k): bool(v) for k, v in flags_raw.items()}
    req_type = str(target.get("type") or "").strip()
    if action == "reject":
        if req_type == _MANAGER_APPROVAL_TYPE_GUEST_SESSION:
            if not str(manager_note or "").strip():
                raise HTTPException(status_code=400, detail="سبب رفض جلسة الضيف إلزامي.")
        target["status"] = "rejected"
        target["managerNote"] = (
            manager_note
            or ("رفض المدير اعتماد جلسة ضيف." if req_type == _MANAGER_APPROVAL_TYPE_GUEST_SESSION else "")
            or ("رفض المدير تنفيذ تسليم الكابتن." if req_type == _MANAGER_APPROVAL_TYPE_CAPTAIN_HANDOVER else "")
            or ("رفض المدير تنفيذ Reset للطاولة." if req_type == _MANAGER_APPROVAL_TYPE_RESET_TABLE_WITH_OPEN_ORDERS else "")
            or ("رفض المدير اعتماد إقفال الشيفت." if req_type == _MANAGER_APPROVAL_TYPE_SHIFT_CLOSE else "")
            or "رفض المدير تنفيذ الإلغاء."
        )
        target["managerReview"] = {
            "userId": str(reviewer.get("userId") or "")[:64],
            "name": str(reviewer.get("name") or "")[:120],
            "role": reviewer_role[:32],
            "at": now_iso,
            "decision": "reject",
        }
        target["executionResult"] = (
            _manager_approval_reject_guest_session(target)
            if req_type == _MANAGER_APPROVAL_TYPE_GUEST_SESSION
            else _manager_approval_reject_shift_close(target, reviewer, manager_note)
            if req_type == _MANAGER_APPROVAL_TYPE_SHIFT_CLOSE
            else {"action": "keep_session_open"}
        )
        _manager_approval_requests_save(data)
        _manager_approval_dismiss_inbox(str(target.get("id") or ""))
        _append_session_audit_entry(
            {
                "at": now_iso,
                "action": "manager_approval_rejected",
                "requestType": str(target.get("type") or ""),
                "requestId": str(target.get("id") or ""),
                "sessionId": str(target.get("sessionId") or ""),
                "tableId": str(target.get("tableId") or ""),
                "managerNote": target.get("managerNote") or "",
                "reviewedByUserId": str(reviewer.get("userId") or ""),
                "reviewedByName": str(reviewer.get("name") or ""),
                "reviewedByRole": reviewer_role,
            }
        )
        if bool(flags_map.get("notifyRequester", True)):
            _manager_approval_notify_requester(
                target,
                "رفض طلب جلسة ضيف"
                if req_type == _MANAGER_APPROVAL_TYPE_GUEST_SESSION
                else "رفض طلب تسليم الكابتن"
                if req_type == _MANAGER_APPROVAL_TYPE_CAPTAIN_HANDOVER
                else "رفض طلب Reset للطاولة"
                if req_type == _MANAGER_APPROVAL_TYPE_RESET_TABLE_WITH_OPEN_ORDERS
                else "رفض إقفال الشيفت"
                if req_type == _MANAGER_APPROVAL_TYPE_SHIFT_CLOSE
                else "رفض طلب الإلغاء",
                manager_note,
            )
        cache_delete_pattern("mat3am:restaurant:role-inbox:*")
        return {"ok": True, "request": target}
    if action != "approve":
        raise HTTPException(status_code=400, detail="action غير مدعوم: approve | reject")
    decision_id = str(body.get("decisionId") or "").strip()
    if not decision_id:
        raise HTTPException(status_code=400, detail="decisionId مطلوب عند الاعتماد")
    if req_type == _MANAGER_APPROVAL_TYPE_CANCEL_SESSION_WITH_OPEN_ORDERS:
        execution_result = _manager_approval_execute_cancel_session(target, decision_id, reviewer, manager_note, flags_map)
    elif req_type == _MANAGER_APPROVAL_TYPE_GUEST_SESSION:
        execution_result = _manager_approval_execute_guest_session(target, decision_id, reviewer, manager_note, flags_map, str(body.get("decisionInputValue") or ""))
    elif req_type == _MANAGER_APPROVAL_TYPE_CAPTAIN_HANDOVER:
        execution_result = _manager_approval_execute_captain_handover(
            target,
            decision_id,
            reviewer,
            manager_note,
            flags_map,
            str(body.get("targetUserId") or ""),
        )
    elif req_type == _MANAGER_APPROVAL_TYPE_RESET_TABLE_WITH_OPEN_ORDERS:
        execution_result = _manager_approval_execute_reset_table(target, decision_id, reviewer, manager_note, flags_map)
    elif req_type == _MANAGER_APPROVAL_TYPE_INVOICE_PAYMENT:
        if decision_id != "approve_invoice_payment_exception":
            raise HTTPException(status_code=400, detail="قرار اعتماد التسوية غير صالح.")
        execution_result = {
            "action": "approve_invoice_payment_exception",
            "invoiceId": str(target.get("invoiceId") or ""),
            "approvalType": str(target.get("approvalType") or ""),
            "decisionLabel": "تم اعتماد طريقة تسوية الفاتورة",
        }
    elif req_type == _MANAGER_APPROVAL_TYPE_SHIFT_CLOSE:
        if decision_id != "approve_shift_close":
            raise HTTPException(status_code=400, detail="قرار اعتماد إقفال الشيفت غير صالح.")
        execution_result = _manager_approval_execute_shift_close(target, reviewer, manager_note)
    else:
        raise HTTPException(status_code=400, detail="نوع الطلب غير مدعوم في التنفيذ الحالي.")
    target["status"] = "approved"
    target["managerNote"] = manager_note
    target["managerReview"] = {
        "userId": str(reviewer.get("userId") or "")[:64],
        "name": str(reviewer.get("name") or "")[:120],
        "role": reviewer_role[:32],
        "at": now_iso,
        "decision": decision_id,
    }
    target["executionResult"] = execution_result
    _manager_approval_requests_save(data)
    _manager_approval_dismiss_inbox(str(target.get("id") or ""))
    cache_delete_pattern("mat3am:restaurant:role-inbox:*")
    return {"ok": True, "request": target}


def _looks_like_table_guid(value: object) -> bool:
    s = str(value or "").strip()
    if not s:
        return False
    return bool(re.match(
        r"^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$",
        s,
    ))


def _usable_table_display_name(value: object, *, reject_id: str = "") -> str:
    """اسم عرض صالح — يرفض الفارغ و«—» والمعرف نفسه إن كان GUID."""
    nm = str(value or "").strip()
    if not nm or nm == "—":
        return ""
    rid = str(reject_id or "").strip()
    if rid and nm.upper() == rid.upper():
        return ""
    if _looks_like_table_guid(nm):
        return ""
    return nm


def _floor_plan_table_id_to_label() -> dict:
    """خريطة id / linkedTableId في المخطط → تسمية للعرض (label أو name)."""
    out: dict = {}
    p = _restaurant_path("floor_plan")
    if not os.path.isfile(p):
        return out
    try:
        with open(p, "r", encoding="utf-8") as f:
            plan = json.load(f)
        if not isinstance(plan, dict):
            return out
        # بعض الملفات تغلّف المخطط تحت مفتاح plan
        if isinstance(plan.get("plan"), dict):
            plan = plan["plan"]

        def _put(key: str, lab: str) -> None:
            k = str(key or "").strip()
            if not k or not lab:
                return
            out[k] = lab
            out[k.upper()] = lab

        def ingest_tables(tbl_list):
            if not isinstance(tbl_list, list):
                return
            for t in tbl_list:
                if not isinstance(t, dict):
                    continue
                tid = str(t.get("id") or "").strip()
                linked = str(t.get("linkedTableId") or "").strip()
                lab = (t.get("label") or t.get("name") or t.get("title") or "").strip()
                if not lab:
                    # لا نخزّن GUID كاسم عرض — نترك الحقل للطبقات التالية
                    continue
                if tid:
                    _put(tid, lab)
                if linked:
                    _put(linked, lab)

        if plan.get("schemaVersion") == 2:
            for fl in plan.get("floors") or []:
                if isinstance(fl, dict):
                    ingest_tables(fl.get("tables"))
        else:
            ingest_tables(plan.get("tables"))
    except Exception:
        pass
    return out


def _restaurant_file_tables_id_to_name() -> dict:
    out: dict = {}
    for t in _restaurant_load("tables", []):
        if not isinstance(t, dict) or not t.get("id"):
            continue
        tid = str(t.get("id")).strip()
        nm = (t.get("name") or "").strip()
        num = t.get("number")
        if nm and not _looks_like_table_guid(nm):
            out[tid] = nm
            out[tid.upper()] = nm
        elif num is not None and str(num).strip() != "":
            label = f"طاولة {num}"
            out[tid] = label
            out[tid.upper()] = label
        # لا نضع tid→tid؛ يمنع الرجوع لمخطط الصالة / SQL
    return out


def _restaurant_table_display_names_for_ids(table_ids: set) -> dict:
    """حلّ أسماء عرض للطاولة: مخطط الأرضية (linkedTableId)، ثم tables.json، ثم TBL005."""
    result: dict = {}
    if not table_ids:
        return result
    fp = _floor_plan_table_id_to_label()
    fm = _restaurant_file_tables_id_to_name()
    pending: list = []
    for tid in table_ids:
        if not tid:
            result[tid] = "—"
            continue
        ts = str(tid).strip()
        t_up = ts.upper()
        hit = _usable_table_display_name(fp.get(ts) or fp.get(t_up), reject_id=ts)
        if not hit:
            hit = _usable_table_display_name(fm.get(ts) or fm.get(t_up), reject_id=ts)
        if hit:
            result[tid] = hit
            continue
        pending.append(tid)

    if pending:
        conn = get_connection()
        if conn:
            try:
                dbmap: dict = {}
                cur = conn.cursor()
                cur.execute("SELECT CardGuide, CostCenter FROM TBL005 WHERE CostCenter IS NOT NULL")
                for row in cur.fetchall():
                    if row and row[0]:
                        g = str(row[0]).strip()
                        name = (str(row[1]).strip() if row[1] is not None else "") or ""
                        dbmap[g.upper()] = name or g
                for tid in pending:
                    if tid in result:
                        continue
                    ts = str(tid).strip()
                    nm = dbmap.get(ts.upper())
                    if nm:
                        result[tid] = nm if len(nm) < 80 else (nm[:77] + "…")
                    else:
                        compact = ts.replace("-", "")
                        short = compact[-6:].upper() if len(compact) >= 6 else ts[:8]
                        result[tid] = f"طاولة (مرجع {short})"
            finally:
                try:
                    conn.close()
                except Exception:
                    pass
        for tid in pending:
            if tid not in result:
                ts = str(tid).strip()
                compact = ts.replace("-", "")
                short = compact[-6:].upper() if len(compact) >= 6 else ts[:8]
                result[tid] = f"طاولة (مرجع {short})"
    return result


