def _restaurant_preload_sessions_orders() -> tuple:
    """جلسات + طلبات في bulk ODBC واحد (أو JSON) — يُستخدم لعدم فتح 4–6 اتصالات لكل طلب."""
    bulk = _restaurant_sql_get_bulk(["table_sessions", "orders"])
    sessions_raw = bulk.get("table_sessions")
    orders_raw = bulk.get("orders")
    sessions_src = "sql" if sessions_raw is not None else "json"
    orders_src = "sql" if orders_raw is not None else "json"
    if sessions_raw is None:
        sessions_raw = _restaurant_load("table_sessions", [])
    if orders_raw is None:
        orders_raw = _restaurant_load("orders", [])
    if not isinstance(sessions_raw, list):
        sessions_raw = []
    if not isinstance(orders_raw, list):
        orders_raw = []
    return sessions_raw, orders_raw, sessions_src, orders_src


def _restaurant_operational_snapshot_sync(include_users: bool = False) -> dict:
    """لقطة واحدة: SQL (طاولات) + حالة تشغيل (جلسات/طلبات من SQL أو JSON) + إعدادات."""
    sessions_raw, orders_raw, sessions_src, orders_src = _restaurant_preload_sessions_orders()

    tables_payload = _restaurant_get_tables_payload(
        sessions_preload=sessions_raw,
        orders_preload=orders_raw,
    )
    fp_raw = _restaurant_load("floor_plan", {})
    try:
        wf_raw = _restaurant_read_workflow()
    except Exception:
        wf_raw = {}

    ops_raw = _restaurant_read_ops_storage()
    waiter_table_assignments = _restaurant_waiter_table_assignments_load()
    temp_captain_transfers = _restaurant_temp_captain_transfer_active_rows()
    try:
        relations_payload = restaurant_get_recent_table_relations(limit=500)
        relations_raw = (
            relations_payload.get("relations")
            if isinstance(relations_payload, dict) and isinstance(relations_payload.get("relations"), list)
            else []
        )
    except Exception:
        relations_raw = []

    from mat3am_sql_cache import status as cache_status

    out: dict = {
        "ok": True,
        "floorPlan": fp_raw,
        "tables": tables_payload.get("tables") if isinstance(tables_payload, dict) else [],
        "tableDataSource": tables_payload.get("dataSource") if isinstance(tables_payload, dict) else {},
        "sessions": sessions_raw,
        "orders": orders_raw,
        "workflowSettings": wf_raw,
        "opsSettings": ops_raw if isinstance(ops_raw, dict) else {},
        "waiterTableAssignments": waiter_table_assignments,
        "tempCaptainTransfers": temp_captain_transfers,
        # شاشة الطاولات تعتمد اللقطة السريعة ثم تعود فوراً؛ لذلك يجب تضمين
        # العلاقات هنا، وإلا فلن تطلب endpoint المنفصل ولن تظهر لافتة النقل.
        "relations": relations_raw,
        "sources": {
            "table_sessions": sessions_src,
            "orders": orders_src,
            "tables": (tables_payload.get("dataSource") or {}).get("catalog") or "unknown",
        },
        "sqlCache": cache_status(),
    }
    if include_users:
        from mat3am_sql_cache import get_app_users

        users, umeta = get_app_users(get_connection)
        out["users"] = users
        out["usersDataSource"] = umeta
    return out


@app.get("/api/restaurant/operational-snapshot")
async def restaurant_operational_snapshot(includeUsers: bool = Query(False, alias="includeUsers")):
    """لقطة تشغيلية واحدة (JSON) — تقليل 6+ اتصالات ODBC من الواجهة + Redis cache 30s."""
    cache_key = f"mat3am:restaurant:operational-snapshot:u={includeUsers}"
    cached = cache_get(cache_key)
    if cached:
        return cached
    result = await run_in_threadpool(_restaurant_operational_snapshot_sync, includeUsers)
    cache_set(cache_key, result, ttl=30)
    return result


def _restaurant_get_tables_payload(
    *,
    sessions_preload: Optional[list] = None,
    orders_preload: Optional[list] = None,
) -> dict:
    """بناء قائمة الطاولات — يُفضّل تمرير جلسات/طلبات محمّلة مسبقاً لتقليل ODBC."""
    if sessions_preload is None or orders_preload is None:
        sp, op, _, _ = _restaurant_preload_sessions_orders()
        sessions_preload = sp if sessions_preload is None else sessions_preload
        orders_preload = op if orders_preload is None else orders_preload

    plan_refs = []
    try:
        raw_doc = _restaurant_load("floor_plan", {})
        plan_doc = raw_doc.get("plan") if isinstance(raw_doc, dict) and isinstance(raw_doc.get("plan"), dict) else raw_doc
        floor = None
        if isinstance(plan_doc, dict) and plan_doc.get("schemaVersion") == 2 and isinstance(plan_doc.get("floors"), list):
            floors = [f for f in plan_doc.get("floors") if isinstance(f, dict)]
            active_id = str(plan_doc.get("activeFloorId") or "").strip()
            floor = next((f for f in floors if str(f.get("id") or "") == active_id), floors[0] if floors else None)
        elif isinstance(plan_doc, dict):
            floor = plan_doc
        for t in ((floor or {}).get("tables") or []):
            if not isinstance(t, dict):
                continue
            tid = str(t.get("linkedTableId") or "").strip()
            lab = str(t.get("label") or "").strip()
            if tid or lab:
                plan_refs.append({"linked_id": tid.upper(), "label": lab})
    except Exception:
        plan_refs = []

    sessions_now = list(sessions_preload) if isinstance(sessions_preload, list) else []
    orders_now = list(orders_preload) if isinstance(orders_preload, list) else []
    _close_stale_active_sessions(sessions_now)
    # لا نجعل عرض الشرائح ينتظر توليد/مزامنة التنبيهات؛ تُنفذ بالخلفية فقط.
    try:
        threading.Thread(
            target=_restaurant_sync_no_order_watch_alerts,
            kwargs={"sessions": sessions_now, "orders": orders_now},
            daemon=True,
            name="mat3am-no-order-watch-sync",
        ).start()
    except Exception:
        pass
    local_state = _local_table_state_map()
    no_order_map = _table_no_order_overdue_map(10, sessions=sessions_now, orders=orders_now)
    active_table_ids_upper = set()
    if sessions_now:
        for s in sessions_now:
            if not _session_active_today(s):
                continue
            tid = str((s or {}).get("tableId") or "").strip().upper()
            if tid:
                active_table_ids_upper.add(tid)
    if orders_now:
        for o in orders_now:
            if not isinstance(o, dict):
                continue
            # تحسين: لا نعتبر الطلب نشطاً للطاولة إلا إذا كان من تاريخ اليوم (تجنباً للطلبات اليتيمة القديمة)
            if not _is_today_iso(str(o.get("createdAt") or "")):
                continue
            st = str(o.get("status") or "").strip().lower()
            if st not in ("pending", "preparing", "ready"):
                continue
            tid = str(o.get("tableId") or "").strip().upper()
            if tid:
                active_table_ids_upper.add(tid)

    def _normalized_table_status(table_id: str, raw_status: Any) -> str:
        st = str(raw_status or "ready").strip().lower() or "ready"
        tid = str(table_id or "").strip().upper()
        # دورة التنظيف أولوية تشغيلية: لا تُلغى بسبب طلب/جلسة عابرة بعد التحويل أو الإغلاق.
        # هذا كان يسبب تذبذب الشريحة بين cleaning/occupied أثناء الاستطلاع.
        if st in ("dirty", "cleaning"):
            return st
        # إذا كان للطاولة جلسة أو طلب نشط فعلياً اليوم، فهي "مشغولة" حتماً
        if tid in active_table_ids_upper:
            return "occupied"
        # إذا كانت الحالة "occupied" لكن لا يوجد نشاط فعلي، فهي "جاهزة"
        if st == "occupied":
            return "ready"
        return st

    # 1) قاعدة البيانات (TBL005) — كاش ذاكرة + مرآة JSON (انظر mat3am_sql_cache.py)
    from mat3am_sql_cache import get_tbl005_cost_centers

    tbl005_rows, tbl_meta = get_tbl005_cost_centers(get_connection)
    if tbl005_rows:
        try:
            row_by_id = {}
            row_by_name = {}
            for item in tbl005_rows:
                gid = str(item.get("id") or "").strip().upper()
                nm = str(item.get("name") or "").strip()
                if gid:
                    row_by_id[gid] = item
                if nm:
                    row_by_name[nm] = item
            tables = []
            if plan_refs:
                used = set()
                for i, ref in enumerate(plan_refs, 1):
                    row = None
                    if ref["linked_id"]:
                        row = row_by_id.get(ref["linked_id"])
                    if row is None and ref["label"]:
                        row = row_by_name.get(ref["label"])
                    if row is None:
                        continue
                    gid = str(row.get("id") or "")
                    if gid in used:
                        continue
                    used.add(gid)
                    st_row = local_state.get(gid.upper(), {})
                    min_charge = _get_table_minimum_charge(st_row)
                    status_v = _normalized_table_status(gid, st_row.get("status"))
                    dirty_at = st_row.get("dirtyAt")
                    clean_started = st_row.get("cleaningStartedAt")
                    overdue = False
                    if status_v == "dirty" and dirty_at:
                        ddt = _iso_to_local_dt(str(dirty_at))
                        if ddt and (datetime.now() - ddt).total_seconds() >= 600:
                            overdue = True
                    no_order_info = no_order_map.get(gid, {}) if isinstance(no_order_map, dict) else {}
                    tables.append({
                        "id": gid,
                        "number": i,
                        "name": row.get("name") or ref["label"] or ("طاولة " + str(i)),
                        "seats": 4,
                        "status": status_v,
                        "dirtyAt": dirty_at,
                        "cleaningStartedAt": clean_started,
                        "cleanupOverdue": overdue,
                        "noOrderOverdue": bool(no_order_info.get("noOrderOverdue")),
                        "noOrderMinutes": int(no_order_info.get("noOrderMinutes") or 0),
                        "position": {"x": 50 + (i % 5) * 120, "y": 50 + (i // 5) * 100},
                        "minimumCharge": max(0.0, min_charge),
                        "features": {"canAddChildSeat": True, "nearBalcony": False, "nearBathroom": False, "smokingArea": False, "vipSection": False},
                    })
            else:
                for i, row in enumerate(tbl005_rows, 1):
                    gid = str(row.get("id") or "")
                    st_row = local_state.get(gid.upper(), {})
                    min_charge = _get_table_minimum_charge(st_row)
                    status_v = _normalized_table_status(gid, st_row.get("status"))
                    dirty_at = st_row.get("dirtyAt")
                    clean_started = st_row.get("cleaningStartedAt")
                    overdue = False
                    if status_v == "dirty" and dirty_at:
                        ddt = _iso_to_local_dt(str(dirty_at))
                        if ddt and (datetime.now() - ddt).total_seconds() >= 600:
                            overdue = True
                    no_order_info = no_order_map.get(gid, {}) if isinstance(no_order_map, dict) else {}
                    tables.append({
                        "id": gid,
                        "number": i,
                        "name": row.get("name") or ("طاولة " + str(i)),
                        "seats": 4,
                        "status": status_v,
                        "dirtyAt": dirty_at,
                        "cleaningStartedAt": clean_started,
                        "cleanupOverdue": overdue,
                        "noOrderOverdue": bool(no_order_info.get("noOrderOverdue")),
                        "noOrderMinutes": int(no_order_info.get("noOrderMinutes") or 0),
                        "position": {"x": 50 + (i % 5) * 120, "y": 50 + (i // 5) * 100},
                        "minimumCharge": max(0.0, min_charge),
                        "features": {"canAddChildSeat": True, "nearBalcony": False, "nearBathroom": False, "smokingArea": False, "vipSection": False},
                    })
            if tables:
                _merge_mat3am_vip_tables_into(tables)
                return {"tables": tables, "dataSource": {"catalog": "sql", **tbl_meta}}
        except Exception as tbl_build_err:
            print(f"[mat3am] restaurant_get_tables TBL005 build: {tbl_build_err}", flush=True)

    # 2) ملف محلي (لبيئات بدون قاعدة)
    data = _restaurant_load("tables", [])
    if data:
        out = []
        for t in data:
            if not isinstance(t, dict):
                continue
            tid = str(t.get("id") or "").strip()
            st = _normalized_table_status(tid, t.get("status"))
            dirty_at = t.get("dirtyAt")
            overdue = False
            if st == "dirty" and dirty_at:
                ddt = _iso_to_local_dt(str(dirty_at))
                if ddt and (datetime.now() - ddt).total_seconds() >= 600:
                    overdue = True
            no_order_info = no_order_map.get(tid, {}) if isinstance(no_order_map, dict) else {}
            row = dict(t)
            row["cleanupOverdue"] = overdue
            row["noOrderOverdue"] = bool(no_order_info.get("noOrderOverdue"))
            row["noOrderMinutes"] = int(no_order_info.get("noOrderMinutes") or 0)
            out.append(row)
        _merge_mat3am_vip_tables_into(out)
        return {"tables": out}

    # 3) افتراضي
    out = []
    for t in _restaurant_default_tables():
        tid = str((t or {}).get("id") or "").strip()
        no_order_info = no_order_map.get(tid, {}) if isinstance(no_order_map, dict) else {}
        row = dict(t)
        row["cleanupOverdue"] = False
        row["noOrderOverdue"] = bool(no_order_info.get("noOrderOverdue"))
        row["noOrderMinutes"] = int(no_order_info.get("noOrderMinutes") or 0)
        out.append(row)
    return {"tables": out}


@app.get("/api/restaurant/tables")
def restaurant_get_tables():
    """جلب الطاولات — من مراكز التكلفة (TBL005) أولاً، ثم من ملف، ثم افتراضي. Redis cache 15s."""
    cache_key = "mat3am:restaurant:tables"
    cached = cache_get(cache_key)
    if cached:
        return cached
    result = _restaurant_get_tables_payload()
    cache_set(cache_key, result, ttl=15)
    return result


def _restaurant_pos_channels_default_doc() -> dict:
    return {
        "version": 1,
        "agentGroupNames": {
            "cash_individual": "عملاء السفاري",
            "delivery_riders": "مندوبين توصيل",
            "delivery_customers": "عملاء الدليفري",
            "hall_patrons": "عملاء الصالة",
            "sites": "عملاء المواقع",
        },
        "channels": {"sites": {"pseudoTableAliases": ["مواقع", "SITES", "sites"]}},
    }


@app.get("/api/restaurant/pos-channels")
def restaurant_get_pos_channels():
    """إعدادات قنوات نقاط البيع (دليفري / مواقع / …) — من `config/restaurant/pos_channels.json` مع افتراضي."""
    doc = _restaurant_load("pos_channels", {})
    if not isinstance(doc, dict):
        doc = {}
    base = _restaurant_pos_channels_default_doc()
    merged = {**base, **doc}
    ag = doc.get("agentGroupNames") if isinstance(doc.get("agentGroupNames"), dict) else {}
    if isinstance(ag, dict):
        merged["agentGroupNames"] = {**(base.get("agentGroupNames") or {}), **ag}
    ch = doc.get("channels") if isinstance(doc.get("channels"), dict) else {}
    if isinstance(ch, dict):
        merged["channels"] = {**(base.get("channels") or {}), **ch}
    return merged


@app.get("/api/restaurant/pos-paired-cost-centers")
def restaurant_pos_paired_cost_centers(
    channel: str = Query("delivery", description="delivery أو sites — مجموعة عملاء القناة من pos_channels / TBL015"),
):
    """
    مراكز تكلفة مقترنة بعملاء القناة: TBL005 ↔ TBL016 على نفس CardGuide
    (مع UNION لمطابقة AgentName مع CostCenter)، ضمن MainGroupGuide لمجموعة القناة.
    """
    ch = str(channel or "").strip().lower()
    if ch not in ("delivery", "sites"):
        raise HTTPException(status_code=400, detail="channel يجب أن يكون delivery أو sites")
    doc = restaurant_get_pos_channels()
    agn = doc.get("agentGroupNames") if isinstance(doc.get("agentGroupNames"), dict) else {}
    gname = ""
    if ch == "delivery":
        gname = str(agn.get("delivery_customers") or "").strip()
    else:
        gname = str(agn.get("sites") or "").strip()
    if not gname:
        return {"tables": [], "groupName": None, "warning": "group_not_configured"}

    conn = get_connection()
    if not conn:
        return {"tables": [], "groupName": gname, "warning": "no_db"}

    try:
        cursor = conn.cursor()
        cursor.execute(
            """
            SELECT TOP 1 CardGuide
            FROM dbo.TBL015
            WHERE RTRIM(LTRIM(ISNULL(GroupName, N''))) = RTRIM(LTRIM(?))
            """,
            (gname,),
        )
        row = cursor.fetchone()
        if not row or row[0] is None:
            return {"tables": [], "groupName": gname, "warning": "group_not_found_in_TBL015"}
        mg = str(row[0]).strip()
        sql = """
            SELECT DISTINCT x.CardGuide, x.CostCenter
            FROM (
              SELECT t5.CardGuide AS CardGuide, t5.CostCenter AS CostCenter
              FROM dbo.TBL005 AS t5
              INNER JOIN dbo.TBL016 AS t16 ON t16.CardGuide = t5.CardGuide
              WHERE t16.MainGroupGuide = CAST(? AS uniqueidentifier)
                AND RTRIM(LTRIM(ISNULL(t5.CostCenter, N''))) <> N''
                AND ISNULL(t16.NotActive, 0) = 0
              UNION
              SELECT t5.CardGuide AS CardGuide, t5.CostCenter AS CostCenter
              FROM dbo.TBL005 AS t5
              INNER JOIN dbo.TBL016 AS t16
                ON RTRIM(LTRIM(ISNULL(t16.AgentName, N''))) = RTRIM(LTRIM(ISNULL(t5.CostCenter, N'')))
              WHERE t16.MainGroupGuide = CAST(? AS uniqueidentifier)
                AND RTRIM(LTRIM(ISNULL(t5.CostCenter, N''))) <> N''
                AND ISNULL(t16.NotActive, 0) = 0
            ) AS x
            ORDER BY x.CostCenter
        """
        cursor.execute(sql, (mg, mg))
        tables = []
        for r in cursor.fetchall():
            gid = str(r[0] or "").strip()
            nm = str(r[1] or "").strip() or gid
            if not gid:
                continue
            tables.append({"id": gid, "name": nm, "number": 0, "status": "ready", "seats": 2})
        return {"tables": tables, "groupName": gname}
    except Exception as e:
        return {"tables": [], "groupName": gname, "warning": str(e)[:400]}
    finally:
        try:
            conn.close()
        except Exception:
            pass


@app.post("/api/restaurant/tables")
def restaurant_save_table(body: dict):
    """حفظ/إنشاء طاولة"""
    def _parse_table_number(raw_number: Any, raw_name: Any, fallback: int) -> int:
        try:
            n = int(raw_number)
            if n > 0:
                return n
        except Exception:
            pass
        try:
            nm = str(raw_name or "")
            m = re.search(r"(\d+)", nm)
            if m:
                n2 = int(m.group(1))
                if n2 > 0:
                    return n2
        except Exception:
            pass
        return max(1, int(fallback))

    def _point_in_polygon(px: float, py: float, poly_points: list) -> bool:
        if not isinstance(poly_points, list) or len(poly_points) < 3:
            return True
        inside = False
        j = len(poly_points) - 1
        for i in range(len(poly_points)):
            try:
                xi = float(poly_points[i][0])
                yi = float(poly_points[i][1])
                xj = float(poly_points[j][0])
                yj = float(poly_points[j][1])
            except Exception:
                j = i
                continue
            intersects = ((yi > py) != (yj > py)) and (px < ((xj - xi) * (py - yi) / ((yj - yi) or 1e-9) + xi))
            if intersects:
                inside = not inside
            j = i
        return inside

    def _table_overlaps(x: float, y: float, w: float, h: float, existing_tables: list) -> bool:
        x2 = x + w
        y2 = y + h
        for et in existing_tables:
            if not isinstance(et, dict):
                continue
            try:
                ex = float(et.get("x") or 0.0)
                ey = float(et.get("y") or 0.0)
                ew = float(et.get("w") or 0.0)
                eh = float(et.get("h") or 0.0)
            except Exception:
                continue
            if ew <= 0 or eh <= 0:
                continue
            ex2 = ex + ew
            ey2 = ey + eh
            if x < ex2 and x2 > ex and y < ey2 and y2 > ey:
                return True
        return False

    def _auto_place_table_into_floor_plan(table_rec: dict) -> None:
        fp = _restaurant_path("floor_plan")
        if not os.path.exists(fp):
            return
        try:
            with open(fp, "r", encoding="utf-8") as f:
                raw_doc = json.load(f)
        except Exception:
            return
        if not isinstance(raw_doc, dict):
            return

        is_v2 = raw_doc.get("schemaVersion") == 2 and isinstance(raw_doc.get("floors"), list)
        floors = raw_doc.get("floors") if is_v2 else [raw_doc]
        if not isinstance(floors, list) or not floors:
            return

        active_id = str(raw_doc.get("activeFloorId") or "")
        target_floor = None
        for fl in floors:
            if isinstance(fl, dict) and active_id and str(fl.get("id") or "") == active_id:
                target_floor = fl
                break
        if target_floor is None:
            target_floor = floors[0] if isinstance(floors[0], dict) else None
        if not isinstance(target_floor, dict):
            return

        tbls = target_floor.get("tables")
        if not isinstance(tbls, list):
            target_floor["tables"] = []
            tbls = target_floor["tables"]

        linked_id = str(table_rec.get("id") or "").strip()
        if not linked_id:
            return
        for t in tbls:
            if not isinstance(t, dict):
                continue
            if str(t.get("linkedTableId") or "").strip() == linked_id:
                return

        shell = target_floor.get("shell") if isinstance(target_floor.get("shell"), dict) else {}
        points = shell.get("points") if isinstance(shell, dict) else []
        if not isinstance(points, list) or len(points) < 3:
            return
        xs = []
        ys = []
        for p in points:
            if isinstance(p, (list, tuple)) and len(p) >= 2:
                try:
                    xs.append(float(p[0]))
                    ys.append(float(p[1]))
                except Exception:
                    pass
        if len(xs) < 3 or len(ys) < 3:
            return
        min_x, max_x = min(xs), max(xs)
        min_y, max_y = min(ys), max(ys)
        if max_x - min_x < 60 or max_y - min_y < 60:
            return

        rect_w = 92.0
        rect_h = 62.0
        pad = 8.0
        place_x = min_x + 20.0
        place_y = min_y + 20.0
        for _ in range(80):
            try_x = random.uniform(min_x + pad, max_x - rect_w - pad)
            try_y = random.uniform(min_y + pad, max_y - rect_h - pad)
            cx = try_x + rect_w / 2.0
            cy = try_y + rect_h / 2.0
            if not _point_in_polygon(cx, cy, points):
                continue
            if _table_overlaps(try_x, try_y, rect_w, rect_h, tbls):
                continue
            place_x = try_x
            place_y = try_y
            break

        max_tnum = 0
        for t in tbls:
            if not isinstance(t, dict):
                continue
            tid = str(t.get("id") or "")
            m = re.search(r"(\d+)$", tid)
            if m:
                try:
                    max_tnum = max(max_tnum, int(m.group(1)))
                except Exception:
                    pass
        floor_table_id = f"T{max_tnum + 1}"
        label = str(table_rec.get("name") or f"طاولة {table_rec.get('number') or ''}").strip() or floor_table_id
        seats = int(table_rec.get("seats") or 4)
        if seats < 1:
            seats = 1
        tbls.append(
            {
                "id": floor_table_id,
                "label": label,
                "shape": "rect",
                "x": round(place_x, 2),
                "y": round(place_y, 2),
                "w": rect_w,
                "h": rect_h,
                "seats": seats,
                "linkedTableId": linked_id,
            }
        )

        try:
            with open(fp, "w", encoding="utf-8") as f:
                json.dump(raw_doc, f, ensure_ascii=False, indent=2)
        except Exception:
            return

    data = _restaurant_load("tables", [])
    if not isinstance(data, list):
        data = []
    tid = body.get("id") or str(uuid.uuid4())
    table_number = _parse_table_number(body.get("number"), body.get("name"), len(data) + 1)
    rec = {
        "id": tid,
        "number": table_number,
        "name": body.get("name", "طاولة " + str(len(data) + 1)),
        "seats": body.get("seats", 4),
        "status": body.get("status", "available"),
        "position": body.get("position", {"x": 0, "y": 0}),
        "features": body.get("features", {"canAddChildSeat": True, "nearBalcony": False, "nearBathroom": False, "smokingArea": False, "vipSection": False}),
    }
    rec_number_norm = str(rec.get("number")).strip()
    for t in data:
        if not isinstance(t, dict):
            continue
        if str(t.get("id") or "") == str(tid):
            continue
        if str(t.get("number")).strip() == rec_number_norm:
            raise HTTPException(status_code=409, detail=f"رقم الطاولة مستخدم بالفعل: {rec_number_norm}")
    existing = [i for i, t in enumerate(data) if t.get("id") == tid]
    is_new = not bool(existing)
    if existing:
        data[existing[0]] = rec
    else:
        data.append(rec)
    _restaurant_save("tables", data)
    if is_new:
        try:
            _auto_place_table_into_floor_plan(rec)
        except Exception:
            pass
    # upsert into TBL005 as a cost center
    try:
        cc_label = str(rec.get("name") or "").strip()
        _upsert_cost_center_by_name(cc_label)
    except Exception:
        pass
    return rec

@app.delete("/api/restaurant/tables/{table_id}")
def restaurant_delete_table(table_id: str):
    """حذف طاولة من ملف التهيئة (مزامنة مع واجهة التخطيط)"""
    data = _restaurant_load("tables", [])
    new_data = [t for t in data if str(t.get("id")) != str(table_id)]
    if len(new_data) == len(data):
        raise HTTPException(status_code=404, detail="الطاولة غير موجودة في الملف المحلي")
    _restaurant_save("tables", new_data)
    return {"ok": True, "id": table_id}

@app.patch("/api/restaurant/tables/{table_id}/status")
def restaurant_update_table_status(table_id: str, body: dict):
    """تحديث حالة طاولة"""
    raw = str((body or {}).get("status") or "").strip().lower()
    status = raw or "ready"
    if status in ("available", "free", "open", "جاهزة", "متاحة"):
        status = "ready"
    elif status in ("busy", "occupied", "مشغولة"):
        status = "occupied"
    elif status in ("reserved", "محجوزة"):
        status = "reserved"
    elif status in ("dirty", "متسخة"):
        status = "dirty"
    elif status in ("cleaning", "تنظيف"):
        status = "cleaning"
    elif status not in ("ready", "occupied", "reserved", "dirty", "cleaning"):
        status = "ready"
    data = _restaurant_load("tables", [])
    now_iso = datetime.now().isoformat()
    for t in data:
        if t.get("id") == table_id:
            t["status"] = status
            t["statusUpdatedAt"] = now_iso
            if status == "dirty":
                t["dirtyAt"] = now_iso
                t["cleaningStartedAt"] = None
                t["readyAt"] = None
            elif status == "cleaning":
                t["cleaningStartedAt"] = now_iso
            elif status == "ready":
                t["readyAt"] = now_iso
                t["dirtyAt"] = None
                t["cleaningStartedAt"] = None
                t.pop("minimumCharge", None)
                t.pop("minimumChargeUpdatedAt", None)
            _restaurant_save("tables", data)
            # #region debug-point B:table-status-save-file
            _dbg_table_session_close(
                "B",
                "api_server.py:restaurant_update_table_status:file-save",
                "table status saved to local tables store",
                {"tableId": str(table_id or ""), "status": status, "statusUpdatedAt": now_iso},
            )
            # #endregion
            return t
    conn = get_connection()
    if conn:
        try:
            cursor = conn.cursor()
            cursor.execute("SELECT CardGuide, CostCenter FROM TBL005 WHERE CardGuide = CAST(? AS uniqueidentifier)", (table_id,))
            row = cursor.fetchone()
            conn.close()
            if row:
                rec = {"id": table_id, "status": status, "name": row[1], "statusUpdatedAt": now_iso}
                if status == "dirty":
                    rec["dirtyAt"] = now_iso
                if status == "cleaning":
                    rec["cleaningStartedAt"] = now_iso
                if status == "ready":
                    rec["readyAt"] = now_iso
                # cache in local file to preserve operational lifecycle timestamps
                data.append(rec)
                _restaurant_save("tables", data)
                # #region debug-point B:table-status-save-sql
                _dbg_table_session_close(
                    "B",
                    "api_server.py:restaurant_update_table_status:sql-save",
                    "table status resolved from SQL and cached locally",
                    {"tableId": str(table_id or ""), "status": status, "statusUpdatedAt": now_iso, "tableName": str(row[1] or "")},
                )
                # #endregion
                return rec
        except Exception:
            pass
    # #region debug-point D:table-status-fallback
    _dbg_table_session_close(
        "D",
        "api_server.py:restaurant_update_table_status:fallback",
        "table status returned without local or SQL match",
        {"tableId": str(table_id or ""), "status": status},
    )
    # #endregion
    return {"id": table_id, "status": status}


@app.patch("/api/restaurant/tables/{table_id}/minimum-charge")
def restaurant_update_table_minimum_charge(table_id: str, body: dict):
    """تحديث minimum charge لطاولة (يُحفظ محلياً حتى مع مصدر SQL)."""
    # Shared Terminal: عملية تعديل/خصم حسّاسة
    _terminal_require_user((body or {}).get("mat3amActor") if isinstance(body, dict) else None)
    tid = str(table_id or "").strip()
    if not tid:
        raise HTTPException(status_code=400, detail="tableId مطلوب")
    try:
        mc_raw = (body or {}).get("minimumCharge")
        mc = float(str(mc_raw or "0").replace(",", "."))
        mc = max(0.0, mc)
    except Exception:
        raise HTTPException(status_code=400, detail="minimumCharge غير صالح")
    data = _restaurant_load("tables", [])
    if not isinstance(data, list):
        data = []
    now_iso = datetime.now().isoformat()
    for t in data:
        if isinstance(t, dict) and str(t.get("id") or "").strip().upper() == tid.upper():
            t["minimumCharge"] = mc
            t["minimumChargeUpdatedAt"] = now_iso
            _restaurant_save("tables", data)
            try:
                sess = _restaurant_load("table_sessions", [])
                changed = False
                for s in (sess if isinstance(sess, list) else []):
                    if not isinstance(s, dict):
                        continue
                    if str(s.get("status") or "").strip().lower() != "active":
                        continue
                    if not _is_today_iso(str(s.get("startTime") or "")):
                        continue
                    if _norm_session_table_id(str(s.get("tableId") or "")) != _norm_session_table_id(tid):
                        continue
                    try:
                        linked = int(float(s.get("linkedOrderCount") or 0))
                    except Exception:
                        linked = 0
                    if linked > 0:
                        continue
                    s["minimumChargePerSeat"] = mc
                    changed = True
                if changed:
                    _restaurant_save("table_sessions", sess)
            except Exception:
                pass
            cache_invalidate_restaurant()
            cache_delete_pattern("mat3am:restaurant:operational-snapshot:*")
            cache_delete_pattern("mat3am:restaurant:order-taker-bootstrap:*")
            return {"ok": True, "id": tid, "minimumCharge": mc}
    # إذا الطاولة مصدرها SQL (TBL005) ولم توجد محلياً، أنشئ سجل حالة محلي
    rec = {"id": tid, "minimumCharge": mc, "minimumChargeUpdatedAt": now_iso}
    data.append(rec)
    _restaurant_save("tables", data)
    try:
        sess = _restaurant_load("table_sessions", [])
        changed = False
        for s in (sess if isinstance(sess, list) else []):
            if not isinstance(s, dict):
                continue
            if str(s.get("status") or "").strip().lower() != "active":
                continue
            if not _is_today_iso(str(s.get("startTime") or "")):
                continue
            if _norm_session_table_id(str(s.get("tableId") or "")) != _norm_session_table_id(tid):
                continue
            try:
                linked = int(float(s.get("linkedOrderCount") or 0))
            except Exception:
                linked = 0
            if linked > 0:
                continue
            s["minimumChargePerSeat"] = mc
            changed = True
        if changed:
            _restaurant_save("table_sessions", sess)
    except Exception:
        pass
    cache_invalidate_restaurant()
    cache_delete_pattern("mat3am:restaurant:operational-snapshot:*")
    cache_delete_pattern("mat3am:restaurant:order-taker-bootstrap:*")
    return {"ok": True, "id": tid, "minimumCharge": mc}


@app.get("/api/restaurant/waiter-table-assignments")
def restaurant_get_waiter_table_assignments():
    return {"ok": True, "items": _restaurant_waiter_table_assignments_load()}


@app.post("/api/restaurant/waiter-table-assignments/mutate")
def restaurant_mutate_waiter_table_assignments(body: dict):
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="جسم غير صالح")
    action = str(body.get("action") or "").strip().lower()
    rows = _restaurant_waiter_table_assignments_load()
    if action == "add":
        user_id = str(body.get("userId") or "").strip()
        if not user_id:
            raise HTTPException(status_code=400, detail="userId مطلوب")
        table_ids = body.get("tableIds") if isinstance(body.get("tableIds"), list) else []
        normalized_table_ids: List[str] = []
        for raw_tid in table_ids:
            tid = _restaurant_waiter_assignment_table_id(raw_tid)
            if tid and tid not in normalized_table_ids:
                normalized_table_ids.append(tid)
        if not normalized_table_ids:
            raise HTTPException(status_code=400, detail="اختر طاولة واحدة على الأقل")
        rec = {
            "id": str(uuid.uuid4()),
            "userId": user_id,
            "userLogin": str(body.get("userLogin") or "").strip()[:120],
            "userName": str(body.get("userName") or "").strip()[:200],
            "validFrom": _restaurant_waiter_assignment_date(body.get("validFrom")),
            "validTo": _restaurant_waiter_assignment_date(body.get("validTo")),
            "tableIds": normalized_table_ids,
            "createdAt": datetime.now().isoformat(),
        }
        rows.append(rec)
    elif action == "update":
        row_id = str(body.get("assignmentId") or body.get("id") or "").strip()
        if not row_id:
            raise HTTPException(status_code=400, detail="assignmentId مطلوب")
        hit = None
        for row in rows:
            if str(row.get("id") or "").strip() == row_id:
                hit = row
                break
        if hit is None:
            raise HTTPException(status_code=404, detail="التخصيص غير موجود")
        user_id = str(body.get("userId") or hit.get("userId") or "").strip()
        if not user_id:
            raise HTTPException(status_code=400, detail="userId مطلوب")
        table_ids = body.get("tableIds") if isinstance(body.get("tableIds"), list) else hit.get("tableIds") or []
        normalized_table_ids: List[str] = []
        for raw_tid in table_ids:
            tid = _restaurant_waiter_assignment_table_id(raw_tid)
            if tid and tid not in normalized_table_ids:
                normalized_table_ids.append(tid)
        if not normalized_table_ids:
            raise HTTPException(status_code=400, detail="اختر طاولة واحدة على الأقل")
        hit["userId"] = user_id
        hit["userLogin"] = str(body.get("userLogin") or hit.get("userLogin") or "").strip()[:120]
        hit["userName"] = str(body.get("userName") or hit.get("userName") or "").strip()[:200]
        hit["validFrom"] = _restaurant_waiter_assignment_date(body.get("validFrom") or hit.get("validFrom"))
        hit["validTo"] = _restaurant_waiter_assignment_date(body.get("validTo") or hit.get("validTo"))
        hit["tableIds"] = normalized_table_ids
    elif action == "remove":
        row_id = str(body.get("assignmentId") or body.get("id") or "").strip()
        if not row_id:
            raise HTTPException(status_code=400, detail="assignmentId مطلوب")
        kept = [row for row in rows if str(row.get("id") or "").strip() != row_id]
        if len(kept) == len(rows):
            raise HTTPException(status_code=404, detail="التخصيص غير موجود")
        rows = kept
    else:
        raise HTTPException(status_code=400, detail="action يجب أن يكون add أو update أو remove")
    _restaurant_waiter_table_assignments_save(rows)
    cache_invalidate_restaurant()
    return {"ok": True, "assignmentsChanged": True, "items": _restaurant_waiter_table_assignments_load()}


def _get_table_minimum_charge(st_row: dict | None) -> float:
    """اقرأ minimumCharge للطاولة/الكرسي: أولاً من override الطاولة حتى لو كان 0، ثم من الإعدادات الافتراضية."""
    try:
        if isinstance(st_row, dict) and "minimumCharge" in st_row:
            mc = float(st_row.get("minimumCharge") or 0)
            return max(0.0, mc)
    except Exception:
        pass
    # fallback: القيمة الافتراضية من الإعدادات
    try:
        settings = _settings_load()
        if isinstance(settings, dict):
            default_mc = float(str(settings.get("tableDefaultMinimumCharge") or "0").replace(",", "."))
            return max(0.0, default_mc)
    except Exception:
        pass
    return 0.0


def _normalize_session_guest_count(value, default: int = 1) -> int:
    try:
        dv = int(float(default))
    except (TypeError, ValueError):
        dv = 1
    dv = max(1, min(12, dv))
    try:
        n = int(float(value))
    except (TypeError, ValueError):
        return dv
    return max(1, min(12, n))


def _normalize_minimum_charge_input(value) -> Optional[float]:
    try:
        if value is None:
            return None
        txt = str(value).strip()
        if txt == "":
            return None
        out = float(txt.replace(",", "."))
        return max(0.0, out)
    except Exception:
        return None


def _auto_numbered_seat_guest_labels(guest_count: int, existing: Optional[dict] = None) -> dict:
    out: dict[str, str] = {}
    count = _normalize_session_guest_count(guest_count, 1)
    shared_text = ""
    if isinstance(existing, dict):
        raw_shared = existing.get("13")
        if raw_shared is None:
            raw_shared = existing.get(13)
        if raw_shared is not None:
            shared_text = str(raw_shared or "").strip()[:120]
    for i in range(1, count + 1):
        out[str(i)] = str(i)
    if shared_text:
        out["13"] = shared_text
    return out


def _session_minimum_charge_per_seat(session_row: Optional[dict] = None, table_id: str = "") -> float:
    if isinstance(session_row, dict):
        try:
            if "minimumChargePerSeat" in session_row:
                snap = float(session_row.get("minimumChargePerSeat") or 0)
                return max(0.0, snap)
        except Exception:
            pass
        if not table_id:
            table_id = str(session_row.get("tableId") or "").strip()
    st_row = None
    if table_id:
        st_row = _local_table_state_map().get(str(table_id).strip().upper())
    return _get_table_minimum_charge(st_row)


def _restaurant_clear_table_minimum_charge_override(table_id: str) -> None:
    """عند فتح جلسة جديدة: نضمن وجود minimumCharge للطاولة.
    نحافظ على القيمة المخصصة إن وُجدت حتى لو كانت 0، وإلا نستخدم القيمة الافتراضية من الإعدادات."""
    tid = str(table_id or "").strip()
    if not tid:
        return
    data = _restaurant_load("tables", [])
    if not isinstance(data, list):
        data = []
    found = False
    has_override = False
    for t in data:
        if not isinstance(t, dict):
            continue
        if str(t.get("id") or "").strip().upper() != tid.upper():
            continue
        found = True
        has_override = "minimumCharge" in t
        break
    if found and has_override:
        # القيمة المخصصة على الشريحة موجودة — نحافظ عليها حتى لو كانت صفرًا
        return
    default_mc = _get_table_minimum_charge(None)
    now_iso = datetime.now().isoformat()
    if found:
        for t in data:
            if not isinstance(t, dict):
                continue
            if str(t.get("id") or "").strip().upper() != tid.upper():
                continue
            t["minimumCharge"] = default_mc
            t["minimumChargeUpdatedAt"] = now_iso
            break
    else:
        data.append({"id": tid, "minimumCharge": default_mc, "minimumChargeUpdatedAt": now_iso})
    _restaurant_save("tables", data)


