@app.post("/api/restaurant/tables/{table_id}/apply-cleaning-policy")
def restaurant_table_apply_cleaning_policy(table_id: str, body: dict):
    """تنفيذ سياسة التنظيف بأمر مباشر (manager/waiter)."""
    actor = ""
    if isinstance(body, dict):
        actor = str(body.get("actorRole") or body.get("actor") or "").strip().lower()
    if actor not in ("manager", "waiter"):
        raise HTTPException(status_code=400, detail="actorRole يجب أن يكون manager أو waiter")
    return _workflow_apply_cleaning_policy(table_id, event="direct_command", actor_role=actor)


def _restaurant_session_order_counts() -> dict:
    """عدد الطلبات (أي سجل) لكل sessionId."""
    counts: dict = {}
    for o in _restaurant_load("orders", []):
        if not isinstance(o, dict):
            continue
        sid = str(o.get("sessionId") or "").strip()
        if sid:
            counts[sid] = counts.get(sid, 0) + 1
    return counts


def _restaurant_open_orders_for_table(table_id: str) -> list[dict]:
    """كل الطلبات المفتوحة الفعلية على طاولة بعينها بغض النظر عن الجلسة الحالية، بشرط أن تكون من تاريخ اليوم."""
    tid = _norm_session_table_id(str(table_id or "").strip())
    if not tid:
        return []
    out: list[dict] = []
    for order in _restaurant_load("orders", []):
        if not isinstance(order, dict):
            continue
        if _norm_session_table_id(str(order.get("tableId") or "").strip()) != tid:
            continue
        # تحسين: لا نمنع التسكين بسبب طلبات قديمة جداً (ليست من اليوم)
        if not _is_today_iso(str(order.get("createdAt") or "")):
            continue
        st = str(order.get("status") or "").strip().lower()
        if st not in ("pending", "preparing", "ready"):
            continue
        out.append(order)
    return out


def _restaurant_force_reset_table(table_id: str, *, reason: str = "", actor: Optional[dict] = None) -> dict:
    """تنظيف تشغيلي كامل للطاولة: إلغاء الطلبات المفتوحة، إنهاء الجلسات النشطة، وإرجاع الطاولة إلى جاهزة."""
    tid = _norm_session_table_id(str(table_id or "").strip())
    if not tid:
        raise HTTPException(status_code=400, detail="tableId مطلوب لتنفيذ Reset للطاولة.")
    actor = actor if isinstance(actor, dict) else {}
    reason_txt = str(reason or "").strip()[:500] or "reset_table"
    now_iso = datetime.now().isoformat()

    sessions = _restaurant_load("table_sessions", [])
    if not isinstance(sessions, list):
        sessions = []
    active_session_ids: list[str] = []
    for s in sessions:
        if not isinstance(s, dict):
            continue
        if _norm_session_table_id(str(s.get("tableId") or "").strip()) != tid:
            continue
        if str(s.get("status") or "").strip().lower() != "active":
            continue
        sid = str(s.get("id") or "").strip()
        if sid:
            active_session_ids.append(sid)

    completed_session_ids: list[str] = []
    for sid in active_session_ids:
        done = _restaurant_complete_session_internal(
            sid,
            force=True,
            reason=reason_txt,
            actor=actor,
            table_status_on_complete="ready",
            release_captain_on_complete=True,
        )
        completed_session_ids.append(str((done or {}).get("id") or sid))

    orders = _restaurant_load("orders", [])
    if not isinstance(orders, list):
        orders = []
    orders_changed = False
    cancelled_order_count = 0
    cancelled_line_count = 0
    for order in orders:
        if not isinstance(order, dict):
            continue
        if _norm_session_table_id(str(order.get("tableId") or "").strip()) != tid:
            continue
        st = str(order.get("status") or "").strip().lower()
        if st in ("served", "paid", "cancelled"):
            continue
        items = [_kds_normalize_item(x) for x in (order.get("items") or []) if isinstance(x, dict)]
        order_changed = False
        if items:
            for it in items:
                if bool(it.get("cancelled")):
                    continue
                it["cancelled"] = True
                it["lineStatus"] = "cancelled"
                it["cancelledAt"] = now_iso
                it["prepared"] = False
                it["preparedQty"] = 0.0
                it["sent"] = False
                it["preparedAt"] = None
                it["sentAt"] = None
                it["handoffAt"] = None
                cancelled_line_count += 1
                order_changed = True
            order["items"] = items
            prev_status = str(order.get("status") or "").strip().lower()
            _kds_refresh_order_status(order)
            if str(order.get("status") or "").strip().lower() == "cancelled":
                order["cancelledAt"] = str(order.get("cancelledAt") or "").strip() or now_iso
            if order_changed or prev_status != str(order.get("status") or "").strip().lower():
                cancelled_order_count += 1
                orders_changed = True
        elif st != "cancelled":
            order["status"] = "cancelled"
            order["cancelledAt"] = now_iso
            cancelled_order_count += 1
            orders_changed = True
    if orders_changed:
        _restaurant_save("orders", orders)

    tables = _restaurant_load("tables", [])
    if not isinstance(tables, list):
        tables = []
    table_row = None
    for t in tables:
        if isinstance(t, dict) and _norm_session_table_id(str(t.get("id") or "").strip()) == tid:
            table_row = t
            break
    if table_row is None:
        table_row = {"id": tid}
        tables.append(table_row)
    table_row["status"] = "ready"
    table_row["statusUpdatedAt"] = now_iso
    table_row["readyAt"] = now_iso
    table_row["dirtyAt"] = None
    table_row["cleaningStartedAt"] = None
    table_row["occupiedSince"] = None
    table_row["noOrderOverdue"] = False
    table_row["noOrderMinutes"] = 0
    table_row["cleanupOverdue"] = False
    for key in (
        "minimumCharge",
        "minimumChargeUpdatedAt",
        "currentSessionId",
        "currentOrderId",
        "captainUserId",
        "captainLogin",
        "captainName",
        "captainRole",
        "captainClaimedAt",
        "occupiedAt",
        "reservedAt",
        "billingRequestedAt",
    ):
        table_row.pop(key, None)
    _restaurant_save("tables", tables)
    cache_invalidate_restaurant()
    return {
        "table": dict(table_row),
        "completedSessionIds": completed_session_ids,
        "cancelledOrderCount": cancelled_order_count,
        "cancelledLineCount": cancelled_line_count,
    }


def _restaurant_ops_day_reset(
    *,
    purge_history: bool = True,
    clear_delivery: bool = True,
    clear_invoices: bool = False,
    actor: Optional[dict] = None,
    reason: str = "",
) -> dict:
    """تصفير تشغيلي لبدء يوم عمل نظيف — بدون المساس بالمنيو/المستخدمين/الإعدادات/المخطط."""
    actor = actor if isinstance(actor, dict) else {}
    now_iso = datetime.now().isoformat()
    reason_txt = str(reason or "").strip()[:500] or "ops_day_reset"
    stats: dict[str, Any] = {
        "at": now_iso,
        "purgeHistory": bool(purge_history),
        "clearDelivery": bool(clear_delivery),
        "clearInvoices": bool(clear_invoices),
    }

    with _restaurant_table_sessions_lock:
        sessions = _restaurant_load("table_sessions", [])
        if not isinstance(sessions, list):
            sessions = []
        active_before = sum(
            1 for s in sessions if isinstance(s, dict) and str(s.get("status") or "").lower() == "active"
        )
        if purge_history:
            stats["sessionsCleared"] = len(sessions)
            stats["activeSessionsClosed"] = active_before
            _restaurant_save("table_sessions", [])
        else:
            closed = 0
            for s in sessions:
                if not isinstance(s, dict):
                    continue
                if str(s.get("status") or "").lower() != "active":
                    continue
                s["status"] = "completed"
                s["endTime"] = now_iso
                s["closedAt"] = now_iso
                s["endedAt"] = now_iso
                s["endReason"] = reason_txt
                closed += 1
            stats["activeSessionsClosed"] = closed
            stats["sessionsCleared"] = 0
            if closed:
                _restaurant_save("table_sessions", sessions)

    with _restaurant_orders_lock:
        orders = _restaurant_load("orders", [])
        if not isinstance(orders, list):
            orders = []
        open_statuses = {"pending", "preparing", "ready", "served", "delivered", "new", "sent", "queued"}
        open_before = sum(
            1
            for o in orders
            if isinstance(o, dict) and str(o.get("status") or "").strip().lower() in open_statuses
        )
        if purge_history:
            stats["ordersCleared"] = len(orders)
            stats["openOrdersCancelled"] = open_before
            _restaurant_save("orders", [])
        else:
            cancelled = 0
            for order in orders:
                if not isinstance(order, dict):
                    continue
                st = str(order.get("status") or "").strip().lower()
                if st in ("paid", "cancelled", "canceled"):
                    continue
                items = [_kds_normalize_item(x) for x in (order.get("items") or []) if isinstance(x, dict)]
                for it in items:
                    if bool(it.get("cancelled")):
                        continue
                    it["cancelled"] = True
                    it["lineStatus"] = "cancelled"
                    it["cancelledAt"] = now_iso
                if items:
                    order["items"] = items
                    _kds_refresh_order_status(order)
                else:
                    order["status"] = "cancelled"
                order["cancelledAt"] = str(order.get("cancelledAt") or "").strip() or now_iso
                cancelled += 1
            stats["openOrdersCancelled"] = cancelled
            stats["ordersCleared"] = 0
            if cancelled:
                _restaurant_save("orders", orders)

    tables = _restaurant_load("tables", [])
    if not isinstance(tables, list):
        tables = []
    tables_reset = 0
    for t in tables:
        if not isinstance(t, dict):
            continue
        st = str(t.get("status") or "").strip().lower()
        needs = st not in ("ready", "available", "") or any(
            t.get(k)
            for k in (
                "awaitingPayment",
                "billingRequestedAt",
                "billingStatus",
                "dirtyAt",
                "cleaningStartedAt",
                "sessionId",
                "activeSessionId",
                "captainUserId",
                "captainName",
                "assignedCaptainName",
                "minimumCharge",
            )
        )
        if not needs and st in ("ready", "available", ""):
            # تأكد من تنظيف أعلام الفاتورة حتى لو كانت جاهزة
            if not any(
                t.get(k)
                for k in ("awaitingPayment", "billingRequestedAt", "billingStatus", "sessionId", "activeSessionId")
            ):
                continue
        t["status"] = "ready"
        t["statusUpdatedAt"] = now_iso
        t["readyAt"] = now_iso
        t["dirtyAt"] = None
        t["cleaningStartedAt"] = None
        for key in (
            "awaitingPayment",
            "billingRequestedAt",
            "billingStatus",
            "sessionId",
            "activeSessionId",
            "captainUserId",
            "captainName",
            "assignedCaptainName",
            "minimumCharge",
            "minimumChargeUpdatedAt",
            "cleanupOverdue",
            "noOrderOverdue",
            "reservedAt",
            "guestCount",
        ):
            t.pop(key, None)
        tables_reset += 1
    if tables_reset:
        _restaurant_save("tables", tables)
    stats["tablesReset"] = tables_reset

    approvals = _manager_approval_requests_load()
    stats["approvalsCleared"] = len(approvals)
    _manager_approval_requests_save([])

    alerts = _restaurant_load("cashier_alerts", [])
    alerts_n = len(alerts) if isinstance(alerts, list) else 0
    _restaurant_save("cashier_alerts", [])
    stats["cashierAlertsCleared"] = alerts_n

    inbox = _role_inbox_load_rows()
    _role_inbox_save_rows([])
    stats["roleInboxCleared"] = len(inbox)

    transfers = _restaurant_temp_captain_transfers_load()
    _restaurant_temp_captain_transfers_save([])
    stats["tempCaptainTransfersCleared"] = len(transfers)

    returns = _guest_return_requests_load()
    _guest_return_requests_save([])
    stats["guestReturnsCleared"] = len(returns)

    kn = _restaurant_load("kitchen_notifications", [])
    kn_n = len(kn) if isinstance(kn, list) else 0
    _restaurant_save("kitchen_notifications", [])
    stats["kitchenNotificationsCleared"] = kn_n

    if clear_delivery:
        tickets = _delivery_tickets_load()
        _delivery_tickets_save([])
        stats["deliveryTicketsCleared"] = len(tickets)
    else:
        stats["deliveryTicketsCleared"] = 0

    kids = _restaurant_load("kids_area_sessions", [])
    if isinstance(kids, list):
        stats["kidsSessionsCleared"] = len(kids)
        _restaurant_save("kids_area_sessions", [])
    else:
        stats["kidsSessionsCleared"] = 0

    if clear_invoices:
        inv = _restaurant_load("invoices", [])
        inv_n = len(inv) if isinstance(inv, list) else 0
        _restaurant_save("invoices", [])
        stats["invoicesCleared"] = inv_n
    else:
        stats["invoicesCleared"] = 0

    # سجل تدقيق جديد ليوم نظيف (بعد المسح)
    _restaurant_save("session_audit", [])
    _append_session_audit_entry(
        {
            "at": now_iso,
            "action": "ops_day_reset",
            "sessionId": None,
            "tableId": None,
            "reason": reason_txt,
            "actorId": str(actor.get("id") or "") or None,
            "actorLogin": str(actor.get("login") or "") or None,
            "actorRole": str(actor.get("role") or "") or None,
            "stats": {k: v for k, v in stats.items() if k != "at"},
        }
    )
    stats["sessionAuditReset"] = True

    cache_invalidate_restaurant()
    cache_delete_pattern("mat3am:restaurant:operational-snapshot:*")
    cache_delete_pattern("mat3am:restaurant:order-taker-bootstrap:*")
    cache_delete_pattern("mat3am:restaurant:role-inbox:*")
    return {"ok": True, **stats}


@app.post("/api/restaurant/ops-day-reset")
@_with_restaurant_table_sessions_lock
@_with_restaurant_orders_lock
def restaurant_ops_day_reset(body: dict):
    """بدء يوم عمل نظيف: مسح الجلسات/الطلبات/الموافقات/التنبيهات وإرجاع الطاولات لجاهزة."""
    if not isinstance(body, dict):
        body = {}
    _terminal_require_user(body.get("mat3amActor"))
    actor = _mat3am_actor_from_body(body)
    if not str(actor.get("id") or "").strip():
        raise HTTPException(status_code=400, detail="mat3amActor.id مطلوب")
    if not _role_has_manager_ops_access(str(actor.get("role") or "").strip().lower()):
        raise HTTPException(status_code=403, detail="تصفير يوم العمل لمدير التشغيل أو المدير أو المطوّر فقط.")
    if str(body.get("confirm") or "").strip() != "RESET_DAY":
        raise HTTPException(
            status_code=400,
            detail='للتأكيد أرسل confirm: \"RESET_DAY\" — العملية تمسح الجلسات والموافقات والتنبيهات.',
        )
    return _restaurant_ops_day_reset(
        purge_history=bool(body.get("purgeHistory", True)),
        clear_delivery=bool(body.get("clearDelivery", True)),
        clear_invoices=bool(body.get("clearInvoices", False)),
        actor=actor,
        reason=str(body.get("reason") or "").strip(),
    )


@app.post("/api/restaurant/tables/{table_id}/reset")
@_with_restaurant_table_sessions_lock
@_with_restaurant_orders_lock
def restaurant_force_reset_table(table_id: str, body: dict):
    """Reset للطاولة على مستوى table_id حتى لو لم تعد هناك جلسة نشطة ظاهرة."""
    if not isinstance(body, dict):
        body = {}
    _terminal_require_user(body.get("mat3amActor"))
    actor = _mat3am_actor_from_body(body)
    if not str(actor.get("id") or "").strip():
        raise HTTPException(status_code=400, detail="mat3amActor.id مطلوب")
    if not _role_has_manager_ops_access(str(actor.get("role") or "").strip().lower()):
        raise HTTPException(status_code=403, detail="Reset للطاولة لمدير التشغيل أو المدير أو المطوّر فقط.")
    tid = str(table_id or "").strip()
    if not tid:
        raise HTTPException(status_code=400, detail="tableId مطلوب")
    reason = str(body.get("reason") or "").strip()
    now_iso = datetime.now().isoformat()
    reset_result = _restaurant_force_reset_table(tid, reason=reason, actor=actor)
