        cur = conn.cursor()
        cur.execute(
            "SELECT TOP 1 GroupName FROM dbo.TBL006 WHERE CardGuide = CAST(? AS uniqueidentifier)",
            (pg,),
        )
        if not cur.fetchone():
            raise HTTPException(status_code=404, detail="الباقة غير موجودة")
        sets = []
        params = []
        if body.get("name") is not None:
            sets.append("GroupName = ?")
