@app.post("/api/restaurant/kids-area/sessions/{session_id}/close")
def restaurant_kids_area_session_close(session_id: str, body: dict):
    if not isinstance(body, dict):
        body = {}
    mode = str(body.get("paymentMode") or "cash").strip().lower()
    sessions = _kids_area_load_sessions()
    if not isinstance(sessions, list):
        sessions = []
    settings = _kids_area_load_settings()
    for s in sessions:
        if not isinstance(s, dict) or str(s.get("id")) != session_id:
            continue
        if str(s.get("status") or "") != "active":
            raise HTTPException(status_code=409, detail="الجلسة مغلقة مسبقاً")
        exit_at = datetime.now().isoformat()
        t0 = _kids_area_parse_iso(str(s.get("entryAt") or ""))
        t1 = _kids_area_parse_iso(exit_at)
        hours = 0.0
        if t0 and t1:
            hours = max(0.0, (t1 - t0).total_seconds() / 3600.0)
        pph = _kids_area_package_price(settings, str(s.get("packageId") or ""))
        area_fee = round(hours * pph, 2)
        sales = s.get("salesLines") if isinstance(s.get("salesLines"), list) else []
        sales_total = 0.0
        for ln in sales:
            if not isinstance(ln, dict):
                continue
            sales_total += float(ln.get("quantity") or 0) * float(ln.get("unitPrice") or 0)
        sales_total = round(sales_total, 2)
        grand = round(area_fee + sales_total, 2)
        s["exitAt"] = exit_at
        s["status"] = "closed"
        s["areaFeeComputed"] = area_fee
        s["hoursComputed"] = round(hours, 4)
        s["salesTotal"] = sales_total
        s["grandTotal"] = grand
        pays = s.get("payments")
        if not isinstance(pays, list):
            pays = []
            s["payments"] = pays
        pay_note = ""
        if mode == "table":
            ts_id = str(body.get("tableSessionId") or s.get("linkedTableSessionId") or "").strip()
            if not ts_id:
                raise HTTPException(status_code=400, detail="tableSessionId مطلوب للتحويل للطاولة")
            tdata = _restaurant_load("table_sessions", [])
            if not isinstance(tdata, list):
                tdata = []
            ts = None
            for t in tdata:
                if isinstance(t, dict) and str(t.get("id")) == ts_id:
                    ts = t
                    break
            if not ts:
                raise HTTPException(status_code=404, detail="جلسة الطاولة غير موجودة")
            if str(ts.get("status") or "") != "active":
                raise HTTPException(status_code=409, detail="جلسة الطاولة ليست نشطة")
            table_id = str(ts.get("tableId") or "")
            ch = str(s.get("childName") or "")
            items = [
                {
                    "name": f"[Kids Area] أجر منطقة الأطفال — {ch} ({hours:.2f} ساعة)",
                    "quantity": 1,
                    "unitPrice": area_fee,
                    "productGuide": "",
                }
            ]
            for ln in sales:
                if not isinstance(ln, dict):
                    continue
                items.append(
                    {
                        "name": f"[Kids Area] {ln.get('name') or 'مبيعات'}",
                        "quantity": float(ln.get("quantity") or 1),
                        "unitPrice": float(ln.get("unitPrice") or 0),
                        "productGuide": str(ln.get("productGuide") or ""),
                    }
                )
            ord_data = _restaurant_load("orders", [])
            if not isinstance(ord_data, list):
                ord_data = []
            payload = {
                "sessionId": ts_id,
                "tableId": table_id,
                "tableGuid": table_id,
                "tableLabel": table_id,
                "items": items,
            }
            _kds_upsert_table_order(ord_data, payload)
            _restaurant_save("orders", ord_data)
            _mark_session_first_order_delay(ts_id)
            pays.append({"kind": "table", "amount": grand, "tableSessionId": ts_id, "at": exit_at})
            pay_note = "تم تحويل المبلغ إلى طلب الطاولة"
        else:
            pays.append({"kind": "cash", "amount": grand, "at": exit_at})
            pay_note = "تم تسجيل إغلاق نقدي (لا يُدمج مع الطاولة)"
        _kids_area_save_sessions(sessions)
        return {"session": s, "message": pay_note}
    raise HTTPException(status_code=404, detail="الجلسة غير موجودة")


@app.post("/api/restaurant/orders")
def restaurant_create_order(body: dict):
    """إنشاء طلب"""
    data = _restaurant_load("orders", [])
    if not isinstance(data, list):
        data = []
    incoming_items = [_kds_normalize_item(x) for x in (body.get("items") or []) if isinstance(x, dict)]
    session_id = str(body.get("sessionId") or "")
    table_id = str(body.get("tableId") or "")
    if session_id:
        session_row = _restaurant_find_session_row(session_id)
        if isinstance(session_row, dict):
            _restaurant_sync_session_customer_state(session_row)
            if session_row.get("guestApprovalPending"):
                raise HTTPException(status_code=409, detail="بانتظار موافقة المدير لتحويل الجلسة إلى ضيف صالة قبل إرسال أول طلب.")
    # دمج تلقائي: لو في طلب مفتوح لنفس الطاولة/الجلسة نضيف عليه بدل إنشاء تذكرة جديدة
    for ex in reversed(data):
        if not isinstance(ex, dict):
            continue
        if str(ex.get("status") or "").lower() in ("served", "paid", "cancelled"):
            continue
        same_session = session_id and str(ex.get("sessionId") or "") == session_id
        same_table = table_id and str(ex.get("tableId") or "") == table_id
        # عند توفر sessionId لا ندمج إلا على نفس الجلسة.
        can_merge = bool(same_session) if session_id else bool(same_table)
        if not can_merge:
            continue
        ex["items"] = _kds_merge_items(ex.get("items") or [], incoming_items)
        _kds_apply_captain_fields(
            ex,
            _kds_resolve_captain_fields(body=body, session_id=session_id or str(ex.get("sessionId") or "")),
        )
        ex["updatedAt"] = datetime.now().isoformat()
        _kds_refresh_order_status(ex)
        # تأكد من وجود prepTargetMinutes بعد الدمج — استخدم KDS defaults كـ fallback
        if not ex.get("prepTargetMinutes"):
            kds_defaults = _restaurant_read_kds_settings()
            ex["prepTargetMinutes"] = _kds_compute_order_target_minutes(ex.get("items") or [], kds_defaults.get("prepTargetMinutes"))
        _restaurant_save("orders", data)
        _mark_session_first_order_delay(session_id or ex.get("sessionId") or "")
        _restaurant_mark_session_customer_type_locked(session_id or ex.get("sessionId") or "")
        cache_delete_pattern("mat3am:restaurant:operational-snapshot:*")
        cache_delete_pattern("mat3am:restaurant:order-taker-bootstrap:*")
        return ex

    oid = str(uuid.uuid4())
    ptm = body.get("prepTargetMinutes")
    try:
        ptm_f = float(ptm) if ptm is not None and str(ptm).strip() != "" else None
    except (TypeError, ValueError):
        ptm_f = None
    if ptm_f is not None and (ptm_f < 1 or ptm_f > 240):
        ptm_f = None
    # استخدام KDS defaults كـ fallback إذا لم يُرسل prepTargetMinutes
    if ptm_f is None:
        kds_defaults = _restaurant_read_kds_settings()
        ptm_f = _kds_compute_order_target_minutes(incoming_items, kds_defaults.get("prepTargetMinutes"))
    rec = {
        "id": oid,
        "sessionId": session_id or body.get("sessionId"),
        "tableId": table_id or body.get("tableId"),
        "tableGuid": body.get("tableGuid") or body.get("tableId"),
        "tableLabel": body.get("tableLabel") or body.get("tableName") or body.get("tableId"),
        "waiterId": body.get("waiterId"),
        "items": incoming_items,
        "status": "pending",
        "createdAt": _mat3am_now_iso(),
        "prepTargetMinutes": ptm_f,
        "ticketNo": _restaurant_next_kds_ticket_no(data),
    }
    _kds_apply_captain_fields(rec, _kds_resolve_captain_fields(body=body, session_id=str(rec.get("sessionId") or "")))
    data.append(rec)
    _restaurant_save("orders", data)
    _mark_session_first_order_delay(session_id or rec.get("sessionId") or "")
    _restaurant_mark_session_customer_type_locked(session_id or rec.get("sessionId") or "")
    cache_delete_pattern("mat3am:restaurant:operational-snapshot:*")
    cache_delete_pattern("mat3am:restaurant:order-taker-bootstrap:*")
    return rec

@app.patch("/api/restaurant/orders/{order_id}/status")
def restaurant_update_order_status(order_id: str, body: dict):
    status = (body.get("status") or "").strip().lower()
    allowed = {"pending", "preparing", "ready", "served", "paid", "cancelled"}
    if status not in allowed:
        raise HTTPException(status_code=400, detail=f"حالة غير مدعومة: {status}")
    data = _restaurant_load("orders", [])
    for o in data:
        if o.get("id") == order_id:
            prev = str(o.get("status") or "").lower()
            if status == "cancelled" and prev not in ("pending",):
                raise HTTPException(
                    status_code=409,
                    detail="لا يمكن الإلغاء بعد بدء التحضير في المطبخ.",
                )
            o["status"] = status
            if status == "preparing":
                o["prepStartTime"] = datetime.now().isoformat()
            elif status == "ready":
                now_iso = datetime.now().isoformat()
                o["prepEndTime"] = now_iso
                # تثبيت "جاهز للتسليم": نعلّم كل البنود كـ prepared/ready
                # حتى لا تعيد _kds_refresh_order_status الطلب إلى pending في القراءة التالية.
                items = [_kds_normalize_item(x) for x in (o.get("items") or []) if isinstance(x, dict)]
                for it in items:
                    if bool(it.get("sent")):
                        continue
                    it["prepared"] = True
                    it["preparedQty"] = float(it.get("quantity") or 0)
                    it["lineStatus"] = "ready"
                    if not str(it.get("preparedAt") or "").strip():
                        it["preparedAt"] = now_iso
                o["items"] = items
                # دليفري: حدّث التذكرة + تنبيه الكاشير
                try:
                    sid = str(o.get("sessionId") or "")
                    tid = str(o.get("deliveryTicketId") or "").strip()
                    tickets = _delivery_tickets_load()
                    linked = None
                    for t in tickets:
                        if not isinstance(t, dict):
                            continue
                        if tid and str(t.get("id") or "") == tid:
                            linked = t
                            break
                        if sid and str(t.get("sessionId") or "") == sid:
                            linked = t
                            break
                        if str(t.get("orderId") or "") == str(o.get("id") or ""):
                            linked = t
                            break
                    if linked or sid.startswith("delivery:") or str(o.get("tableId") or "").upper() == "DELIVERY":
                        _delivery_notify_ready(o, linked)
                        if linked:
                            _delivery_tickets_save(tickets)
                except Exception as _deliv_ready_err:
                    print("[mat3am] delivery ready hook:", _deliv_ready_err)
            elif status in ("served", "paid"):
                # تثبيت "تم التسليم": نعلّم كل البنود sent حتى لا يعيد
                # _kds_refresh_order_status الطلب إلى ready في القراءات اللاحقة.
                now_iso = datetime.now().isoformat()
                items = [_kds_normalize_item(x) for x in (o.get("items") or []) if isinstance(x, dict)]
                for it in items:
                    it["prepared"] = True
                    it["preparedQty"] = float(it.get("quantity") or 0)
                    it["sent"] = True
                    it["lineStatus"] = "sent"
                    if not str(it.get("preparedAt") or "").strip():
                        it["preparedAt"] = now_iso
                    if not str(it.get("sentAt") or "").strip():
                        it["sentAt"] = now_iso
                o["items"] = items
                if not str(o.get("completedAt") or "").strip():
                    o["completedAt"] = now_iso
                try:
                    created_dt = datetime.fromisoformat(str(o.get("createdAt") or ""))
                    done_dt = datetime.fromisoformat(str(o.get("completedAt") or ""))
                    o["kpiLeadMinutes"] = round(max(0.0, (done_dt - created_dt).total_seconds() / 60.0), 2)
                except Exception:
                    pass
            elif status == "cancelled":
                o["cancelledAt"] = datetime.now().isoformat()
            _restaurant_save("orders", data)
            return o
    raise HTTPException(status_code=404, detail="الطلب غير موجود")


@app.patch("/api/restaurant/orders/{order_id}/items/{line_id}")
def restaurant_update_order_line(order_id: str, line_id: str, body: dict):
    data = _restaurant_load("orders", [])
    for o in data:
        if not isinstance(o, dict):
            continue
        if str(o.get("id") or "") != str(order_id):
            continue
        items = [_kds_normalize_item(x) for x in (o.get("items") or []) if isinstance(x, dict)]
        found = None
        for it in items:
            if str(it.get("lineId") or "") == str(line_id):
                found = it
                break
        if not found:
            lid = str(line_id or "").strip()
            prefix = f"{order_id}-"
            if lid.startswith(prefix):
                try:
                    pos = int(lid[len(prefix):])
                except Exception:
                    pos = -1
                if 0 <= pos < len(items):
                    found = items[pos]
        if not found:
            raise HTTPException(status_code=404, detail="سطر الطلب غير موجود")
        session_id = str(o.get("sessionId") or "").strip()
        if "seatNo" in (body or {}):
            if str(o.get("status") or "").lower() in ("paid", "cancelled"):
                raise HTTPException(status_code=409, detail="لا يمكن تغيير مقعد هذا السطر بعد إغلاق الطلب.")
            sess_data = _restaurant_load("table_sessions", [])
            sess_row = next(
                (
                    s
                    for s in (sess_data if isinstance(sess_data, list) else [])
                    if isinstance(s, dict) and str(s.get("id") or "").strip() == session_id
                ),
                None,
            )
            if isinstance(sess_row, dict) and str(sess_row.get("billingRequestedAt") or "").strip():
                raise HTTPException(status_code=409, detail="لا يمكن إعادة توزيع البنود بعد طلب الحساب.")
            raw_seat = body.get("seatNo")
            if raw_seat in (None, "", 0, "0"):
                found["seatNo"] = None
            else:
                try:
                    seat_no = int(raw_seat)
                except Exception:
                    raise HTTPException(status_code=400, detail="رقم المقعد غير صالح.")
                if seat_no < 1 or seat_no > 13:
                    raise HTTPException(status_code=400, detail="رقم المقعد يجب أن يكون بين 1 و13.")
                found["seatNo"] = seat_no
        if body and body.get("cancelled") in (True, "1", "true", 1, "yes"):
            if bool(found.get("cancelled")):
                o["items"] = items
                _kds_refresh_order_status(o)
                _restaurant_save("orders", data)
                return {"ok": True, "order": o, "line": found}
            if bool(found.get("prepared")) or bool(found.get("sent")):
                raise HTTPException(
                    status_code=409,
                    detail="لا يمكن إلغاء السطر بعد بدء التحضير أو التسليم.",
                )
            if str(o.get("status") or "").lower() in ("served", "paid", "cancelled"):
                raise HTTPException(status_code=409, detail="لا يمكن تعديل بنود هذا الطلب.")
            found["cancelled"] = True
            found["lineStatus"] = "cancelled"
            found["cancelledAt"] = datetime.now().isoformat()
            found["prepared"] = False
            found["preparedQty"] = 0.0
            found["sent"] = False
            o["items"] = items
            _kds_refresh_order_status(o)
            _restaurant_save("orders", data)
            return {"ok": True, "order": o, "line": found}
        if "lineStatus" in (body or {}):
            wanted = str(body.get("lineStatus") or "").strip().lower()
            if wanted != "preparing":
                raise HTTPException(status_code=400, detail="lineStatus المدعوم حالياً هو preparing فقط.")
            if bool(found.get("cancelled")):
                raise HTTPException(status_code=409, detail="لا يمكن بدء تنفيذ سطر ملغي.")
            if bool(found.get("sent")) or str(found.get("lineStatus") or "").strip().lower() in ("ready", "sent"):
                raise HTTPException(status_code=409, detail="السطر جاهز/مرسل بالفعل.")
            now_iso = datetime.now().isoformat()
            found["lineStatus"] = "preparing"
            if not str(found.get("lineStartedAt") or "").strip():
                found["lineStartedAt"] = now_iso
            if not str(o.get("prepStartTime") or "").strip():
                o["prepStartTime"] = now_iso
        if "preparedQty" in (body or {}) or "preparedDelta" in (body or {}):
            qty = float(found.get("quantity") or 0)
            current_prepared_qty = float(found.get("preparedQty") or (qty if found.get("prepared") else 0))
            if "preparedDelta" in (body or {}):
                try:
                    next_prepared_qty = current_prepared_qty + float(body.get("preparedDelta") or 0)
                except Exception:
                    raise HTTPException(status_code=400, detail="preparedDelta غير صالح.")
            else:
                try:
                    next_prepared_qty = float(body.get("preparedQty") or 0)
                except Exception:
                    raise HTTPException(status_code=400, detail="preparedQty غير صالح.")
            if next_prepared_qty < 0:
                next_prepared_qty = 0.0
            if qty > 0:
                next_prepared_qty = min(qty, next_prepared_qty)
            found["preparedQty"] = next_prepared_qty
            found["prepared"] = qty > 0 and next_prepared_qty >= qty
            found["lineStatus"] = "ready" if found["prepared"] else ("preparing" if next_prepared_qty > 0 else "pending")
            found["preparedAt"] = datetime.now().isoformat() if next_prepared_qty > 0 else None
            if next_prepared_qty > 0 and not str(o.get("prepStartTime") or "").strip():
                o["prepStartTime"] = datetime.now().isoformat()
        if "prepared" in (body or {}):
            prepared = bool(body.get("prepared"))
            found["prepared"] = prepared
            found["preparedQty"] = float(found.get("quantity") or 0) if prepared else 0.0
            found["lineStatus"] = "ready" if prepared else "pending"
            found["preparedAt"] = datetime.now().isoformat() if prepared else None
            if prepared and not str(o.get("prepStartTime") or "").strip():
                o["prepStartTime"] = datetime.now().isoformat()
        if "sent" in (body or {}):
            sent = bool(body.get("sent"))
            found["sent"] = sent
            found["lineStatus"] = "sent" if sent else ("ready" if found.get("prepared") else "pending")
            found["sentAt"] = datetime.now().isoformat() if sent else None
        o["items"] = items
        _kds_refresh_order_status(o)
        _restaurant_save("orders", data)
        return {"ok": True, "order": o, "line": found}
    raise HTTPException(status_code=404, detail="الطلب غير موجود")


@app.post("/api/restaurant/orders/{order_id}/items/{line_id}/send")
def restaurant_send_order_line(order_id: str, line_id: str):
    data = _restaurant_load("orders", [])
    for o in data:
        if not isinstance(o, dict):
            continue
        if str(o.get("id") or "") != str(order_id):
            continue
        items = [_kds_normalize_item(x) for x in (o.get("items") or []) if isinstance(x, dict)]
        found = None
        for it in items:
            if str(it.get("lineId") or "") == str(line_id):
                found = it
                break
        if not found:
            lid = str(line_id or "").strip()
            prefix = f"{order_id}-"
            if lid.startswith(prefix):
                try:
                    pos = int(lid[len(prefix):])
                except Exception:
                    pos = -1
                if 0 <= pos < len(items):
                    found = items[pos]
        if not found:
            raise HTTPException(status_code=404, detail="سطر الطلب غير موجود")
        if not bool(found.get("prepared")):
            raise HTTPException(status_code=409, detail="لا يمكن الإرسال قبل تأكيد التحضير")
        now_iso = datetime.now().isoformat()
        needs_runner = _workflow_kitchen_needs_runner()
        if needs_runner:
            # مسار استلام: جاهز لطابور المناولة/الدور المحدد — ليس بعد على الطاولة
            found["sent"] = False
            found["lineStatus"] = "ready"
            found["handoffAt"] = now_iso
            found["sentAt"] = None
        else:
            # لا أحد / نافذة الشيف: بإنهاء المطبخ تذهب مباشرة للطاولة
            found["sent"] = True
            found["lineStatus"] = "sent"
            found["handoffAt"] = now_iso
            found["sentAt"] = now_iso
        o["items"] = items
        _kds_refresh_order_status(o)
        _restaurant_save("orders", data)
        return {
            "ok": True,
            "order": o,
            "line": found,
            "deliveryPath": "runner" if needs_runner else "direct_to_table",
            "deliverFromKitchenBy": _workflow_role_for("pickup_kitchen"),
        }
    raise HTTPException(status_code=404, detail="الطلب غير موجود")


@app.post("/api/restaurant/orders/finish-table")
def restaurant_finish_table_orders(body: dict):
    """
    إنهاء يدوي من المطبخ لكل أصناف طاولة معينة (أو قائمة طلبات).
    يُبقي المسار الحالي للبنود الفردية؛ هذا مسار إضافي دفعة واحدة.
    - إن وُجد مستلم من المطبخ → البنود تصبح ready + handoff لطابور التسليم
    - إن كان «لا أحد» → البنود تُرسل مباشرة للطاولة (served)
    """
    if not isinstance(body, dict):
        raise HTTPException(status_code=400, detail="يتوقع JSON")
    table_key = str(body.get("tableId") or body.get("tableLabel") or body.get("table") or "").strip()
    order_ids_raw = body.get("orderIds")
    order_ids = [str(x).strip() for x in order_ids_raw if str(x).strip()] if isinstance(order_ids_raw, list) else []
    if not table_key and not order_ids:
        raise HTTPException(status_code=400, detail="tableId أو orderIds مطلوب")

    data = _restaurant_load("orders", [])
    if not isinstance(data, list):
        data = []
    now_iso = datetime.now().isoformat()
    needs_runner = _workflow_kitchen_needs_runner()
    touched = []
    lines_done = 0

    def _table_match(o: dict) -> bool:
        if not table_key:
            return False
        tid = str(o.get("tableId") or "").strip()
        tlab = str(o.get("tableLabel") or "").strip()
        tguid = str(o.get("tableGuid") or "").strip()
        keys = {table_key, table_key.upper(), table_key.lower()}
        for cand in (tid, tlab, tguid):
            if cand and (cand in keys or cand.upper() in keys or cand.lower() in keys):
                return True
        # مطابقة مرنة: «طاولة 5» / «T5» / «5»
        norm = re.sub(r"\s+", "", table_key.lower().replace("طاولة", "").replace("table", ""))
        for cand in (tid, tlab):
            cn = re.sub(r"\s+", "", str(cand or "").lower().replace("طاولة", "").replace("table", ""))
            if norm and cn and (norm == cn or norm in cn or cn in norm):
                return True
        return False

    for o in data:
        if not isinstance(o, dict):
            continue
        oid = str(o.get("id") or "").strip()
        st = str(o.get("status") or "").lower()
        if st in ("served", "paid", "cancelled"):
            continue
        if order_ids:
            if oid not in order_ids:
                continue
        elif not _table_match(o):
            continue
        items = [_kds_normalize_item(x) for x in (o.get("items") or []) if isinstance(x, dict)]
        changed = False
        for it in items:
            if bool(it.get("cancelled")):
                continue
            if bool(it.get("sent")) or str(it.get("lineStatus") or "").lower() == "sent":
                continue
            qty = float(it.get("quantity") or 0)
            it["prepared"] = True
            it["preparedQty"] = qty
            if not str(it.get("preparedAt") or "").strip():
                it["preparedAt"] = now_iso
            if needs_runner:
                it["sent"] = False
                it["lineStatus"] = "ready"
                it["handoffAt"] = now_iso
                it["sentAt"] = None
            else:
                it["sent"] = True
                it["lineStatus"] = "sent"
                it["handoffAt"] = now_iso
                it["sentAt"] = now_iso
            lines_done += 1
            changed = True
        if changed:
            o["items"] = items
            if not str(o.get("prepStartTime") or "").strip():
                o["prepStartTime"] = now_iso
            _kds_refresh_order_status(o)
            touched.append(
                {
                    "orderId": oid,
                    "tableId": o.get("tableId"),
                    "tableLabel": o.get("tableLabel"),
                    "status": o.get("status"),
                }
            )

    if not touched:
        raise HTTPException(status_code=404, detail="لا طلبات مفتوحة مطابقة لهذه الطاولة")
    _restaurant_save("orders", data)
    return {
        "ok": True,
        "ordersUpdated": len(touched),
        "linesFinished": lines_done,
        "deliveryPath": "runner" if needs_runner else "direct_to_table",
        "deliverFromKitchenBy": _workflow_role_for("pickup_kitchen"),
        "orders": touched,
    }


@app.post("/api/restaurant/orders/normalize-table-labels")
def restaurant_normalize_order_table_labels():
    """
    تنظيف الطلبات القديمة:
    - تحويل tableLabel من GUID إلى اسم/رقم طاولة فعلي (مثل T20)
    - حفظ النتيجة في orders.json بشكل دائم.
    """
    data = _restaurant_load("orders", [])
    if not isinstance(data, list):
        data = []
    guid_re = re.compile(r"^[0-9a-fA-F-]{36}$")
    labels: dict[str, str] = {}

    # 1) محاولة من floor_plan (linkedTableId -> label)
    try:
        fp_raw = _restaurant_load("floor_plan", {})
        fp_doc = fp_raw.get("plan") if isinstance(fp_raw, dict) and isinstance(fp_raw.get("plan"), dict) else fp_raw
        floors = []
        if isinstance(fp_doc, dict) and isinstance(fp_doc.get("floors"), list):
            floors = [f for f in fp_doc.get("floors") or [] if isinstance(f, dict)]
        elif isinstance(fp_doc, dict):
            floors = [fp_doc]
        for f in floors:
            for t in f.get("tables") or []:
                if not isinstance(t, dict):
                    continue
                lid = str(t.get("linkedTableId") or "").strip()
                lab = str(t.get("label") or "").strip()
                if lid and lab:
                    labels[lid.upper()] = lab
    except Exception:
        pass

    # 2) fallback من TBL005
    conn = get_connection()
    if conn:
        try:
            cursor = conn.cursor()
            for o in data:
                if not isinstance(o, dict):
                    continue
                tid = str(o.get("tableGuid") or o.get("tableId") or "").strip()
                if not tid or not guid_re.match(tid):
                    continue
                if labels.get(tid.upper()):
                    continue
                cursor.execute(
                    """
                    SELECT TOP 1 CostCenter, CardCode
                    FROM TBL005
                    WHERE CardGuide = CAST(? AS uniqueidentifier)
                    """,
                    (tid,),
                )
                rr = cursor.fetchone()
                if rr:
                    lbl = str(rr[0] or "").strip() or (f"#{str(rr[1] or '').strip()}" if rr[1] is not None else "")
                    if lbl:
                        labels[tid.upper()] = lbl
        finally:
            try:
                conn.close()
            except Exception:
                pass

    changed = 0
    for o in data:
        if not isinstance(o, dict):
            continue
        tid = str(o.get("tableGuid") or o.get("tableId") or "").strip()
        if not tid or not guid_re.match(tid):
            continue
        current = str(o.get("tableLabel") or "").strip()
        if current and not guid_re.match(current):
            continue
        lbl = labels.get(tid.upper())
        if not lbl:
            continue
        o["tableGuid"] = tid
        o["tableLabel"] = lbl
        changed += 1

    if changed:
        _restaurant_save("orders", data)
    return {"ok": True, "updated": changed, "totalOrders": len(data)}

